insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-aesop-for-children', 'Freerange Library', 'publisher', true, 'The Aesop for Children', array['reading', 'writing']::text[], 0, 3, array['charlotte_mason', 'classical', 'traditional']::text[], 'online', 0, 'The classic 1919 Aesop collection with Milo Winter''s beloved pictures: 147 short fables, each ending in a moral. Read three fables aloud, let your child tell them back, and copy one moral as handwriting practice. The full illustrated text is free online.', array['49 lessons in 7 units', 'All 147 fables, three per lesson', 'Narration and copywork every lesson', 'One question per fable with a kid-friendly answer', 'Link to the free illustrated text for every fable']::text[], 49, 3, 20, 'high', true, '{}'::text[], '🦊', '#E3A33B', false, '2026-11-11T12:00:00.000Z', 'pk-lib-aesop-for-children', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “The Aesop for Children, with Pictures by Milo Winter” by Aesop (illustrated by Milo Winter) (1919), in the public domain. Free full text: https://www.gutenberg.org/ebooks/19994', '[{"title":"Unit 1: Fables 1–21","lessons":["Lesson 1: The Wolf and the Kid, The Tortoise and the Ducks, The Young Crab and His Mother","Lesson 2: The Frogs and the Ox, The Dog, the Cock, and the Fox, Belling the Cat","Lesson 3: The Eagle and the Jackdaw, The Boy and the Filberts, Hercules and the Wagoner","Lesson 4: The Kid and the Wolf, The Town Mouse and the Country Mouse, The Fox and the Grapes","Lesson 5: The Bundle of Sticks, The Wolf and the Crane, The Ass and His Driver","Lesson 6: The Oxen and the Wheels, The Lion and the Mouse, The Shepherd Boy and the Wolf","Lesson 7: The Gnat and the Bull, The Plane Tree, The Farmer and the Stork"]},{"title":"Unit 2: Fables 22–42","lessons":["Lesson 8: The Sheep and the Pig, The Travelers and the Purse, The Lion and the Ass","Lesson 9: The Frogs Who Wished for a King, The Owl and the Grasshopper, The Wolf and His Shadow","Lesson 10: The Oak and the Reeds, The Rat and the Elephant, The Boys and the Frogs","Lesson 11: The Crow and the Pitcher, The Ants and the Grasshopper, The Ass Carrying the Image","Lesson 12: A Raven and a Swan, The Two Goats, The Ass and the Load of Salt","Lesson 13: The Lion and the Gnat, The Leap at Rhodes, The Cock and the Jewel","Lesson 14: The Monkey and the Camel, The Wild Boar and the Fox, The Ass, the Fox, and the Lion"]},{"title":"Unit 3: Fables 43–63","lessons":["Lesson 15: The Birds, the Beasts, and the Bat, The Lion, the Bear, and the Fox, The Wolf and the Lamb","Lesson 16: The Wolf and the Sheep, The Hares and the Frogs, The Fox and the Stork","Lesson 17: The Travelers and the Sea, The Wolf and the Lion, The Stag and His Reflection","Lesson 18: The Peacock, The Mice and the Weasels, The Wolf and the Lean Dog","Lesson 19: The Fox and the Lion, The Lion and the Ass, The Dog and His Master''s Dinner","Lesson 20: The Vain Jackdaw and His Borrowed Feathers, The Monkey and the Dolphin, The Wolf and the Ass","Lesson 21: The Monkey and the Cat, The Dogs and the Fox, The Dogs and the Hides"]},{"title":"Unit 4: Fables 64–84","lessons":["Lesson 22: The Rabbit, the Weasel, and the Cat, The Bear and the Bees, The Fox and the Leopard","Lesson 23: The Heron, The Cock and the Fox, The Dog in the Manger","Lesson 24: The Wolf and the Goat, The Ass and the Grasshoppers, The Mule","Lesson 25: The Fox and the Goat, The Cat, the Cock, and the Young Mouse, The Wolf and the Shepherd","Lesson 26: The Peacock and the Crane, The Farmer and the Cranes, The Farmer and His Sons","Lesson 27: The Two Pots, The Goose and the Golden Egg, The Fighting Bulls and the Frog","Lesson 28: The Mouse and the Weasel, The Farmer and the Snake, The Sick Stag"]},{"title":"Unit 5: Fables 85–105","lessons":["Lesson 29: The Goatherd and the Wild Goats, The Spendthrift and the Swallow, The Cat and the Birds","Lesson 30: The Dog and the Oyster, The Astrologer, Three Bullocks and a Lion","Lesson 31: Mercury and the Woodman, The Frog and the Mouse, The Fox and the Crab","Lesson 32: The Serpent and the Eagle, The Wolf in Sheep''s Clothing, The Bull and the Goat","Lesson 33: The Eagle and the Beetle, The Old Lion and the Fox, The Man and the Lion","Lesson 34: The Ass and the Lap Dog, The Milkmaid and Her Pail, The Wolf and the Shepherd","Lesson 35: The Goatherd and the Goat, The Miser, The Wolf and the House Dog"]},{"title":"Unit 6: Fables 106–126","lessons":["Lesson 36: The Fox and the Hedgehog, The Bat and the Weasels, The Quack Toad","Lesson 37: The Fox Without a Tail, The Mischievous Dog, The Rose and the Butterfly","Lesson 38: The Cat and the Fox, The Boy and the Nettle, The Old Lion","Lesson 39: The Fox and the Pheasants, Two Travelers and a Bear, The Porcupine and the Snakes","Lesson 40: The Fox and the Monkey, The Mother and the Wolf, The Flies and the Honey","Lesson 41: The Eagle and the Kite, The Stag, the Sheep, and the Wolf, The Animals and the Plague","Lesson 42: The Shepherd and the Lion, The Dog and His Reflection, The Hare and the Tortoise"]},{"title":"Unit 7: Fables 127–147","lessons":["Lesson 43: The Bees and Wasps, and the Hornet, The Lark and Her Young Ones, The Cat and the Old Rat","Lesson 44: The Fox and the Crow, The Ass and Its Shadow, The Miller, His Son, and the Ass","Lesson 45: The Ant and the Dove, The Man and the Satyr, The Wolf, the Kid, and the Goat","Lesson 46: The Swallow and the Crow, Jupiter and the Monkey, The Lion, the Ass, and the Fox","Lesson 47: The Lion''s Share, The Mole and His Mother, The North Wind and the Sun","Lesson 48: The Hare and His Ears, The Wolves and the Sheep, The Cock and the Fox","Lesson 49: The Ass in the Lion''s Skin, The Fisherman and the Little Fish, The Fighting Cocks and the Eagle"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-aesop-for-children', 1, '{"units":[{"id":"aesop-for-children-u1","title":"Unit 1: Fables 1–21","lessons":[{"id":"aesop-for-children-1-1","title":"Lesson 1: The Wolf and the Kid, The Tortoise and the Ducks, The Young Crab and His Mother","steps":["Read aloud: The Wolf and the Kid, The Tortoise and the Ducks, The Young Crab and His Mother","After each fable, have your child tell it back in their own words","Copy the moral of \"The Wolf and the Kid\" (younger children can trace it after you write it)","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Wolf and the Kid”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_KID"},{"label":"Read “The Tortoise and the Ducks”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TORTOISE_AND_THE_DUCKS"},{"label":"Read “The Young Crab and His Mother”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_YOUNG_CRAB_AND_HIS_MOTHER"}],"questions":["Why was the Wolf sorry he played music for the Kid?","Why did the Tortoise fall when the Ducks carried him?","What was wrong with the Mother Crab''s advice?"],"answers":["He forgot what he came to do. Don''t let anything distract you from what you set out to do.","He opened his mouth to show off. Showing off and being nosy can get you hurt.","She couldn''t walk straight herself. Show a good example before you tell others what to do."]},{"id":"aesop-for-children-1-2","title":"Lesson 2: The Frogs and the Ox, The Dog, the Cock, and the Fox, Belling the Cat","steps":["Read aloud: The Frogs and the Ox, The Dog, the Cock, and the Fox, Belling the Cat","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Dog, the Cock, and the Fox\" in your best handwriting","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Frogs and the Ox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FROGS_AND_THE_OX"},{"label":"Read “The Dog, the Cock, and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOG_THE_COCK_AND_THE_FOX"},{"label":"Read “Belling the Cat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#BELLING_THE_CAT"}],"questions":["What happened when the old Frog tried to puff up as big as the Ox?","How did the Cock trick the Fox who wanted to eat him?","Why did no Mouse want to put the bell on the Cat?"],"answers":["She burst. Don''t try to do something that can''t be done.","He sent the Fox around the tree to his friend the Dog. If you try to trick others, you may get tricked back.","It was too dangerous. Saying something should be done is easier than doing it."]},{"id":"aesop-for-children-1-3","title":"Lesson 3: The Eagle and the Jackdaw, The Boy and the Filberts, Hercules and the Wagoner","steps":["Read aloud: The Eagle and the Jackdaw, The Boy and the Filberts, Hercules and the Wagoner","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"Hercules and the Wagoner\" from dictation, then check it against the book","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Eagle and the Jackdaw”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_EAGLE_AND_THE_JACKDAW"},{"label":"Read “The Boy and the Filberts”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BOY_AND_THE_FILBERTS"},{"label":"Read “Hercules and the Wagoner”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#HERCULES_AND_THE_WAGONER"}],"questions":["Why couldn''t the Jackdaw carry off a ram like the Eagle?","How could the Boy get his hand out of the pitcher?","What did Hercules tell the Farmer to do?"],"answers":["He wasn''t strong enough and got stuck. Don''t think you can do more than you really can.","Let go of some nuts. Don''t try to take too much at once.","Push the wheel himself. Try your best first, then you''ll get help."]},{"id":"aesop-for-children-1-4","title":"Lesson 4: The Kid and the Wolf, The Town Mouse and the Country Mouse, The Fox and the Grapes","steps":["Read aloud: The Kid and the Wolf, The Town Mouse and the Country Mouse, The Fox and the Grapes","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Kid and the Wolf\" and underline the most important word","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Kid and the Wolf”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_KID_AND_THE_WOLF"},{"label":"Read “The Town Mouse and the Country Mouse”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TOWN_MOUSE_AND_THE_COUNTRY_MOUSE"},{"label":"Read “The Fox and the Grapes”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_GRAPES"}],"questions":["Why could the Kid be rude to the Wolf from the roof?","Why did the Town Mouse''s friend go home to the country?","Why did the Fox say the grapes were sour?"],"answers":["He was safe up high. Don''t say mean things just because you feel safe.","The town was full of danger. A safe, simple life is better than fancy food and fear.","He couldn''t reach them. People sometimes pretend they don''t want what they can''t get."]},{"id":"aesop-for-children-1-5","title":"Lesson 5: The Bundle of Sticks, The Wolf and the Crane, The Ass and His Driver","steps":["Read aloud: The Bundle of Sticks, The Wolf and the Crane, The Ass and His Driver","After each fable, have your child tell it back in their own words","Copy the moral of \"The Wolf and the Crane\" (younger children can trace it after you write it)"],"links":[{"label":"Read “The Bundle of Sticks”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BUNDLE_OF_STICKS"},{"label":"Read “The Wolf and the Crane”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_CRANE"},{"label":"Read “The Ass and His Driver”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_AND_HIS_DRIVER"}],"questions":["Why couldn''t the sons break the bundle of sticks?","What \"reward\" did the Crane get for helping the Wolf?","What happened when the Ass wouldn''t listen to his driver?"],"answers":["The sticks were held together. We are strong when we stick together.","Only her life. Don''t expect thanks from someone mean.","He fell off the cliff. Listen to good advice from people who know better."]},{"id":"aesop-for-children-1-6","title":"Lesson 6: The Oxen and the Wheels, The Lion and the Mouse, The Shepherd Boy and the Wolf","steps":["Read aloud: The Oxen and the Wheels, The Lion and the Mouse, The Shepherd Boy and the Wolf","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Shepherd Boy and the Wolf\" in your best handwriting","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Oxen and the Wheels”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_OXEN_AND_THE_WHEELS"},{"label":"Read “The Lion and the Mouse”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_AND_THE_MOUSE"},{"label":"Read “The Shepherd Boy and the Wolf”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SHEPHERD_BOY_AND_THE_WOLF"}],"questions":["Who were working hardest, the Oxen or the creaking Wheels?","How did the little Mouse help the Lion?","Why didn''t the villagers come when the Boy really saw a wolf?"],"answers":["The Oxen. The ones who complain the most often have it easiest.","She chewed the net and set him free. Being kind is never wasted, even small friends can help.","He had lied too many times. People won''t believe a liar even when he tells the truth."]},{"id":"aesop-for-children-1-7","title":"Lesson 7: The Gnat and the Bull, The Plane Tree, The Farmer and the Stork","steps":["Read aloud: The Gnat and the Bull, The Plane Tree, The Farmer and the Stork","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Gnat and the Bull\" from dictation, then check it against the book","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Gnat and the Bull”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_GNAT_AND_THE_BULL"},{"label":"Read “The Plane Tree”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_PLANE_TREE"},{"label":"Read “The Farmer and the Stork”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FARMER_AND_THE_STORK"}],"questions":["Did the Bull even notice the Gnat on his horn?","What did the travelers call the tree that gave them shade?","Why did the Farmer punish the Stork too?"],"answers":["No. Some think they are very important when others hardly notice them.","Useless. People often forget to be thankful for the good things they have.","He was caught with the thieving Cranes. People judge you by the friends you are with."]}]},{"id":"aesop-for-children-u2","title":"Unit 2: Fables 22–42","lessons":[{"id":"aesop-for-children-2-1","title":"Lesson 8: The Sheep and the Pig, The Travelers and the Purse, The Lion and the Ass","steps":["Read aloud: The Sheep and the Pig, The Travelers and the Purse, The Lion and the Ass","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Travelers and the Purse\" and underline the most important word","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Sheep and the Pig”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SHEEP_AND_THE_PIG"},{"label":"Read “The Travelers and the Purse”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TRAVELERS_AND_THE_PURSE"},{"label":"Read “The Lion and the Ass”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_AND_THE_ASS"}],"questions":["Why did the Pig squeal so much more than the Sheep?","Why wouldn''t the man share the trouble with his friend?","What did the Lion do when the Ass made fun of him?"],"answers":["The Sheep would only lose wool but the Pig would be eaten. It''s easy to be brave when nothing bad will happen to you.","He wouldn''t share the purse. If you won''t share the good things, don''t expect help with the bad.","He ignored him and walked on. Don''t let a silly person''s words bother you."]},{"id":"aesop-for-children-2-2","title":"Lesson 9: The Frogs Who Wished for a King, The Owl and the Grasshopper, The Wolf and His Shadow","steps":["Read aloud: The Frogs Who Wished for a King, The Owl and the Grasshopper, The Wolf and His Shadow","After each fable, have your child tell it back in their own words","Copy the moral of \"The Wolf and His Shadow\" (younger children can trace it after you write it)","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Frogs Who Wished for a King”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FROGS_WHO_WISHED_FOR_A_KING"},{"label":"Read “The Owl and the Grasshopper”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_OWL_AND_THE_GRASSHOPPER"},{"label":"Read “The Wolf and His Shadow”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_HIS_SHADOW"}],"questions":["Were the Frogs happy with the king they asked for?","How did the Owl catch the Grasshopper?","Why was the Wolf caught by the Lion?"],"answers":["No, the Stork ate them. Make sure a change will really be better before you ask for it.","She praised his singing and offered him a treat. Watch out when an enemy says nice things.","He thought he was as big as his shadow. Don''t let pretending make you forget what''s real."]},{"id":"aesop-for-children-2-3","title":"Lesson 10: The Oak and the Reeds, The Rat and the Elephant, The Boys and the Frogs","steps":["Read aloud: The Oak and the Reeds, The Rat and the Elephant, The Boys and the Frogs","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Oak and the Reeds\" in your best handwriting"],"links":[{"label":"Read “The Oak and the Reeds”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_OAK_AND_THE_REEDS"},{"label":"Read “The Rat and the Elephant”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_RAT_AND_THE_ELEPHANT"},{"label":"Read “The Boys and the Frogs”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BOYS_AND_THE_FROGS"}],"questions":["Why did the Reeds survive the storm but the Oak fell?","What did the Cat show the proud Rat?","What did the Frog tell the Boys throwing stones?"],"answers":["The Reeds bent with the wind. Sometimes it''s wiser to bend than to be stubborn.","He was not as important as the Elephant. Being a little like someone great doesn''t make you great.","Your fun means death to us. Think about whether your fun hurts someone else."]},{"id":"aesop-for-children-2-4","title":"Lesson 11: The Crow and the Pitcher, The Ants and the Grasshopper, The Ass Carrying the Image","steps":["Read aloud: The Crow and the Pitcher, The Ants and the Grasshopper, The Ass Carrying the Image","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Ants and the Grasshopper\" from dictation, then check it against the book","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Crow and the Pitcher”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_CROW_AND_THE_PITCHER"},{"label":"Read “The Ants and the Grasshopper”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ANTS_AND_THE_GRASSHOPPER"},{"label":"Read “The Ass Carrying the Image”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_CARRYING_THE_IMAGE"}],"questions":["How did the Crow get a drink from the pitcher?","Why did the Ants refuse to feed the Grasshopper?","Who were the people really bowing to?"],"answers":["He dropped in pebbles until the water rose. When you''re stuck, think hard and you may find a way.","He played all summer instead of working. There is a time to work and a time to play.","The image, not the Ass. Don''t take credit for what belongs to someone else."]},{"id":"aesop-for-children-2-5","title":"Lesson 12: A Raven and a Swan, The Two Goats, The Ass and the Load of Salt","steps":["Read aloud: A Raven and a Swan, The Two Goats, The Ass and the Load of Salt","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Ass and the Load of Salt\" and underline the most important word","Act out one fable with toys or puppets"],"links":[{"label":"Read “A Raven and a Swan”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#A_RAVEN_AND_A_SWAN"},{"label":"Read “The Two Goats”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TWO_GOATS"},{"label":"Read “The Ass and the Load of Salt”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_AND_THE_LOAD_OF_SALT"}],"questions":["Did the Raven turn white by living like a Swan?","Why did both Goats fall into the river?","Why did the Ass''s trick fail the second time?"],"answers":["No, he just got thin. Changing what you do won''t change who you are.","Neither would let the other pass. Being stubborn can hurt everyone, so sometimes give way.","He carried sponges, not salt, so the load got heavier. A trick that worked once won''t work every time."]},{"id":"aesop-for-children-2-6","title":"Lesson 13: The Lion and the Gnat, The Leap at Rhodes, The Cock and the Jewel","steps":["Read aloud: The Lion and the Gnat, The Leap at Rhodes, The Cock and the Jewel","After each fable, have your child tell it back in their own words","Copy the moral of \"The Lion and the Gnat\" (younger children can trace it after you write it)","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Lion and the Gnat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_AND_THE_GNAT"},{"label":"Read “The Leap at Rhodes”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LEAP_AT_RHODES"},{"label":"Read “The Cock and the Jewel”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_COCK_AND_THE_JEWEL"}],"questions":["What happened to the Gnat after he beat the Lion?","How did the hearers answer the man who bragged about his big jump?","Why did the Cock not want the jewel?"],"answers":["A spider caught him. Don''t get so proud of winning that you stop being careful.","Jump it here and now. What you do counts more than what you brag about.","He couldn''t eat it. Something precious means nothing to someone who doesn''t care about it."]},{"id":"aesop-for-children-2-7","title":"Lesson 14: The Monkey and the Camel, The Wild Boar and the Fox, The Ass, the Fox, and the Lion","steps":["Read aloud: The Monkey and the Camel, The Wild Boar and the Fox, The Ass, the Fox, and the Lion","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Wild Boar and the Fox\" in your best handwriting","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Monkey and the Camel”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MONKEY_AND_THE_CAMEL"},{"label":"Read “The Wild Boar and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WILD_BOAR_AND_THE_FOX"},{"label":"Read “The Ass, the Fox, and the Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_THE_FOX_AND_THE_LION"}],"questions":["Why was the Camel chased away?","Why did the Boar sharpen his tusks with no enemy around?","What happened to the Fox after he betrayed the Ass?"],"answers":["He tried to dance like the Monkey and looked silly. Don''t copy others just to show off.","There''d be no time when danger came. Get ready before trouble comes.","The Lion ate him too. If you betray a friend, you may be betrayed."]}]},{"id":"aesop-for-children-u3","title":"Unit 3: Fables 43–63","lessons":[{"id":"aesop-for-children-3-1","title":"Lesson 15: The Birds, the Beasts, and the Bat, The Lion, the Bear, and the Fox, The Wolf and the Lamb","steps":["Read aloud: The Birds, the Beasts, and the Bat, The Lion, the Bear, and the Fox, The Wolf and the Lamb","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Wolf and the Lamb\" from dictation, then check it against the book"],"links":[{"label":"Read “The Birds, the Beasts, and the Bat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BIRDS_THE_BEASTS_AND_THE_BAT"},{"label":"Read “The Lion, the Bear, and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_THE_BEAR_AND_THE_FOX"},{"label":"Read “The Wolf and the Lamb”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_LAMB"}],"questions":["Why did the Bat end up with no friends?","Who got the kid that the Lion and Bear fought over?","Why did the Wolf eat the Lamb even though she did nothing wrong?"],"answers":["He kept switching sides. People who trick others end up alone.","The Fox. Sometimes those who do the work don''t get the reward.","He wanted to and made up excuses. A bully won''t listen to what''s fair."]},{"id":"aesop-for-children-3-2","title":"Lesson 16: The Wolf and the Sheep, The Hares and the Frogs, The Fox and the Stork","steps":["Read aloud: The Wolf and the Sheep, The Hares and the Frogs, The Fox and the Stork","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Wolf and the Sheep\" and underline the most important word","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Wolf and the Sheep”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_SHEEP"},{"label":"Read “The Hares and the Frogs”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_HARES_AND_THE_FROGS"},{"label":"Read “The Fox and the Stork”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_STORK"}],"questions":["Why wouldn''t the Sheep bring the Wolf a drink?","What made the Hares stop being so scared?","How did the Stork pay the Fox back?"],"answers":["She knew he would eat her. It''s easy to see through a sneaky person.","They saw Frogs afraid of them. Someone always has it worse than you.","She served food in a tall jar he couldn''t reach. Don''t play a trick you wouldn''t want played on you."]},{"id":"aesop-for-children-3-3","title":"Lesson 17: The Travelers and the Sea, The Wolf and the Lion, The Stag and His Reflection","steps":["Read aloud: The Travelers and the Sea, The Wolf and the Lion, The Stag and His Reflection","After each fable, have your child tell it back in their own words","Copy the moral of \"The Wolf and the Lion\" (younger children can trace it after you write it)","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Travelers and the Sea”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TRAVELERS_AND_THE_SEA"},{"label":"Read “The Wolf and the Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_LION"},{"label":"Read “The Stag and His Reflection”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_STAG_AND_HIS_REFLECTION"}],"questions":["What did the travelers find when the \"ship\" came in?","Why couldn''t the Wolf complain when the Lion took his lamb?","What did the Stag think of his legs and his antlers?"],"answers":["Only some sticks of wood. Don''t let wishing make you forget what''s real.","He stole it first. Something taken wrongly can be lost the same way.","He hated his legs and loved his antlers, but his legs saved him and his antlers trapped him. Useful things matter more than pretty things."]},{"id":"aesop-for-children-3-4","title":"Lesson 18: The Peacock, The Mice and the Weasels, The Wolf and the Lean Dog","steps":["Read aloud: The Peacock, The Mice and the Weasels, The Wolf and the Lean Dog","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Wolf and the Lean Dog\" in your best handwriting","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Peacock”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_PEACOCK"},{"label":"Read “The Mice and the Weasels”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MICE_AND_THE_WEASELS"},{"label":"Read “The Wolf and the Lean Dog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_LEAN_DOG"}],"questions":["Why did the Peacock''s beautiful tail make him unhappy?","Why were the Mouse leaders caught?","Why did the Wolf go away hungry from the lean Dog?"],"answers":["It was too heavy to fly. Don''t give up being free just for looking fancy.","Their fancy headdresses wouldn''t fit in the holes. Being important can come with dangers.","He believed the Dog''s promise to get fat first. Don''t trust promises from someone who wants to fool you."]},{"id":"aesop-for-children-3-5","title":"Lesson 19: The Fox and the Lion, The Lion and the Ass, The Dog and His Master''s Dinner","steps":["Read aloud: The Fox and the Lion, The Lion and the Ass, The Dog and His Master''s Dinner","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Fox and the Lion\" from dictation, then check it against the book","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Fox and the Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_LION"},{"label":"Read “The Lion and the Ass”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_AND_THE_ASS1"},{"label":"Read “The Dog and His Master''s Dinner”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOG_AND_HIS_MASTERS_DINNER"}],"questions":["Why did the Fox stop being afraid of the Lion?","Why wasn''t the Lion scared of the braying Ass?","Why did the Dog finally eat his master''s dinner?"],"answers":["He saw him many times. Getting used to something dangerous can make you forget it''s dangerous.","He knew the Ass was all noise. A loud bragger doesn''t scare those who know him.","He stopped to argue with the other dogs. Don''t stop to argue with temptation, just walk away."]},{"id":"aesop-for-children-3-6","title":"Lesson 20: The Vain Jackdaw and His Borrowed Feathers, The Monkey and the Dolphin, The Wolf and the Ass","steps":["Read aloud: The Vain Jackdaw and His Borrowed Feathers, The Monkey and the Dolphin, The Wolf and the Ass","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Monkey and the Dolphin\" and underline the most important word"],"links":[{"label":"Read “The Vain Jackdaw and His Borrowed Feathers”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_VAIN_JACKDAW_AND_HIS_BORROWED_FEATHERS"},{"label":"Read “The Monkey and the Dolphin”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MONKEY_AND_THE_DOLPHIN"},{"label":"Read “The Wolf and the Ass”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_ASS"}],"questions":["What happened when the Jackdaw wore peacock feathers?","Why did the Dolphin leave the Monkey?","How did the Ass escape the Wolf?"],"answers":["The Peacocks pulled them off and his own flock chased him. Wearing borrowed things doesn''t make you better.","The Monkey kept telling lies. One lie leads to another lie.","He tricked him into looking at his hoof and kicked him. Stick to what you are good at."]},{"id":"aesop-for-children-3-7","title":"Lesson 21: The Monkey and the Cat, The Dogs and the Fox, The Dogs and the Hides","steps":["Read aloud: The Monkey and the Cat, The Dogs and the Fox, The Dogs and the Hides","After each fable, have your child tell it back in their own words","Copy the moral of \"The Dogs and the Hides\" (younger children can trace it after you write it)","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Monkey and the Cat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MONKEY_AND_THE_CAT"},{"label":"Read “The Dogs and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOGS_AND_THE_FOX"},{"label":"Read “The Dogs and the Hides”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOGS_AND_THE_HIDES"}],"questions":["Who ate the chestnuts the Cat pulled from the fire?","Why did the Fox laugh at the Dogs tearing the lion skin?","Why did the Dogs burst?"],"answers":["The Monkey. A flatterer says nice things to get something from you.","They wouldn''t dare if the Lion were alive. It''s mean and easy to pick on someone who can''t fight back.","They tried to drink the whole stream. Don''t try to do impossible things."]}]},{"id":"aesop-for-children-u4","title":"Unit 4: Fables 64–84","lessons":[{"id":"aesop-for-children-4-1","title":"Lesson 22: The Rabbit, the Weasel, and the Cat, The Bear and the Bees, The Fox and the Leopard","steps":["Read aloud: The Rabbit, the Weasel, and the Cat, The Bear and the Bees, The Fox and the Leopard","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Rabbit, the Weasel, and the Cat\" in your best handwriting","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Rabbit, the Weasel, and the Cat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_RABBIT_THE_WEASEL_AND_THE_CAT"},{"label":"Read “The Bear and the Bees”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BEAR_AND_THE_BEES"},{"label":"Read “The Fox and the Leopard”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_LEOPARD"}],"questions":["Who won when the Rabbit and Weasel asked the Cat to judge?","Why did the Bear end up hiding in a pool?","What did the Fox say was real beauty?"],"answers":["The Cat, she grabbed them both. Be careful asking a strong bully to settle your fight.","He got angry at one bee and the whole swarm came. It''s better to put up with a small hurt than to make it worse by getting mad.","A clever mind, not a spotted coat. Looking fine outside doesn''t mean you''re clever inside."]},{"id":"aesop-for-children-4-2","title":"Lesson 23: The Heron, The Cock and the Fox, The Dog in the Manger","steps":["Read aloud: The Heron, The Cock and the Fox, The Dog in the Manger","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Cock and the Fox\" from dictation, then check it against the book","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Heron”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_HERON"},{"label":"Read “The Cock and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_COCK_AND_THE_FOX"},{"label":"Read “The Dog in the Manger”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOG_IN_THE_MANGER"}],"questions":["What did the Heron end up eating?","How did the Cock trick the Fox?","Why did the Dog keep the hay from the Cattle?"],"answers":["A tiny Snail. If you are too picky, you may end up with little or nothing.","He said dogs were coming. A trickster can be tricked too.","He was being mean, even though he couldn''t eat it. Don''t keep things from others that you can''t use yourself."]},{"id":"aesop-for-children-4-3","title":"Lesson 24: The Wolf and the Goat, The Ass and the Grasshoppers, The Mule","steps":["Read aloud: The Wolf and the Goat, The Ass and the Grasshoppers, The Mule","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Mule\" and underline the most important word","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Wolf and the Goat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_GOAT"},{"label":"Read “The Ass and the Grasshoppers”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_AND_THE_GRASSHOPPERS"},{"label":"Read “The Mule”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MULE"}],"questions":["Why didn''t the Goat come down for the Wolf''s grass?","What happened to the Ass who ate only dew?","What did the Mule remember when he got tired?"],"answers":["She knew he wanted to eat her. Don''t trust an invitation from someone who''s only thinking of himself.","He starved. You can''t change how nature works.","His father was a donkey. Don''t brag about your family unless you''re sure."]},{"id":"aesop-for-children-4-4","title":"Lesson 25: The Fox and the Goat, The Cat, the Cock, and the Young Mouse, The Wolf and the Shepherd","steps":["Read aloud: The Fox and the Goat, The Cat, the Cock, and the Young Mouse, The Wolf and the Shepherd","After each fable, have your child tell it back in their own words","Copy the moral of \"The Fox and the Goat\" (younger children can trace it after you write it)"],"links":[{"label":"Read “The Fox and the Goat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_GOAT"},{"label":"Read “The Cat, the Cock, and the Young Mouse”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_CAT_THE_COCK_AND_THE_YOUNG_MOUSE"},{"label":"Read “The Wolf and the Shepherd”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_SHEPHERD"}],"questions":["Why did the Goat end up stuck in the well?","Which animal was really dangerous to the young Mouse?","What happened when the Shepherd trusted the Wolf to guard the sheep?"],"answers":["He jumped in without thinking. Look before you leap.","The quiet Cat, not the noisy Cock. Don''t judge by how things look.","The Wolf ate them. A wolf is always a wolf."]},{"id":"aesop-for-children-4-5","title":"Lesson 26: The Peacock and the Crane, The Farmer and the Cranes, The Farmer and His Sons","steps":["Read aloud: The Peacock and the Crane, The Farmer and the Cranes, The Farmer and His Sons","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Farmer and the Cranes\" in your best handwriting","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Peacock and the Crane”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_PEACOCK_AND_THE_CRANE"},{"label":"Read “The Farmer and the Cranes”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FARMER_AND_THE_CRANES"},{"label":"Read “The Farmer and His Sons”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FARMER_AND_HIS_SONS"}],"questions":["How was the Crane better than the Peacock?","When did the Cranes really leave the field?","What treasure did the sons find in the vineyard?"],"answers":["He could fly high. Being useful matters more than looking pretty.","When the Farmer used real stones, not just pretend. Big talk doesn''t mean someone can''t really act.","A big harvest from digging. Hard work is a treasure itself."]},{"id":"aesop-for-children-4-6","title":"Lesson 27: The Two Pots, The Goose and the Golden Egg, The Fighting Bulls and the Frog","steps":["Read aloud: The Two Pots, The Goose and the Golden Egg, The Fighting Bulls and the Frog","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Fighting Bulls and the Frog\" from dictation, then check it against the book","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Two Pots”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_TWO_POTS"},{"label":"Read “The Goose and the Golden Egg”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_GOOSE_AND_THE_GOLDEN_EGG"},{"label":"Read “The Fighting Bulls and the Frog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FIGHTING_BULLS_AND_THE_FROG"}],"questions":["What happened when the brass and clay pots traveled together?","Why did the Countryman lose all his gold?","Why were the Frogs afraid of the bulls fighting?"],"answers":["The clay pot broke. Friends who are alike get along best.","He killed the goose to get all the eggs at once. Being greedy can make you lose everything.","The loser would run into the marsh and crush them. When big ones fight, little ones get hurt."]},{"id":"aesop-for-children-4-7","title":"Lesson 28: The Mouse and the Weasel, The Farmer and the Snake, The Sick Stag","steps":["Read aloud: The Mouse and the Weasel, The Farmer and the Snake, The Sick Stag","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Mouse and the Weasel\" and underline the most important word","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Mouse and the Weasel”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MOUSE_AND_THE_WEASEL"},{"label":"Read “The Farmer and the Snake”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FARMER_AND_THE_SNAKE"},{"label":"Read “The Sick Stag”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SICK_STAG"}],"questions":["Why couldn''t the Mouse get out of the basket?","What did the frozen Snake do after the Farmer warmed him?","Why did the Stag starve?"],"answers":["He ate too much and got fat. Being greedy gets you into trouble.","He bit the Farmer. Don''t trust someone who is wicked, even when you feel sorry for them.","His visitors ate all his food. Being a good friend means doing good, not just saying nice things."]}]},{"id":"aesop-for-children-u5","title":"Unit 5: Fables 85–105","lessons":[{"id":"aesop-for-children-5-1","title":"Lesson 29: The Goatherd and the Wild Goats, The Spendthrift and the Swallow, The Cat and the Birds","steps":["Read aloud: The Goatherd and the Wild Goats, The Spendthrift and the Swallow, The Cat and the Birds","After each fable, have your child tell it back in their own words","Copy the moral of \"The Spendthrift and the Swallow\" (younger children can trace it after you write it)","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Goatherd and the Wild Goats”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_GOATHERD_AND_THE_WILD_GOATS"},{"label":"Read “The Spendthrift and the Swallow”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SPENDTHRIFT_AND_THE_SWALLOW"},{"label":"Read “The Cat and the Birds”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_CAT_AND_THE_BIRDS"}],"questions":["Why did the Wild Goats run away from the Goatherd?","Why did the young man sell his cloak?","Why didn''t the Birds let the Cat \"doctor\" in?"],"answers":["He treated his own goats badly. Don''t treat old friends badly to please new ones.","He saw one swallow and thought it was summer. One sign doesn''t mean something has really happened.","They knew he wanted to eat them. Don''t trust someone who is only pretending to help."]},{"id":"aesop-for-children-5-2","title":"Lesson 30: The Dog and the Oyster, The Astrologer, Three Bullocks and a Lion","steps":["Read aloud: The Dog and the Oyster, The Astrologer, Three Bullocks and a Lion","Pause after each fable and ask your child to narrate it","Copy the moral of \"Three Bullocks and a Lion\" in your best handwriting"],"links":[{"label":"Read “The Dog and the Oyster”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOG_AND_THE_OYSTER"},{"label":"Read “The Astrologer”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASTROLOGER"},{"label":"Read “Three Bullocks and a Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THREE_BULLOCKS_AND_A_LION"}],"questions":["What happened when the Dog swallowed the oyster?","Why did the Astrologer fall into the ditch?","How did the Lion finally catch the Bullocks?"],"answers":["It hurt his tummy. If you rush, you''ll be sorry later.","He was looking at the stars, not where he walked. Pay attention to little things right in front of you.","He made them quarrel and split up. We are strong when we stay together."]},{"id":"aesop-for-children-5-3","title":"Lesson 31: Mercury and the Woodman, The Frog and the Mouse, The Fox and the Crab","steps":["Read aloud: Mercury and the Woodman, The Frog and the Mouse, The Fox and the Crab","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"Mercury and the Woodman\" from dictation, then check it against the book","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “Mercury and the Woodman”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#MERCURY_AND_THE_WOODMAN"},{"label":"Read “The Frog and the Mouse”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FROG_AND_THE_MOUSE"},{"label":"Read “The Fox and the Crab”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_CRAB"}],"questions":["What did Mercury give the honest Woodman?","What happened to the Frog who tied the Mouse to him?","What happened when the Crab left the seashore?"],"answers":["All three axes. Telling the truth is always best.","A Hawk caught them both. If you try to hurt others, you may get hurt yourself.","A Fox ate him. Be happy with the place you belong."]},{"id":"aesop-for-children-5-4","title":"Lesson 32: The Serpent and the Eagle, The Wolf in Sheep''s Clothing, The Bull and the Goat","steps":["Read aloud: The Serpent and the Eagle, The Wolf in Sheep''s Clothing, The Bull and the Goat","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Wolf in Sheep''s Clothing\" and underline the most important word","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Serpent and the Eagle”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SERPENT_AND_THE_EAGLE"},{"label":"Read “The Wolf in Sheep''s Clothing”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_IN_SHEEPS_CLOTHING"},{"label":"Read “The Bull and the Goat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BULL_AND_THE_GOAT"}],"questions":["How did the Eagle repay the man who saved him?","Why was the Wolf in sheep''s clothing caught?","Why didn''t the Bull fight the rude Goat?"],"answers":["He knocked away the poisoned horn. A kindness will come back to you.","The Shepherd chose him for dinner. Tricks can get the trickster hurt.","He was hiding from the Lion. It''s wrong to pick on someone when they are in trouble."]},{"id":"aesop-for-children-5-5","title":"Lesson 33: The Eagle and the Beetle, The Old Lion and the Fox, The Man and the Lion","steps":["Read aloud: The Eagle and the Beetle, The Old Lion and the Fox, The Man and the Lion","After each fable, have your child tell it back in their own words","Copy the moral of \"The Man and the Lion\" (younger children can trace it after you write it)","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Eagle and the Beetle”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_EAGLE_AND_THE_BEETLE"},{"label":"Read “The Old Lion and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_OLD_LION_AND_THE_FOX"},{"label":"Read “The Man and the Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MAN_AND_THE_LION"}],"questions":["How did the Beetle get back at the Eagle?","Why didn''t the Fox go into the Lion''s cave?","Why did the Man and Lion disagree about the statue?"],"answers":["She kept rolling the Eagle''s eggs out of the nest. Even the smallest can stand up to a wrong.","Footprints went in but none came out. Learn from what happened to others.","A man made it, so the man won. It depends on who tells the story."]},{"id":"aesop-for-children-5-6","title":"Lesson 34: The Ass and the Lap Dog, The Milkmaid and Her Pail, The Wolf and the Shepherd","steps":["Read aloud: The Ass and the Lap Dog, The Milkmaid and Her Pail, The Wolf and the Shepherd","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Ass and the Lap Dog\" in your best handwriting","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Ass and the Lap Dog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_AND_THE_LAP_DOG"},{"label":"Read “The Milkmaid and Her Pail”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MILKMAID_AND_HER_PAIL"},{"label":"Read “The Wolf and the Shepherd”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_SHEPHERD1"}],"questions":["What happened when the Ass jumped on his master like the Lap Dog?","What made the Milkmaid spill her milk?","What did the Wolf notice about the Shepherd''s dinner?"],"answers":["He got beaten. Don''t act like someone you''re not just to be liked.","She was daydreaming and tossed her head. Don''t count your chickens before they hatch.","They ate a lamb but would chase him for doing the same. People often blame others for things they do themselves."]},{"id":"aesop-for-children-5-7","title":"Lesson 35: The Goatherd and the Goat, The Miser, The Wolf and the House Dog","steps":["Read aloud: The Goatherd and the Goat, The Miser, The Wolf and the House Dog","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Miser\" from dictation, then check it against the book"],"links":[{"label":"Read “The Goatherd and the Goat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_GOATHERD_AND_THE_GOAT"},{"label":"Read “The Miser”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MISER"},{"label":"Read “The Wolf and the House Dog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_AND_THE_HOUSE_DOG"}],"questions":["Why couldn''t the Goatherd hide what he did?","Why was the stone as good as the Miser''s gold?","Why did the Wolf not want to be a house dog?"],"answers":["The Goat''s broken horn would show it. Bad things you do will come out.","He never used the gold. Things are only worth what you use them for.","Dogs wear a collar and chain. Being free is worth more than food."]}]},{"id":"aesop-for-children-u6","title":"Unit 6: Fables 106–126","lessons":[{"id":"aesop-for-children-6-1","title":"Lesson 36: The Fox and the Hedgehog, The Bat and the Weasels, The Quack Toad","steps":["Read aloud: The Fox and the Hedgehog, The Bat and the Weasels, The Quack Toad","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Quack Toad\" and underline the most important word","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Fox and the Hedgehog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_HEDGEHOG"},{"label":"Read “The Bat and the Weasels”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BAT_AND_THE_WEASELS"},{"label":"Read “The Quack Toad”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_QUACK_TOAD"}],"questions":["Why didn''t the Fox want the flies chased away?","How did the Bat escape both Weasels?","Why didn''t the Fox believe the Toad was a doctor?"],"answers":["Hungrier ones would come. Sometimes it''s better to bear a small problem than risk a bigger one.","He said he was a mouse to one and a bird to the other. Change your plan to fit what''s happening.","The Toad couldn''t fix his own skin. Fix yourself before trying to fix others."]},{"id":"aesop-for-children-6-2","title":"Lesson 37: The Fox Without a Tail, The Mischievous Dog, The Rose and the Butterfly","steps":["Read aloud: The Fox Without a Tail, The Mischievous Dog, The Rose and the Butterfly","After each fable, have your child tell it back in their own words","Copy the moral of \"The Fox Without a Tail\" (younger children can trace it after you write it)","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Fox Without a Tail”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_WITHOUT_A_TAIL"},{"label":"Read “The Mischievous Dog”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MISCHIEVOUS_DOG"},{"label":"Read “The Rose and the Butterfly”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ROSE_AND_THE_BUTTERFLY"}],"questions":["Why did the Fox without a tail want the others to cut theirs off?","Was the Dog''s clog something to be proud of?","Why couldn''t the Butterfly blame the Rose?"],"answers":["So he wouldn''t look silly. Don''t listen to someone who wants you to lose what you have.","No, it showed he was bad. Being known for bad things isn''t being famous.","He flitted to other flowers too. Don''t expect others to be loyal if you aren''t."]},{"id":"aesop-for-children-6-3","title":"Lesson 38: The Cat and the Fox, The Boy and the Nettle, The Old Lion","steps":["Read aloud: The Cat and the Fox, The Boy and the Nettle, The Old Lion","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Boy and the Nettle\" in your best handwriting","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Cat and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_CAT_AND_THE_FOX"},{"label":"Read “The Boy and the Nettle”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BOY_AND_THE_NETTLE"},{"label":"Read “The Old Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_OLD_LION"}],"questions":["What saved the Cat when the dogs came?","How should the Boy touch a nettle next time?","How did the animals treat the Lion when he was old and weak?"],"answers":["Her one trick of climbing a tree. Plain good sense beats lots of clever tricks.","Grab it firmly. Whatever you do, do it with all your might.","They attacked him. It''s cowardly to pick on someone who can''t fight back."]},{"id":"aesop-for-children-6-4","title":"Lesson 39: The Fox and the Pheasants, Two Travelers and a Bear, The Porcupine and the Snakes","steps":["Read aloud: The Fox and the Pheasants, Two Travelers and a Bear, The Porcupine and the Snakes","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Porcupine and the Snakes\" from dictation, then check it against the book","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Fox and the Pheasants”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_PHEASANTS"},{"label":"Read “Two Travelers and a Bear”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#TWO_TRAVELERS_AND_A_BEAR"},{"label":"Read “The Porcupine and the Snakes”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_PORCUPINE_AND_THE_SNAKES"}],"questions":["Why did the Pheasants fall to the Fox?","What did the Bear \"whisper\" to the man on the ground?","What did the Porcupine do once the Snakes let him in?"],"answers":["They watched him so hard they got dizzy. Worrying too much about danger can make you fall into it.","Don''t travel with a friend who leaves you in danger. Hard times show who your true friends are.","He pushed them out with his quills. If you give a little, someone may take a lot."]},{"id":"aesop-for-children-6-5","title":"Lesson 40: The Fox and the Monkey, The Mother and the Wolf, The Flies and the Honey","steps":["Read aloud: The Fox and the Monkey, The Mother and the Wolf, The Flies and the Honey","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Fox and the Monkey\" and underline the most important word"],"links":[{"label":"Read “The Fox and the Monkey”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_MONKEY"},{"label":"Read “The Mother and the Wolf”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MOTHER_AND_THE_WOLF"},{"label":"Read “The Flies and the Honey”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FLIES_AND_THE_HONEY"}],"questions":["Why wasn''t the Monkey a good king?","Why didn''t the Wolf get the child?","Why did the flies die?"],"answers":["He fell for the Fox''s trap. A real leader proves it by being wise.","The Mother didn''t mean what she said. Don''t believe everything you hear.","They got stuck in the honey. Being greedy for a treat can hurt you."]},{"id":"aesop-for-children-6-6","title":"Lesson 41: The Eagle and the Kite, The Stag, the Sheep, and the Wolf, The Animals and the Plague","steps":["Read aloud: The Eagle and the Kite, The Stag, the Sheep, and the Wolf, The Animals and the Plague","After each fable, have your child tell it back in their own words","Copy the moral of \"The Stag, the Sheep, and the Wolf\" (younger children can trace it after you write it)","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Eagle and the Kite”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_EAGLE_AND_THE_KITE"},{"label":"Read “The Stag, the Sheep, and the Wolf”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_STAG_THE_SHEEP_AND_THE_WOLF"},{"label":"Read “The Animals and the Plague”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ANIMALS_AND_THE_PLAGUE"}],"questions":["Why did the Kite say he could catch an Ostrich?","Why wouldn''t the Sheep lend wheat to the Stag?","Who was blamed for the plague?"],"answers":["He wanted the Eagle to marry him. People will say anything to win what they want.","She didn''t trust him or his friend the Wolf. Two untrustworthy people don''t make one you can trust.","The Ass, who did the smallest wrong. Sometimes the weak are punished for what the strong did."]},{"id":"aesop-for-children-6-7","title":"Lesson 42: The Shepherd and the Lion, The Dog and His Reflection, The Hare and the Tortoise","steps":["Read aloud: The Shepherd and the Lion, The Dog and His Reflection, The Hare and the Tortoise","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Hare and the Tortoise\" in your best handwriting","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Shepherd and the Lion”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SHEPHERD_AND_THE_LION"},{"label":"Read “The Dog and His Reflection”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_DOG_AND_HIS_REFLECTION"},{"label":"Read “The Hare and the Tortoise”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_HARE_AND_THE_TORTOISE"}],"questions":["What did the Shepherd do when he really saw the Lion?","Why did the Dog lose his bone?","Who won the race?"],"answers":["He ran and wished it gone. Be careful what you wish for.","He snapped at his reflection. Being greedy is foolish.","The Tortoise, by never stopping. Slow and steady wins the race."]}]},{"id":"aesop-for-children-u7","title":"Unit 7: Fables 127–147","lessons":[{"id":"aesop-for-children-7-1","title":"Lesson 43: The Bees and Wasps, and the Hornet, The Lark and Her Young Ones, The Cat and the Old Rat","steps":["Read aloud: The Bees and Wasps, and the Hornet, The Lark and Her Young Ones, The Cat and the Old Rat","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Bees and Wasps, and the Hornet\" from dictation, then check it against the book","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Bees and Wasps, and the Hornet”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_BEES_AND_WASPS_AND_THE_HORNET"},{"label":"Read “The Lark and Her Young Ones”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LARK_AND_HER_YOUNG_ONES"},{"label":"Read “The Cat and the Old Rat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_CAT_AND_THE_OLD_RAT"}],"questions":["How did the Judge know who made the honey?","When did the Lark finally move her babies?","Why didn''t the old Rat go near the flour-covered lump?"],"answers":["The Wasps couldn''t make comb. What you can really do proves who you are.","When the Farmer said he''d cut the wheat himself. Doing it yourself is the best help.","He''d been tricked by the Cat before. A wise one doesn''t get tricked twice."]},{"id":"aesop-for-children-7-2","title":"Lesson 44: The Fox and the Crow, The Ass and Its Shadow, The Miller, His Son, and the Ass","steps":["Read aloud: The Fox and the Crow, The Ass and Its Shadow, The Miller, His Son, and the Ass","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Ass and Its Shadow\" and underline the most important word","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Fox and the Crow”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FOX_AND_THE_CROW"},{"label":"Read “The Ass and Its Shadow”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_AND_ITS_SHADOW"},{"label":"Read “The Miller, His Son, and the Ass”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MILLER_HIS_SON_AND_THE_ASS"}],"questions":["How did the Fox get the Crow''s cheese?","What happened while the men fought over the shadow?","Why did the Miller lose his Ass?"],"answers":["He praised her voice so she sang. A flatterer gets things from people who listen.","The Ass ran away. If you fight over little things, you can lose what matters.","He tried to do what everyone said. If you try to please everyone, you please no one."]},{"id":"aesop-for-children-7-3","title":"Lesson 45: The Ant and the Dove, The Man and the Satyr, The Wolf, the Kid, and the Goat","steps":["Read aloud: The Ant and the Dove, The Man and the Satyr, The Wolf, the Kid, and the Goat","After each fable, have your child tell it back in their own words","Copy the moral of \"The Wolf, the Kid, and the Goat\" (younger children can trace it after you write it)"],"links":[{"label":"Read “The Ant and the Dove”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ANT_AND_THE_DOVE"},{"label":"Read “The Man and the Satyr”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MAN_AND_THE_SATYR"},{"label":"Read “The Wolf, the Kid, and the Goat”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLF_THE_KID_AND_THE_GOAT"}],"questions":["How did the Ant save the Dove?","Why did the Satyr leave the Man?","Why didn''t the Kid open the door to the Wolf?"],"answers":["She bit the hunter so he missed. A kindness is never wasted.","He blew hot and cold. Don''t trust someone who says one thing and then the opposite.","He asked for the password and to see a white paw. It''s good to be extra careful."]},{"id":"aesop-for-children-7-4","title":"Lesson 46: The Swallow and the Crow, Jupiter and the Monkey, The Lion, the Ass, and the Fox","steps":["Read aloud: The Swallow and the Crow, Jupiter and the Monkey, The Lion, the Ass, and the Fox","Pause after each fable and ask your child to narrate it","Copy the moral of \"The Swallow and the Crow\" in your best handwriting","Look at Milo Winter''s picture for one fable and tell what is happening"],"links":[{"label":"Read “The Swallow and the Crow”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_SWALLOW_AND_THE_CROW"},{"label":"Read “Jupiter and the Monkey”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#JUPITER_AND_THE_MONKEY"},{"label":"Read “The Lion, the Ass, and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LION_THE_ASS_AND_THE_FOX"}],"questions":["When did the Crow say the Swallow wasn''t a good friend?","Why did Mother Monkey love her baby most?","How did the Fox learn to share with the Lion?"],"answers":["In winter when the Swallow left. A friend only in good times isn''t much of a friend.","Mothers love their babies no matter what. Mother love is blind.","He saw what happened to the Ass. Learn from other people''s mistakes."]},{"id":"aesop-for-children-7-5","title":"Lesson 47: The Lion''s Share, The Mole and His Mother, The North Wind and the Sun","steps":["Read aloud: The Lion''s Share, The Mole and His Mother, The North Wind and the Sun","Your child narrates each fable back, then you talk about the moral together","Write the moral of \"The Mole and His Mother\" from dictation, then check it against the book","Act out one fable with toys or puppets"],"links":[{"label":"Read “The Lion''s Share”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_LIONS_SHARE"},{"label":"Read “The Mole and His Mother”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_MOLE_AND_HIS_MOTHER"},{"label":"Read “The North Wind and the Sun”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_NORTH_WIND_AND_THE_SUN"}],"questions":["Why did the Lion keep all the meat?","How did the Mother Mole show her son he couldn''t smell?","How did the Sun get the traveler to take off his cloak?"],"answers":["He was the strongest. Sometimes bullies take everything, and that isn''t fair.","She held up something and he guessed wrong. If you brag, others will find what you can''t do.","By shining warmly. Being gentle and kind works better than being rough."]},{"id":"aesop-for-children-7-6","title":"Lesson 48: The Hare and His Ears, The Wolves and the Sheep, The Cock and the Fox","steps":["Read aloud: The Hare and His Ears, The Wolves and the Sheep, The Cock and the Fox","Ask your child to retell their favorite of the three to someone else at home","Copy the moral of \"The Cock and the Fox\" and underline the most important word","Draw a picture of your favorite fable from today"],"links":[{"label":"Read “The Hare and His Ears”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_HARE_AND_HIS_EARS"},{"label":"Read “The Wolves and the Sheep”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_WOLVES_AND_THE_SHEEP"},{"label":"Read “The Cock and the Fox”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_COCK_AND_THE_FOX1"}],"questions":["Why did the Hare run away from the Lion''s kingdom?","What happened when the Sheep sent the Dogs away?","Why didn''t the Cock help the trapped Fox?"],"answers":["He was afraid his ears would be called horns. A bully will find any excuse to pick on you.","The Wolves ate them. Don''t give up your true friends for your enemies.","He knew the Fox would eat the hens. Don''t help someone who will do harm."]},{"id":"aesop-for-children-7-7","title":"Lesson 49: The Ass in the Lion''s Skin, The Fisherman and the Little Fish, The Fighting Cocks and the Eagle","steps":["Read aloud: The Ass in the Lion''s Skin, The Fisherman and the Little Fish, The Fighting Cocks and the Eagle","After each fable, have your child tell it back in their own words","Copy the moral of \"The Ass in the Lion''s Skin\" (younger children can trace it after you write it)","Talk about a time you saw this lesson happen in real life"],"links":[{"label":"Read “The Ass in the Lion''s Skin”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_ASS_IN_THE_LIONS_SKIN"},{"label":"Read “The Fisherman and the Little Fish”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FISHERMAN_AND_THE_LITTLE_FISH"},{"label":"Read “The Fighting Cocks and the Eagle”","url":"https://www.gutenberg.org/cache/epub/19994/pg19994-images.html#THE_FIGHTING_COCKS_AND_THE_EAGLE"}],"questions":["How did the Fox know the \"Lion\" was an Ass?","Why did the Fisherman keep the little fish?","What happened to the proud Cock who crowed on the wall?"],"answers":["He heard it bray. You can dress up, but your words show who you are.","A small fish now is better than a big one later. A sure small thing is better than a big promise.","An Eagle carried him off. Pride comes before a fall."]}]}],"version":1,"license":{"kind":"public_domain"},"attribution":"Lesson plan by Freerange Library for “The Aesop for Children, with Pictures by Milo Winter” by Aesop (illustrated by Milo Winter) (1919), in the public domain. Free full text: https://www.gutenberg.org/ebooks/19994"}'::jsonb)
  on conflict (listing_id, version) do update set content = excluded.content;
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-burgess-bird-book', 'Freerange Library', 'publisher', true, 'The Burgess Bird Book for Children', array['science']::text[], 1, 4, array['charlotte_mason', 'nature_forest']::text[], 'online', 0, 'A classic 1919 read-aloud in which Peter Rabbit gossips with Jenny Wren and meets dozens of real North American birds, from robins and bluebirds to owls and crossbills. Each sitting is one chapter read aloud, a narration, and a nature-study outing or journal page about that chapter''s birds. Siblings can do it together, and the full text is free online.', array['45 lessons in 6 units, one per chapter', 'Link to the free full text for every chapter', 'A nature-study activity for the real bird species in each chapter', 'Narration prompts and comprehension questions with answers', 'Follows the birds through a full year, from spring arrivals to winter visitors']::text[], 45, 3, 30, 'high', true, '{}'::text[], '🐦', '#3D9970', false, '2026-11-11T12:00:00.000Z', 'pk-lib-burgess-bird-book', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “The Burgess Bird Book for Children” by Thornton W. Burgess (1919), in the public domain. Free full text: https://www.gutenberg.org/ebooks/3074', '[{"title":"Unit 1: Spring Comes to the Old Orchard (Chapters I–VIII)","lessons":["Chapter I: Jenny Wren Arrives","Chapter II: The Old Orchard Bully","Chapter III: Jenny Has a Good Word for Some Sparrows","Chapter IV: Chippy, Sweetvoice, and Dotty","Chapter V: Peter Learns Something He Hadn''t Guessed","Chapter VI: An Old Friend In a New Home","Chapter VII: The Watchman of the Old Orchard","Chapter VIII: Old Clothes and Old Houses"]},{"title":"Unit 2: Meadow, Pool, and Orchard Neighbors (Chapters IX–XVI)","lessons":["Chapter IX: Longbill and Teeter","Chapter X: Redwing and Yellow Wing","Chapter XI: Drummers and Carpenters","Chapter XII: Some Unlikely Relatives","Chapter XIII: More of the Blackbird Family","Chapter XIV: Bob White and Carol the Meadow Lark","Chapter XV: A Swallow and One Who Isn''t","Chapter XVI: A Robber in the Old Orchard"]},{"title":"Unit 3: Robbers, Hunters, and Fishermen (Chapters XVII–XXIII)","lessons":["Chapter XVII: More Robbers","Chapter XVIII: Some Homes in the Green Forest","Chapter XIX: A Maker of Thunder and a Friend in Black","Chapter XX: A Fisherman Robbed","Chapter XXI: A Fishing Party","Chapter XXII: Some Feathered Diggers","Chapter XXIII: Some Big Mouths"]},{"title":"Unit 4: Warblers and Bright Singers (Chapters XXIV–XXX)","lessons":["Chapter XXIV: The Warblers Arrive","Chapter XXV: Three Cousins Quite Unlike","Chapter XXVI: Peter Gets a Lame Neck","Chapter XXVII: A New Friend and an Old One","Chapter XXVIII: Peter Sees Rosebreast and Finds Redcoat","Chapter XXIX: The Constant Singers","Chapter XXX: Jenny Wren''s Cousins"]},{"title":"Unit 5: Summer Songs and Farewells (Chapters XXXI–XXXVII)","lessons":["Chapter XXXI: Voices of the Dusk","Chapter XXXII: Peter Saves a Friend and Learns Something","Chapter XXXIII: A Royal Dresser and a Late Nester","Chapter XXXIV: Mourner the Dove and Cuckoo","Chapter XXXV: A Butcher and a Hummer","Chapter XXXVI: A Stranger and a Dandy","Chapter XXXVII: Farewells and Welcomes"]},{"title":"Unit 6: Winter Visitors (Chapters XXXVIII–XLV)","lessons":["Chapter XXXVIII: Honker and Dippy Arrive","Chapter XXXIX: Peter Discovers Two Old Friends","Chapter XL: Some Merry Seed-Eaters","Chapter XLI: More Friends Come With the Snow","Chapter XLII: Peter Learns Something About Spooky","Chapter XLIII: Queer Feet and a Queerer Bill","Chapter XLIV: More Folks in Red","Chapter XLV: Peter Sees Two Terrible Feathered Hunters"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-burgess-bird-book', 1, '{"units":[{"id":"burgess-bird-book-u1","title":"Unit 1: Spring Comes to the Old Orchard (Chapters I–VIII)","lessons":[{"id":"burgess-bird-book-1-1","title":"Chapter I: Jenny Wren Arrives","steps":["Read Chapter I, \"Jenny Wren Arrives\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (House Wren): Listen outside for a loud, bubbly song from a small brown bird with its tail cocked up; that may be a House Wren"],"links":[{"label":"Read Chapter I","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0001"}],"questions":["Why does Jenny Wren leave the Old Orchard every fall?","What color is Jenny Wren''s suit, and why does she like it?"],"answers":["In winter there is no food for her there, so she goes south where there is food","Brown; it is neat and helps her get out of sight in a hurry"],"notes":"Start a nature journal today; the House Wren can be its first page."},{"id":"burgess-bird-book-1-2","title":"Chapter II: The Old Orchard Bully","steps":["Read Chapter II, \"The Old Orchard Bully\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (House Sparrow (English Sparrow)): Look for House Sparrows near buildings or parking lots; sketch the male''s black throat and the white bar on his wing"],"links":[{"label":"Read Chapter II","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0002"}],"questions":["Where had Jenny Wren''s old house been?","What made all the birds stop quarreling and join together?"],"answers":["In a hole in one of the old apple trees","Black Pussy the cat came creeping through the Old Orchard"],"notes":"Peter says the English Sparrow doesn''t belong in this country: it was brought to America from Europe."},{"id":"burgess-bird-book-1-3","title":"Chapter III: Jenny Has a Good Word for Some Sparrows","steps":["Read Chapter III, \"Jenny Has a Good Word for Some Sparrows\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Song Sparrow, White-throated Sparrow, and Fox Sparrow): Look in damp, brushy places for a streaky brown sparrow singing a cheerful song; listen for the White-throat''s slow whistle in spring or fall"],"links":[{"label":"Read Chapter III","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0003"}],"questions":["Where does Little Friend the Song Sparrow like to build his nest?","What does Peter think Whitethroat''s song says?","What is funny about the way Scratcher the Fox Sparrow scratches in the leaves?"],"answers":["On or near the ground, never more than a foot or two up","\"I live happ-i-ly, happ-i-ly, happ-i-ly\"","He uses both feet at once"]},{"id":"burgess-bird-book-1-4","title":"Chapter IV: Chippy, Sweetvoice, and Dotty","steps":["Read Chapter IV, \"Chippy, Sweetvoice, and Dotty\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Chipping Sparrow, American Tree Sparrow, and Vesper Sparrow): Look for a tiny sparrow with a rusty cap on lawns or in trees; draw its white eye-line next to Bully from chapter 2"],"links":[{"label":"Read Chapter IV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0004"}],"questions":["What does Chippy line his nest with?","How can you tell Dotty the Tree Sparrow from Chippy?","Where did Sweetvoice the Vesper Sparrow build his nest?"],"answers":["Long horsehair from a horse''s tail or mane","Dotty is bigger and has a round black dot in the middle of his breast","In a hoofprint of Bossy the Cow"]},{"id":"burgess-bird-book-1-5","title":"Chapter V: Peter Learns Something He Hadn''t Guessed","steps":["Read Chapter V, \"Peter Learns Something He Hadn''t Guessed\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Eastern Bluebird and American Robin): Watch a robin hunting on a lawn: count how many steps it runs before it stops, tilts its head, and pulls up a worm"],"links":[{"label":"Read Chapter V","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0005"}],"questions":["Which bird family do bluebirds and robins both belong to?","What do robins use for the foundation of their nest?","Where was the Bluebirds'' nest?"],"answers":["The Thrush family","Mud","In a hole in an old fence post"]},{"id":"burgess-bird-book-1-6","title":"Chapter VI: An Old Friend In a New Home","steps":["Read Chapter VI, \"An Old Friend In a New Home\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Eastern Phoebe and Least Flycatcher): Sit quietly near water and watch for a bird that darts out from a perch, snaps up a flying insect, and returns, wagging its tail"],"links":[{"label":"Read Chapter VI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0006"}],"questions":["Where did Mr. and Mrs. Phoebe build their nest this year?","Why do Phoebes get back in spring before the other flycatchers?","How did Chebec the Least Flycatcher get his name?"],"answers":["Under the bridge over the Laughing Brook","They don''t go as far south in winter","He keeps calling \"Chebec!\" over and over; \"Least\" because he is the smallest of the family"]},{"id":"burgess-bird-book-1-7","title":"Chapter VII: The Watchman of the Old Orchard","steps":["Read Chapter VII, \"The Watchman of the Old Orchard\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Eastern Kingbird and Great Crested Flycatcher): Watch the sky for a small bird chasing a hawk or crow; in your journal, draw the Kingbird''s white tail band and compare it with the Phoebe from chapter 6"],"links":[{"label":"Read Chapter VII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0007"}],"questions":["Why is Scrapper called the Kingbird?","What strange thing did Cresty ask Peter to look for?","What does Scrapper mostly eat?"],"answers":["Because he is fearless and chases away even big hawks","A snake''s cast-off skin","All kinds of flying insects (only a few bees, mostly drones)"]},{"id":"burgess-bird-book-1-8","title":"Chapter VIII: Old Clothes and Old Houses","steps":["Read Chapter VIII, \"Old Clothes and Old Houses\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Eastern Wood-Pewee (and the birds that nest in old woodpecker holes)): On a walk, look for round holes in tree trunks; list which birds from the book might use an old woodpecker hole"],"links":[{"label":"Read Chapter VIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0008"}],"questions":["What does Pewee keep calling?","Why do Cresty and his wife want a snake skin?","Name two birds besides Jenny Wren that use old woodpecker houses."],"answers":["His own name: \"Pee-wee!\"","They always put a piece of snake skin in their nest","Any two of: Cresty, Bully the English Sparrow, Winsome Bluebird, Skimmer the Tree Swallow, the Nuthatch, the Chickadee, the Flicker, the Sparrow Hawk, the Screech Owl"]}]},{"id":"burgess-bird-book-u2","title":"Unit 2: Meadow, Pool, and Orchard Neighbors (Chapters IX–XVI)","lessons":[{"id":"burgess-bird-book-2-1","title":"Chapter IX: Longbill and Teeter","steps":["Read Chapter IX, \"Longbill and Teeter\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (American Woodcock and Spotted Sandpiper): If you are near a pond or stream, watch for a small shorebird that bobs its tail up and down as it walks; draw a Woodcock''s long bill and big, far-back eyes"],"links":[{"label":"Read Chapter IX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0009"}],"questions":["How does Longbill catch worms deep in the ground?","Why must the Woodcock fly south when the ground freezes?","Why didn''t Peter see Teeter''s eggs?"],"answers":["He pushes his long bill in, feels the worm, and opens just the tip of the upper bill to grab it","He can only probe for worms in soft ground","They were in a hollow in the sand and looked just like the pebbles around them"]},{"id":"burgess-bird-book-2-2","title":"Chapter X: Redwing and Yellow Wing","steps":["Read Chapter X, \"Redwing and Yellow Wing\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Red-winged Blackbird and Northern Flicker): Look in marshes or wet fields for a black bird with red shoulder patches; in flight, look for a flicker''s white rump and golden wing linings"],"links":[{"label":"Read Chapter X","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0010"}],"questions":["How does Redwing get his name?","How is Mrs. Redwing dressed?","What family does Yellow Wing the Flicker belong to?"],"answers":["From the red patch on the bend of each wing","In plain grayish-brown with darker streaks, no bright feathers","The Woodpecker family"]},{"id":"burgess-bird-book-2-3","title":"Chapter XI: Drummers and Carpenters","steps":["Read Chapter XI, \"Drummers and Carpenters\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Downy Woodpecker, Hairy Woodpecker, and Red-headed Woodpecker): Listen for a woodpecker drumming; if you can see it, decide whether it is a Downy or a Hairy by its size and outer tail feathers"],"links":[{"label":"Read Chapter XI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0011"}],"questions":["Why does Downy drum on a hollow limb?","How can you tell Hairy from Downy?","Why does Yellow Wing spend so much time on the ground?"],"answers":["For happiness, the way other birds sing","Hairy is bigger and his outer tail feathers are all white; Downy''s have black bars","He is hunting ants"]},{"id":"burgess-bird-book-2-4","title":"Chapter XII: Some Unlikely Relatives","steps":["Read Chapter XII, \"Some Unlikely Relatives\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Brown-headed Cowbird and Baltimore Oriole): Look high in tall trees, especially elms, for an oriole''s hanging bag-shaped nest; draw it in your journal"],"links":[{"label":"Read Chapter XII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0012"}],"questions":["What did Sally Sly the Cowbird do in Chebec''s nest?","What is the Orioles'' nest like?","Name two birds Jenny says belong to the Blackbird family."],"answers":["She laid her egg there so Chebec would raise her baby","A deep hanging pocket woven of grass, string, hair, and bark","Any two of: orioles, meadowlarks, grackles, bobolinks, cowbirds, Redwing"]},{"id":"burgess-bird-book-2-5","title":"Chapter XIII: More of the Blackbird Family","steps":["Read Chapter XIII, \"More of the Blackbird Family\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Orchard Oriole and Bobolink): In your journal, draw the Orchard Oriole beside the Baltimore Oriole from chapter 12 and color in how their suits differ; in grassy fields, listen for a bubbling song sung in flight"],"links":[{"label":"Read Chapter XIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0013"}],"questions":["How is Weaver the Orchard Oriole''s suit different from Goldy''s?","Where do Bobolinks build their nest?","How did Bubbling Bob protect his nest from Jimmy Skunk?"],"answers":["Where Goldy is orange, Weaver is chestnut","On the ground in the meadow grass","He led Jimmy away from it by flying down in the grass far from the real nest"]},{"id":"burgess-bird-book-2-6","title":"Chapter XIV: Bob White and Carol the Meadow Lark","steps":["Read Chapter XIV, \"Bob White and Carol the Meadow Lark\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Northern Bobwhite and Eastern Meadowlark): Listen in open fields for a whistled \"Bob-white!\" or a meadowlark''s sweet song from a fence post; draw the meadowlark''s black V on its yellow breast"],"links":[{"label":"Read Chapter XIV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0014"}],"questions":["How did Mrs. Meadow Lark hide the way to her nest?","Why does Mrs. Meadow Lark land away from her nest and walk to it?","Where was Mrs. Bob White''s nest?"],"answers":["With a little tunnel of grass leading to it","So no one watching will find the nest","In a clump of tall weeds right beside a busy cow path"]},{"id":"burgess-bird-book-2-7","title":"Chapter XV: A Swallow and One Who Isn''t","steps":["Read Chapter XV, \"A Swallow and One Who Isn''t\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Tree Swallow and Chimney Swift): On a warm evening, watch for swifts (\"cigars with wings\") chattering over chimneys, and for swallows gliding low over fields or water"],"links":[{"label":"Read Chapter XV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0015"}],"questions":["Why does Skimmer have a small bill and short legs?","Is Sooty the Chimney Swift a swallow?","How does Sooty gather sticks for his nest?"],"answers":["He catches insects in the air and almost never walks or hops","No, he is a swift","He snaps off dead twigs with his feet while flying"]},{"id":"burgess-bird-book-2-8","title":"Chapter XVI: A Robber in the Old Orchard","steps":["Read Chapter XVI, \"A Robber in the Old Orchard\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Purple Martin and Barn Swallow): Look for a swallow with a deeply forked tail around barns or fields; draw its forked tail in your journal next to the Tree Swallow from chapter 15"],"links":[{"label":"Read Chapter XVI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0016"}],"questions":["Why does Twitter the Purple Martin live in a house with many rooms?","Where does Forktail the Barn Swallow build his nest?","Who finally drove Mr. Blacksnake away from Skimmer''s nest?"],"answers":["He loves company and likes to live with many of his own kind","Inside Farmer Brown''s barn, of mud and straw lined with feathers","Farmer Brown''s boy"]}]},{"id":"burgess-bird-book-u3","title":"Unit 3: Robbers, Hunters, and Fishermen (Chapters XVII–XXIII)","lessons":[{"id":"burgess-bird-book-3-1","title":"Chapter XVII: More Robbers","steps":["Read Chapter XVII, \"More Robbers\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Blue Jay and American Crow): Listen for a crow''s \"caw\" or a jay''s loud alarm call; notice whether other animals react, the way the Green Forest folk do"],"links":[{"label":"Read Chapter XVII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0017"}],"questions":["Who robbed the Robins'' eggs, and who robbed the Chebecs''?","What clue showed it was Sammy Jay?","What good thing did Sammy Jay do for Peter?"],"answers":["Blacky the Crow robbed the Robins; Sammy Jay robbed the Chebecs","A blue and white feather under Chebec''s nest","He warned Peter that Reddy Fox was coming"]},{"id":"burgess-bird-book-3-2","title":"Chapter XVIII: Some Homes in the Green Forest","steps":["Read Chapter XVIII, \"Some Homes in the Green Forest\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Ovenbird and Red-tailed Hawk): Watch the sky for a big hawk circling; if it flies low, look for a reddish tail. In the woods, listen for a loud \"teacher, teacher, teacher!\""],"links":[{"label":"Read Chapter XVIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0018"}],"questions":["Why is Teacher called the Oven Bird?","What does Blacky do for Mrs. Blacky while she sits on the eggs?","How did Redtail the Hawk get his name?"],"answers":["His nest on the ground is roofed over like an oven","He brings her food","His tail is a rich reddish-brown"]},{"id":"burgess-bird-book-3-3","title":"Chapter XIX: A Maker of Thunder and a Friend in Black","steps":["Read Chapter XIX, \"A Maker of Thunder and a Friend in Black\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Ruffed Grouse and Common Grackle): Look at a grackle or starling in bright sun and notice how its black feathers shine with changing colors (iridescence); draw a grackle next to the Crow from chapter 17 to show the size difference"],"links":[{"label":"Read Chapter XIX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0019"}],"questions":["What makes Strutter''s ''thunder''?","Why didn''t Peter see Mrs. Grouse on her nest?","What color are Creaker the Grackle''s eyes?"],"answers":["His wings beating faster and faster","Her brown cloak matched the dead leaves all around her","Yellow"]},{"id":"burgess-bird-book-3-4","title":"Chapter XX: A Fisherman Robbed","steps":["Read Chapter XX, \"A Fisherman Robbed\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Osprey and Bald Eagle): If you live near water, watch for a big hawk hovering and then diving feet-first for a fish; in your journal, draw the Bald Eagle''s white head and tail beside the Osprey''s white underparts"],"links":[{"label":"Read Chapter XX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0020"}],"questions":["How does Plunger the Osprey catch fish?","How did King Eagle get Plunger''s fish?","Do young Bald Eagles have white heads?"],"answers":["He circles high, hovers, then plunges into the water and grabs the fish with his curved claws","He chased Plunger until he dropped it, then caught it before it hit the water","No; they get white heads only when they grow up"]},{"id":"burgess-bird-book-3-5","title":"Chapter XXI: A Fishing Party","steps":["Read Chapter XXI, \"A Fishing Party\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Great Blue Heron and Belted Kingfisher): At a pond or stream, watch for a tall heron standing still and a kingfisher diving head-first; listen for the kingfisher''s loud rattle"],"links":[{"label":"Read Chapter XXI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0021"}],"questions":["How is Longlegs'' way of fishing different from Plunger''s?","How does Longlegs carry his neck when he flies?","Where do kingfishers make their home?"],"answers":["Longlegs stands still and waits for fish to come to him; Plunger hunts from the air","Folded back on his shoulders","In a hole they dig in a high, gravelly bank near water"]},{"id":"burgess-bird-book-3-6","title":"Chapter XXII: Some Feathered Diggers","steps":["Read Chapter XXII, \"Some Feathered Diggers\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Bank Swallow and American Kestrel (Sparrow Hawk)): Look for a small falcon perched on a wire or dead tree, or hovering over a field; look along sandy banks for rows of small holes"],"links":[{"label":"Read Chapter XXII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0022"}],"questions":["Where does Banker the Bank Swallow live?","What does Killy the Sparrow Hawk mostly eat?","What kind of nest did Mrs. Longlegs have?"],"answers":["In a hole he digs in a sandy bank, near many other Bank Swallows","Grasshoppers, insects, and meadow mice","A loose platform of sticks in a tree"]},{"id":"burgess-bird-book-3-7","title":"Chapter XXIII: Some Big Mouths","steps":["Read Chapter XXIII, \"Some Big Mouths\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Common Nighthawk and Eastern Whip-poor-will): On a summer evening, watch the sky for a nighthawk with white wing patches and listen for its call or its booming dive"],"links":[{"label":"Read Chapter XXIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0023"}],"questions":["What makes the ''boom'' when Boomer dives?","Where does Mrs. Nighthawk lay her eggs?","How can you tell the Whip-poor-will from the Nighthawk?"],"answers":["The wind rushing through his wing feathers as he turns upward","On the bare ground or a flat rock; she builds no nest","The Whip-poor-will has no white patches on its wings"]}]},{"id":"burgess-bird-book-u4","title":"Unit 4: Warblers and Bright Singers (Chapters XXIV–XXX)","lessons":[{"id":"burgess-bird-book-4-1","title":"Chapter XXIV: The Warblers Arrive","steps":["Read Chapter XXIV, \"The Warblers Arrive\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (American Redstart and Yellow Warbler): In spring, look for tiny, busy birds flitting in the treetops; try to spot a black-and-orange Redstart or an all-yellow warbler"],"links":[{"label":"Read Chapter XXIV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0024"}],"questions":["Which bigger bird does Zee Zee the Redstart remind Peter of?","How did Sunshine fool Sally Sly the Cowbird?","What soft material do the Yellow Warblers always use in their nest?"],"answers":["Goldy the Baltimore Oriole","He and his mate built a new floor in the nest right over her egg","Fern-cotton"]},{"id":"burgess-bird-book-4-2","title":"Chapter XXV: Three Cousins Quite Unlike","steps":["Read Chapter XXV, \"Three Cousins Quite Unlike\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Black-and-white Warbler, Common Yellowthroat, and Yellow-breasted Chat): Look for a small striped bird creeping up and down tree trunks; in brushy places, watch for a yellow bird wearing a black mask"],"links":[{"label":"Read Chapter XXV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0025"}],"questions":["How is Creeper the Black and White Warbler different from the other warblers?","How can you always tell Mummer the Yellow-throat?","Which is the largest of the warbler family?"],"answers":["He creeps along tree trunks and limbs instead of flitting about in the leaves","By the black mask across his face","Chut-Chut the Yellow-breasted Chat"]},{"id":"burgess-bird-book-4-3","title":"Chapter XXVI: Peter Gets a Lame Neck","steps":["Read Chapter XXVI, \"Peter Gets a Lame Neck\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Northern Parula, Yellow-rumped (Myrtle) Warbler, and Magnolia Warbler): In your journal, make a warbler page: draw the Parula, Myrtle, and Magnolia warblers and color in the yellow patches that help tell them apart"],"links":[{"label":"Read Chapter XXVI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0026"}],"questions":["Where do Sprite the Parula Warbler and his mate build their nest?","How did Peter recognize Fidget the Myrtle Warbler?","Where do Fidget and Weechi like to build?"],"answers":["Inside a hanging bunch of gray moss","By his yellow cap, yellow sides, and yellow patch at the base of his tail","In little hemlock trees, not far from the ground"]},{"id":"burgess-bird-book-4-4","title":"Chapter XXVII: A New Friend and an Old One","steps":["Read Chapter XXVII, \"A New Friend and an Old One\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Northern Cardinal and Gray Catbird): Listen in bushes and hedges for a cat-like \"meow\"; look for a red cardinal, and notice how different the plainer female looks"],"links":[{"label":"Read Chapter XXVII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0027"}],"questions":["How does Glory the Cardinal help when there is a second family?","Why is Kitty called the Catbird?","What is special about Kitty''s song?"],"answers":["He takes care of the first babies so Mrs. Cardinal can sit on the second eggs","One of his calls sounds like a cat''s meow","It is made of bits of other birds'' songs, plus notes of his own"]},{"id":"burgess-bird-book-4-5","title":"Chapter XXVIII: Peter Sees Rosebreast and Finds Redcoat","steps":["Read Chapter XXVIII, \"Peter Sees Rosebreast and Finds Redcoat\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Rose-breasted Grosbeak and Scarlet Tanager): Draw the male Rose-breasted Grosbeak and Scarlet Tanager in your journal, then draw each one''s mate beside him; compare with the Cardinals from chapter 27"],"links":[{"label":"Read Chapter XXVIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0028"}],"questions":["Why do farmers like Grosbeaks in the potato patch?","How did Redcoat the Tanager hurt his wing?","Who helped Redcoat?"],"answers":["They eat lots of potato bugs","Dodging Broadwing the Hawk, he flew into a sharp dead twig that went through his wing","Farmer Brown''s boy, who gently worked the twig out"]},{"id":"burgess-bird-book-4-6","title":"Chapter XXIX: The Constant Singers","steps":["Read Chapter XXIX, \"The Constant Singers\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Red-eyed Vireo, Warbling Vireo, and Yellow-throated Vireo): On a summer day, listen in tall trees for a bird that keeps singing short phrases over and over all day long"],"links":[{"label":"Read Chapter XXIX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0029"}],"questions":["How did Redeye get his name?","What odd thing does Redeye like to put in his nest?","What happened when the Cowbird egg hatched in Redeye''s nest?"],"answers":["His eyes are red","A piece of paper","The big young Cowbird took most of the food and pushed one of Redeye''s babies out of the nest"]},{"id":"burgess-bird-book-4-7","title":"Chapter XXX: Jenny Wren''s Cousins","steps":["Read Chapter XXX, \"Jenny Wren''s Cousins\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Brown Thrasher and Northern Mockingbird): Listen for a bird that copies other birds'' songs; then draw the Brown Thrasher next to the Catbird from chapter 27, since they belong to the same family"],"links":[{"label":"Read Chapter XXX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0030"}],"questions":["Why is Brownie called a Thrasher?","Is Brownie the Thrasher a thrush?","How did Mocker fool Peter?"],"answers":["Because he thrashes his long tail around so much","No; he is related to the Mockingbird and the Catbird","He whistled exactly like Glory the Cardinal"]}]},{"id":"burgess-bird-book-u5","title":"Unit 5: Summer Songs and Farewells (Chapters XXXI–XXXVII)","lessons":[{"id":"burgess-bird-book-5-1","title":"Chapter XXXI: Voices of the Dusk","steps":["Read Chapter XXXI, \"Voices of the Dusk\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Wood Thrush, Hermit Thrush, and Veery): Go outside at dusk and sit very still for five minutes; listen for a flute-like evening song and write down every bird voice you hear"],"links":[{"label":"Read Chapter XXXI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0031"}],"questions":["Which bird does Melody the Wood Thrush say is the most beautiful singer?","What does Melody use in his nest that Welcome Robin also uses?","Where does the Hermit Thrush build its nest?"],"answers":["His cousin Hermit the Hermit Thrush","Mud","On the ground"]},{"id":"burgess-bird-book-5-2","title":"Chapter XXXII: Peter Saves a Friend and Learns Something","steps":["Read Chapter XXXII, \"Peter Saves a Friend and Learns Something\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Eastern Towhee and Indigo Bunting): Under bushes, listen for a bird noisily scratching in dead leaves; along field edges, look for a small, bright blue bird singing from a treetop"],"links":[{"label":"Read Chapter XXXII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0032"}],"questions":["How did Peter save Chewink from Reddy Fox?","What family does Chewink say is the biggest bird family?","Why is Mrs. Indigo glad she isn''t bright blue?"],"answers":["He thumped the ground with his feet, his danger signal","The Finch and Sparrow family","A bright coat attracts too much attention from enemies"]},{"id":"burgess-bird-book-5-3","title":"Chapter XXXIII: A Royal Dresser and a Late Nester","steps":["Read Chapter XXXIII, \"A Royal Dresser and a Late Nester\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Purple Finch and American Goldfinch): Look at the seed heads of dandelions or thistles for goldfinches; draw the male''s black cap and yellow body, then the plainer female"],"links":[{"label":"Read Chapter XXXIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0033"}],"questions":["Why do the Goldfinches wait until July to build a nest?","What does Chicoree call as he flies?","What color is Linnet the Purple Finch?"],"answers":["They need thistledown for the nest and plenty of seeds for their young","\"Chic-o-ree, per-chic-o-ree!\"","Rose-red"]},{"id":"burgess-bird-book-5-4","title":"Chapter XXXIV: Mourner the Dove and Cuckoo","steps":["Read Chapter XXXIV, \"Mourner the Dove and Cuckoo\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Mourning Dove and Yellow-billed Cuckoo): Listen in the morning for a dove''s soft, sad-sounding coo; look for hairy tent caterpillar webs in trees and think about which bird eats them"],"links":[{"label":"Read Chapter XXXIV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0034"}],"questions":["Why does Mourner the Dove swallow gravel?","What is a dove''s nest like?","What useful thing does Cuckoo eat that few other birds will touch?"],"answers":["The little stones help his gizzard grind up the hard seeds he eats","A flimsy platform of a few sticks","Hairy tent caterpillars"]},{"id":"burgess-bird-book-5-5","title":"Chapter XXXV: A Butcher and a Hummer","steps":["Read Chapter XXXV, \"A Butcher and a Hummer\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Loggerhead Shrike and Ruby-throated Hummingbird): Put out (or find) flowers that hummingbirds visit and watch for one hovering; draw the hummingbird''s nest from the description: a tiny cup of plant down covered in lichens"],"links":[{"label":"Read Chapter XXXV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0035"}],"questions":["Why does Butcher the Shrike stick his food on thorns?","How did Hummer the Hummingbird get his name?","How far south does Hummer go for the winter?"],"answers":["To store extra food for later, and to hold bigger prey while he tears it apart","His wings move so fast they hum like a bee","All the way to South America"]},{"id":"burgess-bird-book-5-6","title":"Chapter XXXVI: A Stranger and a Dandy","steps":["Read Chapter XXXVI, \"A Stranger and a Dandy\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (European Starling and Cedar Waxwing): Look at a flock of starlings in the sun and notice their speckles and shine; if you see waxwings, look for the yellow tip on the tail and red ''wax'' on the wings"],"links":[{"label":"Read Chapter XXXVI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0036"}],"questions":["Where did Speckles the Starling come from?","What happens to a starling''s yellow bill in winter?","Why are waxwings also called Cedarbirds?"],"answers":["From across the ocean, like the English Sparrow","It turns almost black","They love to eat cedar berries"]},{"id":"burgess-bird-book-5-7","title":"Chapter XXXVII: Farewells and Welcomes","steps":["Read Chapter XXXVII, \"Farewells and Welcomes\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Black-capped Chickadee): Hang suet or put out seeds for chickadees and watch them feed upside down; listen for the \"chick-a-dee-dee-dee\" call and the whistled \"fee-bee\" song"],"links":[{"label":"Read Chapter XXXVII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0037"}],"questions":["What is Tommy Tit''s secret for staying warm in winter?","What does Tommy Tit eat on bare trees in winter?","What is Tommy Tit''s spring love call?"],"answers":["Keep your stomach full: food makes heat, and feathers keep it in","Insect eggs, worms under the bark, and sleeping insects in bark cracks","A soft whistled \"Phoe-be! Phoe-be!\""],"notes":"Many birds have left for the south by this chapter. Start a list of birds you still see as the weather turns cold."}]},{"id":"burgess-bird-book-u6","title":"Unit 6: Winter Visitors (Chapters XXXVIII–XLV)","lessons":[{"id":"burgess-bird-book-6-1","title":"Chapter XXXVIII: Honker and Dippy Arrive","steps":["Read Chapter XXXVIII, \"Honker and Dippy Arrive\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Canada Goose and Common Loon): In fall, listen and look up for geese flying in a V; count how many birds are in the V if you see one"],"links":[{"label":"Read Chapter XXXVIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0038"}],"questions":["What shape does Honker''s flock make when it flies?","Why is Dippy the Loon so awkward on land?","Why does Dippy have a sharp, pointed bill instead of a broad one like Honker''s?"],"answers":["A letter V","His short legs are set so far back on his body that he can''t keep his balance to walk","He eats fish and needs to hold on to slippery fish"]},{"id":"burgess-bird-book-6-2","title":"Chapter XXXIX: Peter Discovers Two Old Friends","steps":["Read Chapter XXXIX, \"Peter Discovers Two Old Friends\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (White-breasted Nuthatch and Brown Creeper): Watch tree trunks for a bird walking head-first down (nuthatch) and one spiraling up (creeper); draw arrows in your journal showing which way each one moves"],"links":[{"label":"Read Chapter XXXIX","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0039"}],"questions":["How can Yank-Yank walk head-first down a tree?","How did the Nuthatch get its name?","Where does Seep-Seep the Brown Creeper build its nest?"],"answers":["He twists one foot around and hooks its claws into the bark to keep from falling","From cracking (''hatching'') nuts wedged in cracks in the bark","Behind a piece of loose bark on a tree or stub"]},{"id":"burgess-bird-book-6-3","title":"Chapter XL: Some Merry Seed-Eaters","steps":["Read Chapter XL, \"Some Merry Seed-Eaters\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (American Tree Sparrow and Dark-eyed Junco): After a snow, look for small birds feeding on weed seeds; look for a gray bird with white outer tail feathers that flash when it flies (a junco)"],"links":[{"label":"Read Chapter XL","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0040"}],"questions":["Why can Dotty stay all winter when Chippy can''t?","What other name does Slaty the Junco have?","Who crept up on the seed-eaters in the weedy field?"],"answers":["Dotty eats seeds, which he can find in winter; Chippy eats worms and bugs","Snowbird","Black Pussy the cat"],"notes":"Dotty first appeared in chapter 4. Look back at your journal page for Chippy and compare."},{"id":"burgess-bird-book-6-4","title":"Chapter XLI: More Friends Come With the Snow","steps":["Read Chapter XLI, \"More Friends Come With the Snow\", aloud together","Ask your child to narrate (tell back) the chapter in their own words","Nature study (Snow Bunting and Horned Lark): On a snowy day, look in open fields or along roadsides for flocks of birds walking (not hopping) on the snow"],"links":[{"label":"Read Chapter XLI","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0041"}],"questions":["Where does Snowflake the Snow Bunting nest?","Why does Snowflake come south in winter?","How did Wanderer the Horned Lark get his name?"],"answers":["Far north, on the shore of the Polar Sea","Deep snow up north covers the seeds he needs to eat","From the two little tufts of black feathers above his eyes that look like horns"]},{"id":"burgess-bird-book-6-5","title":"Chapter XLII: Peter Learns Something About Spooky","steps":["Read Chapter XLII, \"Peter Learns Something About Spooky\", aloud together","Have your child tell the story back, including what they learned about the bird","Nature study (Eastern Screech-Owl): Look for holes in old trees where an owl might roost; on a quiet evening, listen for a screech owl''s soft trill or whinny"],"links":[{"label":"Read Chapter XLII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0042"}],"questions":["Why couldn''t Peter eat the bark in Farmer Brown''s young orchard?","Why does Spooky turn his whole head to look sideways?","What does Spooky mostly eat?"],"answers":["Farmer Brown had wrapped wire netting around the trees","His eyes are fixed in their sockets and can''t move","Mice and shrews in winter, and grasshoppers and other insects in summer"]},{"id":"burgess-bird-book-6-6","title":"Chapter XLIII: Queer Feet and a Queerer Bill","steps":["Read Chapter XLIII, \"Queer Feet and a Queerer Bill\", aloud together","Narration: your child retells the chapter; younger ones can act out Peter''s visit","Nature study (Ruffed Grouse (in winter) and Red Crossbill): Look at a pine cone and try to find the seeds hidden under its scales; think about how a crossbill''s crossed bill works like scissors"],"links":[{"label":"Read Chapter XLIII","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0043"}],"questions":["What are Strutter''s winter ''snowshoes''?","What is strange about Snipper the Crossbill''s bill?","What does Snipper like to eat best?"],"answers":["Little horny points that grow out from the sides of his toes so he doesn''t sink in the snow","The tips of the upper and lower halves cross each other","Seeds from the cones of evergreen trees"],"notes":"Strutter the Ruffed Grouse first appeared in chapter 19. Compare his summer and winter feet."},{"id":"burgess-bird-book-6-7","title":"Chapter XLIV: More Folks in Red","steps":["Read Chapter XLIV, \"More Folks in Red\", aloud together","Ask your child to tell back what Peter found out in this chapter","Nature study (Pine Grosbeak and Common Redpoll): Look for small flocks feeding in birch trees or weedy fields in winter; notice whether the whole flock takes off at the same moment"],"links":[{"label":"Read Chapter XLIV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0044"}],"questions":["Which summer bird is Piny the Pine Grosbeak''s cousin?","Why does Mrs. Grosbeak look for cedar, ash, and sumac trees?","How did Redpoll get his name?"],"answers":["Rosebreast the Rose-breasted Grosbeak","They keep their berries all winter, which she can eat","From his red cap"]},{"id":"burgess-bird-book-6-8","title":"Chapter XLV: Peter Sees Two Terrible Feathered Hunters","steps":["Read Chapter XLV, \"Peter Sees Two Terrible Feathered Hunters\", aloud together","Narration: your child describes the bird(s) from memory: size, colors, voice, and nest","Nature study (Northern Goshawk and Great Horned Owl): Make a final journal page: list every bird you have seen this year, and mark which ones you also met in this book"],"links":[{"label":"Read Chapter XLV","url":"https://www.gutenberg.org/cache/epub/3074/pg3074-images.html#link2HCH0045"}],"questions":["How did Peter escape from Terror the Goshawk?","Why did Peter sit perfectly still when he heard Hooty''s call?","When do Great Horned Owls start nesting?"],"answers":["He dove into a hollow log","Hooty calls to scare animals into moving so his sharp ears can find them","In late winter, while there is still snow and ice"],"notes":"This is the last chapter. A fun follow-up is to reread chapter 1 and see how much more you know about the Old Orchard birds now."}]}],"version":1,"license":{"kind":"public_domain"},"attribution":"Lesson plan by Freerange Library for “The Burgess Bird Book for Children” by Thornton W. Burgess (1919), in the public domain. Free full text: https://www.gutenberg.org/ebooks/3074"}'::jsonb)
  on conflict (listing_id, version) do update set content = excluded.content;
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-fairy-land-of-science', 'Freerange Library', 'publisher', true, 'The Fairy-Land of Science', array['science']::text[], 4, 8, array['charlotte_mason', 'classical']::text[], 'online', 0, 'Arabella Buckley''s 1879 classic invites children to meet the ''fairies'' of science: sunbeams, air, water, ice, sound, plants, coal and bees. It''s a family read-aloud for grades 4–8. Each sitting pairs a short reading with narration, a simple home demonstration from the book, and a nature-journal entry. It''s a public-domain classic, and the full text is free online.', array['30 lessons in 10 units (one per lecture)', 'Link to the free full text for every lesson, plus the exact starting point', 'Safe home demonstrations drawn from the book', 'Narration prompts and nature-journal entries', 'Questions with answers', 'Parent notes where the 1879 science is outdated or a demo is unsafe']::text[], 30, 2, 40, 'high', true, '{}'::text[], '🧚', '#3D9970', false, '2026-11-11T12:00:00.000Z', 'pk-lib-fairy-land-of-science', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “The Fairy-Land of Science” by Arabella B. Buckley (1879), in the public domain. Free full text: https://www.gutenberg.org/ebooks/5726', '[{"title":"Lecture I: The Fairy-Land of Science — How to Enter It, How to Use It, and How to Enjoy It","lessons":["Lecture I, part 1: Science has its own fairy tales","Lecture I, part 2: How to enter, use, and enjoy fairy-land"]},{"title":"Lecture II: Sunbeams, and the Work They Do","lessons":["Lecture II, part 1: The sun, source of the sunbeams","Lecture II, part 2: What is a sunbeam?","Lecture II, part 3: Colours, and how we see","Lecture II, part 4: Light, heat, and the chemical rays at work"]},{"title":"Lecture III: The Aerial Ocean in Which We Live","lessons":["Lecture III, part 1: What the air is made of","Lecture III, part 2: The weight of the air","Lecture III, part 3: The barometer and the winds"]},{"title":"Lecture IV: A Drop of Water on Its Travels","lessons":["Lecture IV, part 1: Steam, vapour, and clouds","Lecture IV, part 2: Rain, dew, hail, and crystals","Lecture IV, part 3: Snow, ice, glaciers, and the salty sea"]},{"title":"Lecture V: The Two Great Sculptors — Water and Ice","lessons":["Lecture V, part 1: Rain and rivers carve the land","Lecture V, part 2: Ravines, waterfalls, and canyons","Lecture V, part 3: Deltas, caves, sea-cliffs, and glaciers"]},{"title":"Lecture VI: The Voices of Nature, and How We Hear Them","lessons":["Lecture VI, part 1: What sound is","Lecture VI, part 2: Echoes and the ear","Lecture VI, part 3: Music, noise, thunder, and living voices"]},{"title":"Lecture VII: The Life of a Primrose","lessons":["Lecture VII, part 1: The seed and the plantlet","Lecture VII, part 2: How a plant feeds itself","Lecture VII, part 3: The flower and its seed"]},{"title":"Lecture VIII: The History of a Piece of Coal","lessons":["Lecture VIII, part 1: Into the coal-mine","Lecture VIII, part 2: The coal forest and the Great Dismal Swamp","Lecture VIII, part 3: From peat to coal, and what coal gives us"]},{"title":"Lecture IX: Bees in the Hive","lessons":["Lecture IX, part 1: A city of bees","Lecture IX, part 2: Cells, honey, and young bees","Lecture IX, part 3: Swarms, queens, and the busy hive"]},{"title":"Lecture X: Bees and Flowers","lessons":["Lecture X, part 1: Why flowers wear colours and scents","Lecture X, part 2: Geranium, dead-nettle, salvia, and violet","Lecture X, part 3: Bird''s-foot trefoil, orchis, and helping one another"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-fairy-land-of-science', 1, '{"units":[{"id":"fairy-land-of-science-u1","title":"Lecture I: The Fairy-Land of Science — How to Enter It, How to Use It, and How to Enjoy It","lessons":[{"id":"fairy-land-of-science-1-1","title":"Lecture I, part 1: Science has its own fairy tales","steps":["Read aloud from the start of Lecture I up to ''One picture more''","Child narrates the frozen-brook ''Sleeping Beauty'' story and names the invisible ''fairies'' (heat, cohesion, gravitation, crystallization, life)","Demonstration: drip water from a spoon onto wax paper or a leaf and watch each drop pull itself round (cohesion at work)","Nature journal: draw one raindrop''s journey from cloud to ground and label which ''fairy'' acts at each step"],"links":[{"label":"Read Lecture I (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00005"}],"pages":"From the opening (''I have promised to introduce you'') to the snowdrop in the garden","questions":["What does Buckley say holds the water drops together into round drops?","Which invisible force pulls the raindrops down to the earth?","What shape does every good snowflake have?"],"answers":["Cohesion","Gravitation","A six-pointed star (crystal)"],"notes":"Buckley''s ''fairies'' are a teaching image for natural forces and energy; she says so herself in her footnote. Enjoy the metaphor, then name the real force each time."},{"id":"fairy-land-of-science-1-2","title":"Lecture I, part 2: How to enter, use, and enjoy fairy-land","steps":["Read aloud from ''One picture more'' to the end of the lecture","Narrate: why does Buckley say a coal fire warms us with ''sunbeams of ages ago''?","Demonstration: breathe on a cold window or mirror and watch drops form (as little Cissy did); then stir sugar into water and set a spoonful aside to dry out and leave the sugar behind","Nature journal: sketch one everyday object near you and write a question about its ''history''"],"links":[{"label":"Read Lecture I (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00005"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00034"}],"pages":"From ''One picture more'' to the end of Lecture I","questions":["How do the particles behave in a solid, a liquid, and a gas?","When sugar dissolves in water, is that chemical attraction? How can you tell?","What made the ''rain inside'' on Cissy''s window?"],"answers":["Solid: locked tightly together; liquid: held together but able to roll past each other; gas: flying apart and spreading out","No; the water can dry away and the sugar is left unchanged","Water from their breath condensing on the cold glass"],"notes":"Do NOT try the potassium-in-water demonstration; it is dangerous. Her formula ''K + H2O = KHO + H'' is old notation; today it is written 2K + 2H2O → 2KOH + H2."}]},{"id":"fairy-land-of-science-u2","title":"Lecture II: Sunbeams, and the Work They Do","lessons":[{"id":"fairy-land-of-science-2-1","title":"Lecture II, part 1: The sun, source of the sunbeams","steps":["Read aloud from the start of Lecture II to the cooling ''veil'' of water particles","Narrate the express-train journey to the sun and the giant stuffing earths into the ''sun-ball''","Demonstration: in a dark room, shine a flashlight (the ''sun'') on a ball with a sticker on it (your home) and turn the ball slowly to show sunrise","Nature journal: draw the sun with a row of tiny earths across its face"],"links":[{"label":"Read Lecture II (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00067"}],"pages":"From the opening of Lecture II to the end of the magnifying-glass passage","questions":["Is it the sun that moves at sunrise, or the earth?","About how many earths would it take to fill the sun, by Buckley''s count?","What protects us from the full fierce heat of the sun''s rays?"],"answers":["The earth turns","About 1,331,000 (more than a million)","Tiny particles of water vapour in the air"],"notes":"Modern figures: the sun is about 93 million miles away and about 865,000 miles across. Never look at the sun or focus it with a magnifying glass; skip the burning-paper trick."},{"id":"fairy-land-of-science-2-2","title":"Lecture II, part 2: What is a sunbeam?","steps":["Read aloud from ''We have now learnt something of the distance'' to the end of the prism passage","Narrate the two ways of touching something far away, and which one Buckley says light uses","Demonstration: drop a pebble in a basin and watch ripples travel to the edge; then set a glass of water in a sunny window and find the rainbow it throws","Nature journal: paint or colour the spectrum in order: red, orange, yellow, green, blue, indigo, violet"],"links":[{"label":"Read Lecture II (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00067"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00083"}],"pages":"From ''We have now learnt something of the distance'' to the prism and its colours","questions":["Did Newton think light was made of particles or waves?","How long does a sunbeam take to reach us from the sun, according to Buckley?","What happens to sunlight when it passes through a prism?"],"answers":["Particles (tiny bits thrown out by the sun)","About seven and a half minutes","It is split into a band of colours"],"notes":"The ''ether'' was later shown not to exist; light needs no medium and crosses empty space as an electromagnetic wave. Light actually takes about 8 minutes 20 seconds to arrive and travels about 186,000 miles per second."},{"id":"fairy-land-of-science-2-3","title":"Lecture II, part 3: Colours, and how we see","steps":["Read aloud from ''Till now we have talked of the sunbeam'' to the leaf digesting its food","Narrate why a leaf looks green","Demonstration: make a spinning colour wheel from card painted in rainbow colours and spin it on a pencil to see it turn whitish","Nature journal: collect three coloured leaves or petals and write which colour each sends back to your eye"],"links":[{"label":"Read Lecture II (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00067"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00097"}],"pages":"From ''Till now we have talked of the sunbeam'' to how leaves use sunlight","questions":["Which waves are larger and lazier, red or violet?","Why can you often not see a clean pane of glass?","Why can you see a white tablecloth in a dim room but not a black coat?"],"answers":["Red","It lets nearly all the light waves pass through instead of sending them back to your eye","White sends back nearly all the light waves; black sends back hardly any"],"notes":"Old mirrors were backed with quicksilver (mercury); modern mirrors use aluminium or silver, which is much safer."},{"id":"fairy-land-of-science-2-4","title":"Lecture II, part 4: Light, heat, and the chemical rays at work","steps":["Read aloud from ''We all know that a plant becomes pale'' to the end of the lecture","Narrate how the warmth of your breath was once in a sunbeam","Demonstration: lay lace or leaves on sun-print (cyanotype) paper in the sun, then rinse it as the packet directs, a safe modern version of Buckley''s lace picture","Nature journal: list five things in your house whose heat or light came first from the sun"],"links":[{"label":"Read Lecture II (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00067"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00112"}],"pages":"From ''We all know that a plant becomes pale'' to the end of Lecture II","questions":["What happens to a plant kept away from sunlight?","Can you see the ''dark heat-rays'' from a warm iron? How do you know they are there?","What did the sunbeams do to the nitrate-of-silver paper under the lace?"],"answers":["It becomes pale and sickly","No, you cannot see them, but you can feel them as heat on your face","Turned it dark brown, leaving a light picture of the lace where the threads blocked the sun"],"notes":"Her ''dark heat-rays'' are what we call infrared, and her ''chemical rays'' are mostly ultraviolet and blue light. Don''t handle silver nitrate; use sun-print paper instead. Burning coal also releases carbon dioxide, a link worth discussing with older children."}]},{"id":"fairy-land-of-science-u3","title":"Lecture III: The Aerial Ocean in Which We Live","lessons":[{"id":"fairy-land-of-science-3-1","title":"Lecture III, part 1: What the air is made of","steps":["Read aloud from the start of Lecture III to the heap of papers","Narrate the being who could see gases looking at us ''deep-air creatures''","Demonstration (adult lights it): stand a tea-light in a dish of water, cover it with a glass jar, and watch the flame go out once the oxygen is used","Nature journal: draw a fish in water and a person in air side by side, and label each ''ocean''"],"links":[{"label":"Read Lecture III (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00121"}],"pages":"From the opening of Lecture III to the heap of papers pressing down","questions":["What two gases make up most of the air?","Which gas is used up when something burns or when we breathe?","Why is it good that air is not made entirely of oxygen?"],"answers":["Oxygen and nitrogen","Oxygen","Everything would burn far too fast; fires could not be stopped"],"notes":"Air is about 78% nitrogen, 21% oxygen and nearly 1% argon (argon was discovered in 1894). Her ''carbonic acid gas'' is carbon dioxide. In the jar demo the water rises mostly because the air cools, not only because oxygen is used up. Do not try the phosphorus experiment."},{"id":"fairy-land-of-science-3-2","title":"Lecture III, part 2: The weight of the air","steps":["Read aloud from the pop-gun to the description of the barometer","Narrate Mr. Glaisher''s balloon ascent and why he fainted","Demonstration (over a sink): fill a glass to the brim, press a card on top, turn it over and let go; the air holds the card up","Nature journal: watch for shooting stars on a clear night and record the date, time and direction"],"links":[{"label":"Read Lecture III (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00121"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00137"}],"pages":"From the pop-gun to the barometer","questions":["How much weight does the air press on each square inch at sea level?","How did meteors show that the atmosphere is more than 100 miles high?","Why does a limpet cling so tightly to a rock?"],"answers":["About 15 pounds","They glow by rubbing against air at least 100 miles up, so there must be air that high","It pushes out the air under its shell and the weight of the air presses it down"],"notes":"Meteors mostly burn up about 50–75 miles up; the air fades out gradually with no sharp top. The big meteor showers now peak around August 12 and November 17."},{"id":"fairy-land-of-science-3-3","title":"Lecture III, part 3: The barometer and the winds","steps":["Read aloud from ''But why will it not remain more than 30 inches'' to the end of the lecture","Narrate the schoolboys rushing out of the crowded room, and what it tells us about wind","Demonstration: dip a straw in water, put a finger over the top and lift; the water stays in, like Buckley''s U-tube","Nature journal: note the wind direction and the weather each day this week; if you have a barometer, record it too"],"links":[{"label":"Read Lecture III (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00121"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00152"}],"pages":"From ''But why will it not remain more than 30 inches high'' to the end of Lecture III","questions":["When the mercury in a barometer falls, what weather do we often expect?","Which way does the breeze usually blow at the seaside by day, and why?","Why does sunlight reach into shady corners on earth, but not on the moon?"],"answers":["Rain","From the sea to the land, because the land heats up and its warm air rises, so cooler sea air rushes in","Tiny particles in our air scatter the light; the moon has no air to scatter it"],"notes":"Falling pressure usually comes from moving weather systems, not only from damp air. Mercury is poisonous; handle only sealed instruments."}]},{"id":"fairy-land-of-science-u4","title":"Lecture IV: A Drop of Water on Its Travels","lessons":[{"id":"fairy-land-of-science-4-1","title":"Lecture IV, part 1: Steam, vapour, and clouds","steps":["Read aloud from the start of Lecture IV to the clouds resting on columns of vapour","Narrate what happens inside a kettle as it boils","Demonstration (adult only near the kettle): look for the clear gap just above the spout before the cloud begins; hold a cold plate in the cloud with an oven mitt and catch the ''water-dust''","Nature journal: sketch today''s clouds and mark where their flat bottoms are"],"links":[{"label":"Read Lecture IV (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00171"}],"pages":"From the opening of Lecture IV to the flat-bottomed summer clouds","questions":["Why can''t you see steam right at the mouth of the kettle?","What did Dr. Tyndall call the tiny drops in a cloud?","Why does rising damp air form clouds?"],"answers":["It is still hot enough to be an invisible gas","Water-dust","As it rises it spreads out and cools, and the vapour gathers into tiny drops"],"notes":"Steam burns badly; keep children''s hands well back from the spout."},{"id":"fairy-land-of-science-4-2","title":"Lecture IV, part 2: Rain, dew, hail, and crystals","steps":["Read aloud from the forming of rain to the growing of crystals","Narrate why there is dew on the grass but none on the gravel path","Demonstration: set a glass of ice water on the table and watch ''artificial dew'' form on the outside; also dissolve salt in warm water, pour a little on a dark plate and leave it to dry into cubes","Nature journal: go out early one morning and record where you find dew and where you don''t"],"links":[{"label":"Read Lecture IV (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00171"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00183"}],"pages":"From ''And now, suppose that while these or any other kind of clouds'' to growing nitre crystals","questions":["What happens when wet winds are pushed up cold mountains?","How does water vapour in the air help us on a summer night?","What is the difference between how hail forms and how snow forms?"],"answers":["The air cools and drops its water as rain","It holds in the earth''s heat so the ground does not freeze","Hail is a raindrop that freezes; snow forms when vapour freezes into crystals before becoming a drop"],"notes":"Her vapour ''veil'' that keeps nights warm is part of what we now call the greenhouse effect."},{"id":"fairy-land-of-science-4-3","title":"Lecture IV, part 3: Snow, ice, glaciers, and the salty sea","steps":["Read aloud from the bar magnets to the end of the lecture","Narrate the whole round trip of the water drop from tropical sea back to the sea","Demonstration: fill a small plastic tub to the brim with water, freeze it overnight, and see the ice bulge above the rim; play with two magnets to feel them attract and push apart","Nature journal: catch snowflakes on dark cloth (or draw six-sided ones) and draw what you see"],"links":[{"label":"Read Lecture IV (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00171"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00199"}],"pages":"From the bar magnets to the end of Lecture IV","questions":["Why do water pipes burst in a hard frost?","How is a glacier made?","Why is the sea salty?"],"answers":["Water expands when it freezes and cracks the pipe","Snow piles up and is pressed together until it becomes solid ice that creeps down the valley","Rivers carry dissolved salts to the sea; the sun lifts out only pure water and leaves the salts behind"],"notes":"Water molecules aren''t tiny magnets; they line up in a six-sided pattern because of electrical attraction (hydrogen bonds), but the magnet picture is a good start. About nine-tenths of an iceberg is underwater."}]},{"id":"fairy-land-of-science-u5","title":"Lecture V: The Two Great Sculptors — Water and Ice","lessons":[{"id":"fairy-land-of-science-5-1","title":"Lecture V, part 1: Rain and rivers carve the land","steps":["Read aloud from the start of Lecture V to the Rhine''s oyster-shells","Narrate how the earth-pillars got their capping stones","Demonstration: fill a jar with muddy water from a stream or puddle and leave it overnight to see how much soil settles","Nature journal: after a rain shower, sketch the little rills on a sloping path and how they join"],"links":[{"label":"Read Lecture V (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00219"}],"pages":"From the opening of Lecture V to the carbonate of lime carried by the Rhine","questions":["How does Buckley say a sculptor is like water?","What is left at the bottom of a glass of river water after it stands?","What forms the hard crust inside a kettle in chalk country?"],"answers":["Both slowly cut and shape a rough block into beautiful forms","A layer of mud","Carbonate of lime (chalk) from the water"]},{"id":"fairy-land-of-science-5-2","title":"Lecture V, part 2: Ravines, waterfalls, and canyons","steps":["Read aloud from St. Paul''s churchyard to how gravel, sand and mud settle","Narrate the history of the little ravine from furrow to fern-covered valley","Demonstration: shake gravel, sand and soil in a jar of water and watch which settles first","Nature journal: draw the layers that settled in your jar and label them"],"links":[{"label":"Read Lecture V (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00219"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00235"}],"pages":"From St. Paul''s churchyard full of oyster shells to the sinking gravel","questions":["How are pot-holes made beside a waterfall?","About how fast did Lyell think Niagara Falls ate back the cliff?","In moving water, which drops first: big stones or fine sand?"],"answers":["Water swirls pebbles round and round in a hollow and grinds the rock","About one foot a year","Big stones"],"notes":"Modern estimates say Niagara''s gorge took roughly 12,000 years and the Grand Canyon about 5–6 million years. Both are slow, just as Buckley says."},{"id":"fairy-land-of-science-5-3","title":"Lecture V, part 3: Deltas, caves, sea-cliffs, and glaciers","steps":["Read aloud from the Nile to the end of the lecture","Narrate how a glacier works like a carpenter''s plane","Demonstration: build a sloping sand tray, trickle water from a watering can down it into a ''sea'', and watch a delta grow","Nature journal: draw a stalactite and stalagmite meeting, and mark which hangs down"],"links":[{"label":"Read Lecture V (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00219"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00248"}],"pages":"From the history of the Nile to the end of Lecture V","questions":["What is a delta made of?","What is the difference between a stalactite and a stalagmite?","How can you tell a boulder was carried by ice rather than rolled by water?"],"answers":["Mud carried down by the river and dropped at its mouth","A stalactite hangs from the roof; a stalagmite grows up from the floor","Its edges are still sharp; water would have rounded them"],"notes":"We now know of several ice ages; the last ended about 11,700 years ago. Kentucky''s Mammoth Cave has since been mapped to over 400 miles."}]},{"id":"fairy-land-of-science-u6","title":"Lecture VI: The Voices of Nature, and How We Hear Them","lessons":[{"id":"fairy-land-of-science-6-1","title":"Lecture VI, part 1: What sound is","steps":["Read aloud from the start of Lecture VI to the ''globes'' of sound spreading from a clap","Narrate the row of boxwood balls and the bell","Demonstration: tie a metal spoon to the middle of a string, wrap the ends round your fingers and hold them to your ears, then tap the spoon on a table","Nature journal: sit still outside for five minutes and list every sound you hear"],"links":[{"label":"Read Lecture VI (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00269"}],"pages":"From the opening of Lecture VI to sound spreading on all sides","questions":["What two things are needed for us to hear?","What are a ''condensation'' and a ''rarefaction''?","Which makes shorter sound waves, a man''s bass voice or a woman''s voice?"],"answers":["Something moving the air, and an ear (hearing instrument) to receive it","A crowding together of air particles, and a spreading apart of them","A woman''s voice"],"notes":"Today scientists call the wave itself ''sound'' whether or not anyone hears it; Buckley means the sensation."},{"id":"fairy-land-of-science-6-2","title":"Lecture VI, part 2: Echoes and the ear","steps":["Read aloud from why sound grows fainter to the harp-strings of the inner ear","Narrate the journey of a sound from the air to the brain: drum, hammer, anvil, stirrup, fluid, nerve","Demonstration: find a big wall or cliff, pace at least 60 feet away and clap to hear an echo; or whisper through a long tube or garden hose","Nature journal: draw and label the outer ear, eardrum and three little bones"],"links":[{"label":"Read Lecture VI (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00269"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00288"}],"pages":"From why sound grows fainter to Corti''s organ","questions":["How far from a wall must you stand to hear a separate echo?","Name the three little bones in the ear.","Why could Biot hear a whisper half a mile through a tube?"],"answers":["At least 56 feet","Hammer, anvil, and stirrup","The tube kept the sound waves from spreading out"],"notes":"The tiny stones (otoliths) in the inner ear help with balance rather than prolonging sound. Never put anything into the ear canal."},{"id":"fairy-land-of-science-6-3","title":"Lecture VI, part 3: Music, noise, thunder, and living voices","steps":["Read aloud from noise and musical notes to the end of the lecture","Narrate why the little brook sings while the deep river is quiet","Demonstration: run a stick along a picket fence, then blow across bottles holding different amounts of water and compare the notes","Nature journal: listen to one bird for a few minutes and describe its song in words or marks"],"links":[{"label":"Read Lecture VI (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00269"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00307"}],"pages":"From ''But why then do we not hear all sounds as music?'' to the end of Lecture VI","questions":["What makes a sound a musical note instead of a noise?","Do quicker vibrations make a higher or a lower note?","Why do we see lightning before we hear thunder?"],"answers":["The shocks come quickly and regularly","Higher","Light travels far faster than sound"],"notes":"Two corrections: sound covers about a mile in 5 seconds (not half a mile), and insects buzz mainly from their fast wingbeats, not from wings scraping their legs. The ''sea'' in a shell is room noise echoing inside it."}]},{"id":"fairy-land-of-science-u7","title":"Lecture VII: The Life of a Primrose","lessons":[{"id":"fairy-land-of-science-7-1","title":"Lecture VII, part 1: The seed and the plantlet","steps":["Read aloud from the start of Lecture VII to the mustard seed-leaves","Narrate how the plantlet feeds before it has roots or leaves","Demonstration: soak a large bean overnight, peel it, split the halves and find the tiny plantlet; peel a segment of orange to see its juice cells","Nature journal: draw the opened bean and label the seed-leaves, root end and shoot"],"links":[{"label":"Read Lecture VII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00328"}],"pages":"From the opening of Lecture VII to the seed-leaves coming above ground","questions":["What are the two halves of an almond (or bean) seed?","What does the young plantlet eat at first?","How does a plant grow bigger, cell by cell?"],"answers":["Seed-leaves that hold and feed the plantlet","The stored food (starch, oils, sugar) in its seed-leaves","Each cell fills up and divides into two, again and again"],"notes":"Buckley uses a soaked almond; a soaked lima or broad bean works the same way and avoids nut allergies. Her ''protoplasm'' is the living contents of the cell."},{"id":"fairy-land-of-science-7-2","title":"Lecture VII, part 2: How a plant feeds itself","steps":["Read aloud from ''And now the plant can no longer afford to be idle'' to the stored food in the underground stem","Narrate how water climbs from the roots to the leaves","Demonstration: fill a glass with water, put fresh leaves in, turn it upside down in a saucer of water and set it in the sun; look for oxygen bubbles after an hour","Nature journal: press a leaf and label where its green cells and its stomates are"],"links":[{"label":"Read Lecture VII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00328"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00343"}],"pages":"From ''And now the plant can no longer afford to be idle'' to the primrose''s underground stem","questions":["What can plants make food from that we cannot?","What gives leaves their green colour?","What do the stomates on the underside of a leaf do?"],"answers":["Water, gases from the air, and minerals (matter that was never alive)","Chlorophyll","Open to let out extra water (and close to keep it in when the air is dry)"],"notes":"The oxygen a leaf gives off actually comes from splitting water, not from carbon dioxide (discovered in 1941). Stomates also let carbon dioxide in. Do NOT try the sugar-and-sulphuric-acid experiment."},{"id":"fairy-land-of-science-7-3","title":"Lecture VII, part 3: The flower and its seed","steps":["Read aloud from the flower buds to the end of the lecture","Narrate why the primrose needs insects, and how they carry pollen between the two kinds of flower","Demonstration: gently take apart a simple flower (primrose, buttercup or tulip) and find calyx, corolla, stamens, and pistil with a magnifying glass","Nature journal: draw and label the flower parts you found"],"links":[{"label":"Read Lecture VII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00328"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00360"}],"pages":"From ''We have now seen how a plant springs up'' to the end of Lecture VII","questions":["What is the yellow dust in the anthers called?","What must happen before an ovule can become a seed?","Why does the primrose have a bright, sweet-scented crown?"],"answers":["Pollen","Pollen must land on the stigma and send a tube down to the ovule","To attract insects that carry pollen from flower to flower"],"notes":"Primroses really do come in two forms (''pin'' and ''thrum''); Darwin''s work on them still holds. Children with pollen allergies may want gloves."}]},{"id":"fairy-land-of-science-u8","title":"Lecture VIII: The History of a Piece of Coal","lessons":[{"id":"fairy-land-of-science-8-1","title":"Lecture VIII, part 1: Into the coal-mine","steps":["Read aloud from the start of Lecture VIII to the scaly trees","Narrate the imaginary journey down the shaft: roof, floor and coal","Demonstration: look closely at a piece of barbecue charcoal or coal with a magnifying glass for thin layers; press a fern leaf into soft clay to make a ''fossil'' print","Nature journal: draw the coal ''sandwich'': underclay with roots, coal, and shale roof with leaf prints"],"links":[{"label":"Read Lecture VIII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00378"}],"pages":"From the opening of Lecture VIII to the Lepidodendrons","questions":["What do we find in the shale roof of a coal-mine?","What living plant is most like the giant scaly trees of the coal forests?","How do coal balls prove that coal is made of plants?"],"answers":["Impressions of ferns, reeds and other plants","The little club-moss (Selaginella)","Thin slices show leaves, stems and spores that match the plants above and below the coal"],"notes":"Coal forests grew about 300–360 million years ago, in the Carboniferous period, far longer ago than Buckley could know."},{"id":"fairy-land-of-science-8-2","title":"Lecture VIII, part 2: The coal forest and the Great Dismal Swamp","steps":["Read aloud from the Sigillaria to the jungle of plants fringing the coal-swamp","Narrate how the swamp stayed free of mud","Demonstration: pour muddy water through a thick pad of grass or moss in a funnel and compare it with the muddy water","Nature journal: look for horsetails or club-moss on a walk and sketch them"],"links":[{"label":"Read Lecture VIII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00378"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00395"}],"pages":"From the Sigillaria to the coal-swamp fringed with ferns","questions":["What modern marsh plant is a small cousin of the Calamite?","What is peat made of?","Why did the streams entering the Dismal Swamp bring clear water?"],"answers":["The horsetail (Equisetum)","The remains of plants that lived and died in the swamp","The thick reeds, ferns and shrubs around the swamp filtered out the earth"],"notes":"Coal forests were not as silent as she says: giant dragonflies and other flying insects lived there."},{"id":"fairy-land-of-science-8-3","title":"Lecture VIII, part 3: From peat to coal, and what coal gives us","steps":["Read aloud from the shale bed to the end of the lecture","Narrate what heat and pressure did to the buried plants","Demonstration: stack thin layers of different coloured clay or dough, press them under a pile of books overnight, and cut through to see the ''seams''","Nature journal: list five things Buckley says we get from coal"],"links":[{"label":"Read Lecture VIII (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00378"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00406"}],"pages":"From the shale covering the coal to the end of Lecture VIII","questions":["What two things changed beds of dead plants into hard coal?","Why does some coal burn with a flame and some only glow red?","Why did the Sussex iron-works close?"],"answers":["The great weight of rock above (pressure) and heat","Flaming coal still has its oils and gases; hard coal has lost them and is nearly pure carbon","They ran out of wood for fuel and there was no coal nearby"],"notes":"Do not try the clay-pipe coal-gas experiment. Today we know burning coal adds carbon dioxide to the air and warms the climate, which makes a good discussion for older children."}]},{"id":"fairy-land-of-science-u9","title":"Lecture IX: Bees in the Hive","lessons":[{"id":"fairy-land-of-science-9-1","title":"Lecture IX, part 1: A city of bees","steps":["Read aloud from the start of Lecture IX to the honey-gatherers hanging to make wax","Narrate how the bees build the first wall of wax","Demonstration: look closely at a piece of beeswax or a beeswax candle, then watch bees on flowers from a calm, respectful distance","Nature journal: draw a worker, a drone and a queen and note how they differ"],"links":[{"label":"Read Lecture IX (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00426"}],"pages":"From the opening of Lecture IX to bees hanging to make wax","questions":["How did Huber manage to watch bees at work?","What is propolis and what do bees use it for?","Where does a bee''s wax come from?"],"answers":["He made a hive he could open and close, with a glass hive inside","A gum from sticky buds, used to seal cracks in the hive","From little pockets under her body, made from the honey she has digested"],"notes":"Keep a calm distance from bees, and take extra care with anyone who has a sting allergy. Drones are male bees; the workers are all female."},{"id":"fairy-land-of-science-9-2","title":"Lecture IX, part 2: Cells, honey, and young bees","steps":["Read aloud from the nursing bees to the princess in her royal cell","Narrate the life of a young bee from egg to worker","Demonstration: bundle drinking straws tightly with a rubber band and look at the ends, or squeeze round balls of play-dough together, to see circles pressed into six-sided shapes","Nature journal: draw a few six-sided cells and show which hold honey, bee-bread and eggs"],"links":[{"label":"Read Lecture IX (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00426"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00438"}],"pages":"From the nursing bees to the royal jelly","questions":["Why are honeycomb cells six-sided?","What is bee-bread?","How many days after the egg is laid does a worker bee come out of her cell?"],"answers":["It is the closest-fitting shape; it fills every bit of space and uses the least wax","Pollen stored in the comb","21 days"],"notes":"A queen can actually lay well over 1,000 eggs a day at the height of summer, far more than 200. Drones take about 24 days to develop."},{"id":"fairy-land-of-science-9-3","title":"Lecture IX, part 3: Swarms, queens, and the busy hive","steps":["Read aloud from the eldest princess to the end of the lecture","Narrate why the old queen leaves with a swarm","Demonstration: fan a paper fan at the open end of a cardboard box with a tissue strip hanging inside to see how fanning bees move air through the hive","Nature journal: list all the different jobs bees do in the hive"],"links":[{"label":"Read Lecture IX (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00426"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00454"}],"pages":"From the eldest princess to the end of Lecture IX","questions":["Why are the royal eggs laid a few days apart?","How do bees keep the hive cool and fresh?","What do bees do with a slug too heavy to carry out?"],"answers":["So one princess can leave with a swarm before the next one comes out","Some bees stand at the entrance and fan their wings to make a current of air","Seal it over with propolis so it cannot decay"],"notes":"Summer workers live about six weeks; only the autumn-born bees last through winter. Queens may live two to five years."}]},{"id":"fairy-land-of-science-u10","title":"Lecture X: Bees and Flowers","lessons":[{"id":"fairy-land-of-science-10-1","title":"Lecture X, part 1: Why flowers wear colours and scents","steps":["Read aloud from the start of Lecture X to the drooping bell-flowers","Narrate what the bee does for the flower in return for honey","Demonstration (outdoors): set out squares of coloured paper, each with a drop of sugar water, and watch from a distance which colours insects visit, a simple version of Lubbock''s test","Nature journal: note three flowers that close at night or before rain, or that smell stronger in the evening"],"links":[{"label":"Read Lecture X (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00469"}],"pages":"From the opening of Lecture X to drooping bell-flowers","questions":["Why do grasses and oak trees not need bright flowers?","How did Lubbock show bees remember colours?","Why do bell-shaped flowers often hang their heads?"],"answers":["The wind carries their pollen","Bees trained to find honey on blue glass still went to the blue glass first after the honey was moved","To keep rain and dew out of the honey"],"notes":"Bees see blue and ultraviolet well but are nearly blind to red. Buckley says there were no flying insects in coal-forest times; there were, but flowers had not yet appeared."},{"id":"fairy-land-of-science-10-2","title":"Lecture X, part 2: Geranium, dead-nettle, salvia, and violet","steps":["Read aloud from the ants and hairy stalks to the violet''s box of pollen","Narrate how the wood-geranium keeps itself from using its own pollen","Demonstration: gently push a pencil tip into a salvia, sage or dead-nettle flower and watch the stamen swing down","Nature journal: draw the lines on a flower petal and show where they point"],"links":[{"label":"Read Lecture X (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00469"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00491"}],"pages":"From keeping honey for the right insect to the violet","questions":["Who first found out that flowers keep their honey for insects?","What do the coloured lines on many petals do?","Why does a bee visit only one kind of flower on each trip, and how does that help?"],"answers":["Christian Conrad Sprengel","They point the way to the honey","She likes the same kind of honey on each journey, so the pollen goes to the same kind of flower, where it is useful"],"notes":"Garden ''geraniums'' are really pelargoniums, as Buckley notes; they show the same tricks."},{"id":"fairy-land-of-science-10-3","title":"Lecture X, part 3: Bird''s-foot trefoil, orchis, and helping one another","steps":["Read aloud from the bird''s-foot trefoil to the end of the book","Narrate how the orchis''s pollen masses bend forward on the bee''s head","Demonstration: press gently on the side petals (wings) of a clover, pea or vetch flower and see the keel open to show the pollen","Nature journal: write one ''fairy'' you would like to study next (Buckley suggests a grain of salt, a butterfly or an ant) and a question about it"],"links":[{"label":"Read Lecture X (full text)","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00469"},{"label":"Start of today''s reading","url":"https://www.gutenberg.org/cache/epub/5726/pg5726-images.html#id00510"}],"pages":"From the inside of the bird''s-foot trefoil to the end of the book","questions":["What are the ''standard'', ''wings'' and ''keel'' of a pea-like flower?","How does the bird''s-foot trefoil manage if no bee comes?","What lesson does Buckley draw from bees and flowers helping each other?"],"answers":["The upright top petal, the two side petals, and the two joined lower petals","After a while its stigma becomes sticky and it uses its own pollen","Those who do the most for others receive the most in return"],"notes":"Wild orchids are protected in many places; observe them where they grow rather than picking them."}]}],"version":1,"license":{"kind":"public_domain"},"attribution":"Lesson plan by Freerange Library for “The Fairy-Land of Science” by Arabella B. Buckley (1879), in the public domain. Free full text: https://www.gutenberg.org/ebooks/5726"}'::jsonb)
  on conflict (listing_id, version) do update set content = excluded.content;
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-fifty-famous-stories', 'Freerange Library', 'publisher', true, 'Fifty Famous Stories Retold', array['reading', 'history']::text[], 2, 4, array['charlotte_mason', 'classical', 'traditional']::text[], 'online', 0, 'James Baldwin''s classic collection of short hero tales and legends, from King Alfred''s burned cakes to Horatius at the bridge and Whittington''s cat. Each day you read one or two stories aloud, your child tells it back, and then draws a favorite scene. A gentle first taste of history for ages 7 to 10, and the full text is free online.', array['34 lessons in 7 units covering all 50 stories', 'Link to the free full text for every story', 'A narration prompt and a drawing prompt for each lesson', 'One question per story, with answers', 'Parent notes on legends and dated passages']::text[], 34, 3, 15, 'high', true, '{}'::text[], '🏰', '#E3A33B', false, '2026-11-11T12:00:00.000Z', 'pk-lib-fifty-famous-stories', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “Fifty Famous Stories Retold” by James Baldwin (1896), in the public domain. Free full text: https://www.gutenberg.org/ebooks/18442', '[{"title":"Unit 1: Kings and Outlaws of Old England","lessons":["Lesson 1: King Alfred and the Cakes and King Alfred and the Beggar","Lesson 2: King Canute on the Seashore and The Sons of William the Conqueror","Lesson 3: The White Ship","Lesson 4: King John and the Abbot","Lesson 5: A Story of Robin Hood"]},{"title":"Unit 2: Scotland, Gotham, and Brave Englishmen","lessons":["Lesson 6: Bruce and the Spider and The Black Douglas","Lesson 7: Three Men of Gotham and Other Wise Men of Gotham","Lesson 8: The Miller of the Dee and Sir Philip Sidney","Lesson 9: The Ungrateful Soldier and Sir Humphrey Gilbert","Lesson 10: Sir Walter Raleigh"]},{"title":"Unit 3: Heroes of America, the Sea, and the Mountains","lessons":["Lesson 11: Pocahontas and George Washington and his Hatchet","Lesson 12: Grace Darling","Lesson 13: The Story of William Tell and Arnold Winkelried","Lesson 14: The Bell of Atri"]},{"title":"Unit 4: Stories of Old Rome","lessons":["Lesson 15: How Napoleon crossed the Alps and The Story of Cincinnatus","Lesson 16: The Story of Regulus and Cornelia''s Jewels","Lesson 17: Androclus and the Lion","Lesson 18: Horatius at the Bridge","Lesson 19: Julius Cæsar and The Sword of Damocles"]},{"title":"Unit 5: Stories of Greece (and a Hawk)","lessons":["Lesson 20: Damon and Pythias and A Laconic Answer","Lesson 21: The Ungrateful Guest and Alexander and Bucephalus","Lesson 22: Diogenes the Wise Man and The Brave Three Hundred","Lesson 23: Socrates and his House and The King and his Hawk"]},{"title":"Unit 6: Stories from Many Lands","lessons":["Lesson 24: Doctor Goldsmith and The Kingdoms","Lesson 25: The Barmecide Feast","Lesson 26: The Endless Tale and The Blind Men and the Elephant","Lesson 27: Maximilian and the Goose Boy","Lesson 28: The Inchcape Rock"]},{"title":"Unit 7: Longer Tales","lessons":["Lesson 29: Whittington and his Cat (Parts I–II)","Lesson 30: Whittington and his Cat (Parts III–V)","Lesson 31: Casabianca","Lesson 32: Antonio Canova","Lesson 33: Picciola","Lesson 34: Mignon"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-fifty-famous-stories', 1, '{"units":[{"id":"fifty-famous-stories-u1","title":"Unit 1: Kings and Outlaws of Old England","lessons":[{"id":"fifty-famous-stories-1-1","title":"Lesson 1: King Alfred and the Cakes and King Alfred and the Beggar","steps":["Read “King Alfred and the Cakes” and “King Alfred and the Beggar” aloud together","Tell back both Alfred stories in order: the burned cakes, then the beggar at the door","Draw Alfred by the hearth with the cakes smoking"],"links":[{"label":"Read “King Alfred and the Cakes”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#FIFTY_FAMOUS_STORIES_RETOLD"},{"label":"Read “King Alfred and the Beggar”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#KING_ALFRED_AND_THE_BEGGAR"}],"pages":"pp. 5–9","questions":["Why did King Alfred let the cakes burn?","What did Alfred give the beggar?"],"answers":["He was busy thinking about how to gather his army and beat the Danes","Half of his only loaf and half of his wine"]},{"id":"fifty-famous-stories-1-2","title":"Lesson 2: King Canute on the Seashore and The Sons of William the Conqueror","steps":["Read “King Canute on the Seashore” and “The Sons of William the Conqueror” aloud together","Narrate how Canute taught his officers a lesson, then what each prince chose to be","Draw Canute''s chair at the water''s edge, or the three princes'' birds"],"links":[{"label":"Read “King Canute on the Seashore”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#KING_CANUTE_ON_THE_SEASHORE"},{"label":"Read “The Sons of William the Conqueror”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_SONS_OF_WILLIAM_THE_CONQUEROR"}],"pages":"pp. 10–16","questions":["What did Canute command the sea to do?","Which bird did Henry, the Handsome Scholar, choose?"],"answers":["Come no farther and not touch his feet","A starling"]},{"id":"fifty-famous-stories-1-3","title":"Lesson 3: The White Ship","steps":["Read “The White Ship” aloud together","Narrate the voyage of the White Ship from the merry start to the sad end","Draw the white ship with its white sails under the full moon"],"links":[{"label":"Read “The White Ship”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_WHITE_SHIP"}],"pages":"pp. 17–20","questions":["Why did Prince William row back to the sinking ship?"],"answers":["To save his little sister"],"notes":"The ending is sad: the prince and nearly everyone aboard drown. The poem at the end is a nice one to read aloud."},{"id":"fifty-famous-stories-1-4","title":"Lesson 4: King John and the Abbot","steps":["Read “King John and the Abbot” aloud together","Narrate the three questions and the shepherd''s three clever answers","Draw the shepherd throwing off the abbot''s gown before King John"],"links":[{"label":"Read “King John and the Abbot”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#KING_JOHN_AND_THE_ABBOT"}],"pages":"pp. 21–27","questions":["What did the shepherd say the king was thinking?"],"answers":["That he was the Abbot of Canterbury, but he was only the abbot''s shepherd"]},{"id":"fifty-famous-stories-1-5","title":"Lesson 5: A Story of Robin Hood","steps":["Read “A Story of Robin Hood” aloud together","Narrate how Robin Hood helped Allin-a-Dale","Draw Robin Hood dressed as a harper at the church door"],"links":[{"label":"Read “A Story of Robin Hood”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#A_STORY_OF_ROBIN_HOOD"}],"pages":"pp. 28–32","questions":["What did Robin Hood do when he blew his horn three times?"],"answers":["He called twenty-four of his men in green, with Allin-a-Dale among them, into the church"],"notes":"Baldwin admits Robin was a lawless outlaw; a good chance to talk about whether robbing the rich is ever right."}]},{"id":"fifty-famous-stories-u2","title":"Unit 2: Scotland, Gotham, and Brave Englishmen","lessons":[{"id":"fifty-famous-stories-2-1","title":"Lesson 6: Bruce and the Spider and The Black Douglas","steps":["Read “Bruce and the Spider” and “The Black Douglas” aloud together","Narrate what Bruce learned from the spider, then how the Black Douglas took the castle","Draw the spider''s web under the shed, or the men creeping like cattle toward the wall"],"links":[{"label":"Read “Bruce and the Spider”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#BRUCE_AND_THE_SPIDER"},{"label":"Read “The Black Douglas”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_BLACK_DOUGLAS"}],"pages":"pp. 33–38","questions":["How many times did the spider try before her thread reached the beam?","What did the watchman think the Black Douglas and his men were?"],"answers":["Seven","The farmer''s cattle"]},{"id":"fifty-famous-stories-2-2","title":"Lesson 7: Three Men of Gotham and Other Wise Men of Gotham","steps":["Read “Three Men of Gotham” and “Other Wise Men of Gotham” aloud together","Retell the quarrel on the bridge, then the silly things the sheriff saw in Gotham","Draw one of the ''foolish'' things the men of Gotham were doing"],"links":[{"label":"Read “Three Men of Gotham”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THREE_MEN_OF_GOTHAM"},{"label":"Read “Other Wise Men of Gotham”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#OTHER_WISE_MEN_OF_GOTHAM"}],"pages":"pp. 39–45","questions":["How did the man with the sack show Hodge and Peter they were foolish?","Why did the men of Gotham act like fools?"],"answers":["He poured all his meal into the river, then asked how much was in the sack","So the king''s sheriff would think them simple and not cut off their noses"]},{"id":"fifty-famous-stories-2-3","title":"Lesson 8: The Miller of the Dee and Sir Philip Sidney","steps":["Read “The Miller of the Dee” and “Sir Philip Sidney” aloud together","Narrate why the miller was happy, then what Sir Philip Sidney did with the cup of water","Draw the miller at work in his mill by the river"],"links":[{"label":"Read “The Miller of the Dee”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_MILLER_OF_THE_DEE"},{"label":"Read “Sir Philip Sidney”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#SIR_PHILIP_SIDNEY"}],"pages":"pp. 46–50","questions":["Which river turned the happy miller''s mill?","Who did Sir Philip Sidney give his water to?"],"answers":["The River Dee","A dying soldier lying nearby"]},{"id":"fifty-famous-stories-2-4","title":"Lesson 9: The Ungrateful Soldier and Sir Humphrey Gilbert","steps":["Read “The Ungrateful Soldier” and “Sir Humphrey Gilbert” aloud together","Narrate what the Danish soldier did after the Swede shot at him, then Sir Humphrey Gilbert''s last voyage","Draw the little ''Squirrel'' among the icebergs"],"links":[{"label":"Read “The Ungrateful Soldier”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_UNGRATEFUL_SOLDIER"},{"label":"Read “Sir Humphrey Gilbert”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#SIR_HUMPHREY_GILBERT"}],"pages":"pp. 51–53","questions":["How did the Dane ''punish'' the Swede who shot at him?","What were the names of the two ships?"],"answers":["He drank half the water and gave him only the other half","The Squirrel and the Golden Hind"],"notes":"The Gilbert story describes America as roamed by ''wild Indians''; you might point out that many Native nations already had towns and farms here."},{"id":"fifty-famous-stories-2-5","title":"Lesson 10: Sir Walter Raleigh","steps":["Read “Sir Walter Raleigh” aloud together","Narrate the cloak and the puddle, and the two plants Raleigh brought home","Draw Raleigh spreading his scarlet cloak over the puddle"],"links":[{"label":"Read “Sir Walter Raleigh”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#SIR_WALTER_RALEIGH"}],"pages":"pp. 54–57","questions":["What two things from America did Raleigh make known in England?"],"answers":["The potato and tobacco"],"notes":"Calls the Native people ''savage Indians.'' Worth a quick talk about where potatoes and tobacco came from: Native farmers had grown them for centuries."}]},{"id":"fifty-famous-stories-u3","title":"Unit 3: Heroes of America, the Sea, and the Mountains","lessons":[{"id":"fifty-famous-stories-3-1","title":"Lesson 11: Pocahontas and George Washington and his Hatchet","steps":["Read “Pocahontas” and “George Washington and his Hatchet” aloud together","Narrate the Pocahontas story, then the cherry tree story","Draw young George with his hatchet"],"links":[{"label":"Read “Pocahontas”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#POCAHONTAS"},{"label":"Read “George Washington and his Hatchet”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#GEORGE_WASHINGTON_AND_HIS_HATCHET"}],"pages":"pp. 58–60","questions":["What did Pocahontas do to save John Smith?","What did George''s father say he would rather lose than hear one lie?"],"answers":["She threw herself between him and the clubs and laid her head on his","A dozen cherry trees"],"notes":"Both are legends: historians doubt Smith''s rescue tale (the book itself says some tales are untrue), and the cherry tree story was invented by an early biographer. Pocahontas was about 11 at the time; the book calls the Powhatan people simply ''Indians'' and their leader ''king.''"},{"id":"fifty-famous-stories-3-2","title":"Lesson 12: Grace Darling","steps":["Read “Grace Darling” aloud together","Narrate the rescue from the night of the storm to the lighthouse","Draw Grace and her father rowing toward the wreck"],"links":[{"label":"Read “Grace Darling”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#GRACE_DARLING"}],"pages":"pp. 61–63","questions":["Who rowed out with Grace to save the shipwrecked men?"],"answers":["Her father, the lighthouse keeper"],"notes":"This really happened, in 1838, off the coast of northeast England."},{"id":"fifty-famous-stories-3-3","title":"Lesson 13: The Story of William Tell and Arnold Winkelried","steps":["Read “The Story of William Tell” and “Arnold Winkelried” aloud together","Narrate William Tell and the apple, then how Arnold Winkelried broke the lines","Draw Tell''s arrow and the apple, or Arnold running at the spears"],"links":[{"label":"Read “The Story of William Tell”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_STORY_OF_WILLIAM_TELL"},{"label":"Read “Arnold Winkelried”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#ARNOLD_WINKELRIED"}],"pages":"pp. 64–68","questions":["What did Tell say the second arrow was for?","What did Arnold Winkelried cry as he ran at the spears?"],"answers":["For the tyrant''s heart, if he had hurt his child","Make way for liberty!"],"notes":"Find Switzerland on a map. Arnold''s story ends with his death for his country."},{"id":"fifty-famous-stories-3-4","title":"Lesson 14: The Bell of Atri","steps":["Read “The Bell of Atri” aloud together","Narrate the story of the bell of justice and the old horse","Draw the starving horse pulling on the grapevine rope"],"links":[{"label":"Read “The Bell of Atri”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_BELL_OF_ATRI"}],"pages":"pp. 69–74","questions":["What did the judges order the miser to do?"],"answers":["Set aside half his gold to give the horse food, a pasture and a warm stall"]}]},{"id":"fifty-famous-stories-u4","title":"Unit 4: Stories of Old Rome","lessons":[{"id":"fifty-famous-stories-4-1","title":"Lesson 15: How Napoleon crossed the Alps and The Story of Cincinnatus","steps":["Read “How Napoleon crossed the Alps” and “The Story of Cincinnatus” aloud together","Narrate Napoleon''s march over the Alps, then how Cincinnatus saved Rome","Draw Cincinnatus leaving his plow in the field"],"links":[{"label":"Read “How Napoleon crossed the Alps”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#HOW_NAPOLEON_CROSSED_THE_ALPS"},{"label":"Read “The Story of Cincinnatus”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_STORY_OF_CINCINNATUS"}],"pages":"pp. 75–81","questions":["What word did Napoleon say a man who means to win never uses?","How many days was Cincinnatus ruler of Rome?"],"answers":["Impossible","Sixteen"],"notes":"The Cincinnatus story calls Rome''s enemies ''half-wild'' and ''savage'' men; that is the Romans'' side of the story."},{"id":"fifty-famous-stories-4-2","title":"Lesson 16: The Story of Regulus and Cornelia''s Jewels","steps":["Read “The Story of Regulus” and “Cornelia''s Jewels” aloud together","Narrate why Regulus went back to Carthage, then what Cornelia called her jewels","Draw Cornelia with her two sons beside her"],"links":[{"label":"Read “The Story of Regulus”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_STORY_OF_REGULUS"},{"label":"Read “Cornelia''s Jewels”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#CORNELIAS_JEWELS"}],"pages":"pp. 82–86","questions":["Why did Regulus go back to prison in Carthage?","What did Cornelia say were her jewels?"],"answers":["Because he had promised to, and a Roman keeps his word","Her two sons"],"notes":"Regulus goes back to a cruel death; the story stays brief about it."},{"id":"fifty-famous-stories-4-3","title":"Lesson 17: Androclus and the Lion","steps":["Read “Androclus and the Lion” aloud together","Narrate the story of Androclus and the lion","Draw Androclus pulling the thorn from the lion''s paw"],"links":[{"label":"Read “Androclus and the Lion”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#ANDROCLUS_AND_THE_LION"}],"pages":"pp. 87–90","questions":["What was hurting the lion?"],"answers":["A long, sharp thorn in his paw"],"notes":"Androclus was enslaved, and the crowd came to watch him be killed. A gentle opening to talk about slavery in Rome."},{"id":"fifty-famous-stories-4-4","title":"Lesson 18: Horatius at the Bridge","steps":["Read “Horatius at the Bridge” aloud together","Narrate how Horatius kept the bridge","Draw Horatius on the bridge, or leaping into the Tiber"],"links":[{"label":"Read “Horatius at the Bridge”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#HORATIUS_AT_THE_BRIDGE"}],"pages":"pp. 91–94","questions":["Which river did Horatius swim across?"],"answers":["The Tiber"]},{"id":"fifty-famous-stories-4-5","title":"Lesson 19: Julius Cæsar and The Sword of Damocles","steps":["Read “Julius Cæsar” and “The Sword of Damocles” aloud together","Narrate the two Caesar stories, then what Damocles saw over his head","Draw Damocles at the feast with the sword hanging above"],"links":[{"label":"Read “Julius Cæsar”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#JULIUS_CAESAR"},{"label":"Read “The Sword of Damocles”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_SWORD_OF_DAMOCLES"}],"pages":"pp. 95–99","questions":["What did Caesar say he would rather be than the second man in Rome?","What held up the sword over Damocles?"],"answers":["The head man of a village","A single horsehair"]}]},{"id":"fifty-famous-stories-u5","title":"Unit 5: Stories of Greece (and a Hawk)","lessons":[{"id":"fifty-famous-stories-5-1","title":"Lesson 20: Damon and Pythias and A Laconic Answer","steps":["Read “Damon and Pythias” and “A Laconic Answer” aloud together","Narrate how Damon trusted his friend, then the Spartans'' one-word answer","Draw Pythias arriving at the prison door just in time"],"links":[{"label":"Read “Damon and Pythias”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#DAMON_AND_PYTHIAS"},{"label":"Read “A Laconic Answer”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#A_LACONIC_ANSWER"}],"pages":"pp. 100–102","questions":["Why was Pythias late coming back?","What one word did the Spartans send back to King Philip?"],"answers":["He was delayed by storms and shipwreck","If"],"notes":"Try being ''laconic'' at lunch: answer in as few words as you can."},{"id":"fifty-famous-stories-5-2","title":"Lesson 21: The Ungrateful Guest and Alexander and Bucephalus","steps":["Read “The Ungrateful Guest” and “Alexander and Bucephalus” aloud together","Narrate the ungrateful guest, then how Alexander tamed Bucephalus","Draw young Alexander turning Bucephalus toward the sun"],"links":[{"label":"Read “The Ungrateful Guest”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_UNGRATEFUL_GUEST"},{"label":"Read “Alexander and Bucephalus”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#ALEXANDER_AND_BUCEPHALUS"}],"pages":"pp. 103–107","questions":["How had the farmer helped the soldier?","What was Bucephalus afraid of?"],"answers":["He cared for him after he was washed up half-drowned from a shipwreck","His own shadow"]},{"id":"fifty-famous-stories-5-3","title":"Lesson 22: Diogenes the Wise Man and The Brave Three Hundred","steps":["Read “Diogenes the Wise Man” and “The Brave Three Hundred” aloud together","Narrate the two Diogenes stories, then the stand of the three hundred","Draw Diogenes by his tub, or Diogenes with his lantern"],"links":[{"label":"Read “Diogenes the Wise Man”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#DIOGENES_THE_WISE_MAN"},{"label":"Read “The Brave Three Hundred”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_BRAVE_THREE_HUNDRED"}],"pages":"pp. 108–111","questions":["What did Diogenes ask Alexander to do for him?","Who led the three hundred Spartans in the pass?"],"answers":["Stand aside so he would not block the sunshine","Leonidas, King of the Spartans"],"notes":"Leonidas''s men all die in battle; you can keep the telling short for little ones."},{"id":"fifty-famous-stories-5-4","title":"Lesson 23: Socrates and his House and The King and his Hawk","steps":["Read “Socrates and his House” and “The King and his Hawk” aloud together","Narrate Socrates''s small house, then the story of the king and his hawk","Draw the hawk swooping at the silver cup"],"links":[{"label":"Read “Socrates and his House”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#SOCRATES_AND_HIS_HOUSE"},{"label":"Read “The King and his Hawk”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_KING_AND_HIS_HAWK"}],"pages":"pp. 112–117","questions":["What did Socrates hope to fill his little house with?","Why did the hawk keep knocking the cup away?"],"answers":["True friends","A poisonous dead snake was lying in the spring"],"notes":"Genghis Khan kills his hawk before he understands; the lesson is never to act in anger."}]},{"id":"fifty-famous-stories-u6","title":"Unit 6: Stories from Many Lands","lessons":[{"id":"fifty-famous-stories-6-1","title":"Lesson 24: Doctor Goldsmith and The Kingdoms","steps":["Read “Doctor Goldsmith” and “The Kingdoms” aloud together","Narrate Doctor Goldsmith''s ''medicine,'' then the king''s three questions to the children","Draw the children around the king in the meadow"],"links":[{"label":"Read “Doctor Goldsmith”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#DOCTOR_GOLDSMITH"},{"label":"Read “The Kingdoms”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_KINGDOMS"}],"pages":"pp. 118–122","questions":["What was really in Goldsmith''s box of ''medicine''?","To what kingdom did the boy say the orange belonged?"],"answers":["Money","The vegetable kingdom"]},{"id":"fifty-famous-stories-6-2","title":"Lesson 25: The Barmecide Feast","steps":["Read “The Barmecide Feast” aloud together","Narrate the pretend feast and the real one","Draw the Barmecide and Schacabac at the empty table"],"links":[{"label":"Read “The Barmecide Feast”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_BARMECIDE_FEAST"}],"pages":"pp. 123–126","questions":["Why did the Barmecide invite Schacabac to live with him?"],"answers":["Because he was good-humored and quick-witted and made the best of everything"],"notes":"From the Arabian Nights."},{"id":"fifty-famous-stories-6-3","title":"Lesson 26: The Endless Tale and The Blind Men and the Elephant","steps":["Read “The Endless Tale” and “The Blind Men and the Elephant” aloud together","Narrate the locust story the stranger told, then what each blind man thought","Draw the six blind men around the elephant"],"links":[{"label":"Read “The Endless Tale”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_ENDLESS_TALE"},{"label":"Read “The Blind Men and the Elephant”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_BLIND_MEN_AND_THE_ELEPHANT"}],"pages":"pp. 127–131","questions":["What did the locusts keep carrying away?","What did the man who held the tail say the elephant was like?"],"answers":["Grains of corn, one at a time","A rope"]},{"id":"fifty-famous-stories-6-4","title":"Lesson 27: Maximilian and the Goose Boy","steps":["Read “Maximilian and the Goose Boy” aloud together","Narrate the king, the book, and the geese","Draw the king chasing the geese with the whip"],"links":[{"label":"Read “Maximilian and the Goose Boy”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#MAXIMILIAN_AND_THE_GOOSE_BOY"}],"pages":"pp. 132–136","questions":["What did the goose boy say the king would never be?"],"answers":["A good gooseherd"]},{"id":"fifty-famous-stories-6-5","title":"Lesson 28: The Inchcape Rock","steps":["Read “The Inchcape Rock” aloud together","Narrate what the Abbot did and what Ralph the Rover did","Draw the bell on the buoy above the rock"],"links":[{"label":"Read “The Inchcape Rock”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#THE_INCHCAPE_ROCK"}],"pages":"pp. 137–139","questions":["What did Ralph the Rover do to the bell?"],"answers":["He cut it loose so it sank into the sea"]}]},{"id":"fifty-famous-stories-u7","title":"Unit 7: Longer Tales","lessons":[{"id":"fifty-famous-stories-7-1","title":"Lesson 29: Whittington and his Cat (Parts I–II)","steps":["Read parts I–II of “Whittington and his Cat” aloud together","Narrate how Dick came to London and why he bought a cat","Draw the eight-horse wagon on the road to London"],"links":[{"label":"Read “Whittington and his Cat”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#WHITTINGTON_AND_HIS_CAT"}],"pages":"pp. 140–144","questions":["What did Dick hear people say London''s streets were paved with?","Why did Dick buy a cat?"],"answers":["Gold","To drive away the rats and mice in his garret"],"notes":"Read parts I and II (The City, The Kitchen) today."},{"id":"fifty-famous-stories-7-2","title":"Lesson 30: Whittington and his Cat (Parts III–V)","steps":["Read parts III–V of “Whittington and his Cat” aloud together","Narrate the ship''s voyage, the cat at the palace, and Dick''s fortune","Draw the cat chasing the rats from the king''s table"],"links":[{"label":"Read “Whittington and his Cat”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#WHITTINGTON_AND_HIS_CAT"}],"pages":"pp. 144–152","questions":["What did the bells of Bow Church seem to say to Dick?","Whom did Dick marry?"],"answers":["Turn again, Whittington, thrice Lord Mayor of London","Alice, Mr. Fitzwarren''s daughter"],"notes":"Read parts III–V (The Venture, The Cat, The Fortune). The book says the people there had ''never seen any white men'' and pokes fun at the queen''s English; a good chance to talk about how travelers'' tales treated other peoples."},{"id":"fifty-famous-stories-7-3","title":"Lesson 31: Casabianca","steps":["Read “Casabianca” aloud together","Narrate what happened on the burning ship","Draw the boy standing on the deck"],"links":[{"label":"Read “Casabianca”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#CASABIANCA"}],"pages":"pp. 153–155","questions":["Why would Casabianca not leave the ship?"],"answers":["His father had told him to stay at his post, and he did not know his father was dead"],"notes":"This is a sad story of war (the Battle of the Nile, 1798). Read ahead if you have a sensitive child."},{"id":"fifty-famous-stories-7-4","title":"Lesson 32: Antonio Canova","steps":["Read “Antonio Canova” aloud together","Narrate how Antonio saved the Count''s dinner","Draw the butter lion on the Count''s table"],"links":[{"label":"Read “Antonio Canova”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#ANTONIO_CANOVA"}],"pages":"pp. 156–161","questions":["What did Antonio carve his lion from?"],"answers":["A big lump of butter"]},{"id":"fifty-famous-stories-7-5","title":"Lesson 33: Picciola","steps":["Read “Picciola” aloud together","Narrate how Charney cared for his little plant","Draw Picciola growing between the paving stones"],"links":[{"label":"Read “Picciola”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#PICCIOLA"}],"pages":"pp. 162–166","questions":["Who helped Charney save the plant and get set free?"],"answers":["The emperor''s wife (Napoleon''s empress), after reading his handkerchief"]},{"id":"fifty-famous-stories-7-6","title":"Lesson 34: Mignon","steps":["Read “Mignon” aloud together","Narrate how Mignon came to live with Wilhelm and how she tried to please him","Draw Mignon dancing blindfolded among the eggs"],"links":[{"label":"Read “Mignon”","url":"https://www.gutenberg.org/cache/epub/18442/pg18442-images.html#MIGNON"}],"pages":"pp. 167–172","questions":["What did Mignon dance among without touching any?"],"answers":["Eggs laid out on a carpet"],"notes":"From Goethe''s novel. Mignon tries to scrub the brown tint off her skin, thinking it is dye; you may want to talk about that. The story ends without a real ending."}]}],"version":1,"license":{"kind":"public_domain"},"attribution":"Lesson plan by Freerange Library for “Fifty Famous Stories Retold” by James Baldwin (1896), in the public domain. Free full text: https://www.gutenberg.org/ebooks/18442"}'::jsonb)
  on conflict (listing_id, version) do update set content = excluded.content;
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-home-geography', 'Freerange Library', 'publisher', true, 'Home Geography for Primary Grades', array['geography', 'science']::text[], 1, 3, array['charlotte_mason', 'nature_forest', 'traditional']::text[], 'online', 0, 'A gentle classic primer that teaches geography by starting at your own front door: finding north by the sun and stars, measuring and mapping your room, and spotting hills, streams, and ponds nearby. Each sitting is one or two short lessons with a hands-on or outdoor activity, a poem now and then, and a few questions to talk over. Great for siblings together, and the full text is free online.', array['31 sittings covering all 45 lessons, in 5 units', 'Link to the free full text for every lesson', 'Hands-on activities from the book: shadow watching, room plans, sand-table land forms, water experiments', 'Questions with answers for each sitting', 'Covers direction, maps, land and water forms, weather, plants, animals, minerals, and how people work']::text[], 31, 3, 20, 'high', true, '{}'::text[], '🧭', '#E3A33B', false, '2026-11-11T12:00:00.000Z', 'pk-lib-home-geography', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “Home Geography for Primary Grades” by C. C. Long (1894), in the public domain. Free full text: https://www.gutenberg.org/ebooks/12228', '[{"title":"Unit 1: Direction, Distance, and Plans (Lessons I–X)","lessons":["Lessons I–II: Position; How the Sun Shows Direction","Lessons III–IV: How the Stars Show Direction; How the Compass Shows Direction","Lessons V–VI: Questions on Direction; What the Winds Bring (poem)","Lesson VII: How to Tell Distance","Lesson VIII: Pictures and Plans","Lessons IX–X: Written Exercise; God Made Them All (poem)"]},{"title":"Unit 2: Land Forms and Weather (Lessons XI–XVII)","lessons":["Lesson XI: Plains","Lesson XII: Hills, Mountains, Valleys","Lessons XIII–XIV: Rain, Wind, and Snow; How Water Is Changed to Vapor","Lesson XV: How Vapor Is Changed to Water","Lessons XVI–XVII: Dew, Clouds, and Rain; The Fairy Artist (poem)"]},{"title":"Unit 3: Rivers, Maps, and Water Forms (Lessons XVIII–XXVIII)","lessons":["Lesson XVIII: How Rivers Are Made","Lessons XIX–XX: More About Rivers; The Brook (poem)","Lesson XXI: Work of Flowing Rivers","Lessons XXII–XXIII: Waterdrop''s Story; The River (poem)","Lesson XXIV: A Map","Lesson XXV: Forms of Land and Water","Lesson XXVI: More About Forms of Land and Water","Lessons XXVII–XXVIII: A Trip to the Highlands; Spring (poem)"]},{"title":"Unit 4: Plants (Lessons XXIX–XXXVI)","lessons":["Lessons XXIX–XXX: Useful Vegetables; Useful Grains","Lesson XXXI: Fruits","Lesson XXXII: Useful Plants","Lesson XXXIII: Forest Trees","Lesson XXXIV: Flowers","Lessons XXXV–XXXVI: What Is Necessary to Make Plants Grow; Summer Rain (poem)"]},{"title":"Unit 5: Animals, Minerals, and People (Lessons XXXVII–XLV)","lessons":["Lessons XXXVII–XXXVIII: The Parts of Animals; The Covering of Animals","Lessons XXXIX–XL: Uses of Animals; The Signs of the Seasons (poem)","Lesson XLI: Things Found in the Earth","Lesson XLII: More About Things Found in the Earth","Lesson XLIII: How People Live, and What They Are Doing","Lessons XLIV–XLV: More About What People Are Doing; A Review Lesson"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-home-geography', 1, '{"units":[{"id":"home-geography-u1","title":"Unit 1: Direction, Distance, and Plans (Lessons I–X)","lessons":[{"id":"home-geography-1-1","title":"Lessons I–II: Position; How the Sun Shows Direction","steps":["Read Lessons I and II together and do the right/left/front/back game at the table, then turn around and play it again","Go outside in the morning and point to where the sun rose; name that direction east","Stand with your right arm toward east and left arm toward west, and name north (in front) and south (behind)","Copywork: copy the sentence about the sun rising in the east and setting in the west"],"links":[{"label":"Read Lesson I","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less1"},{"label":"Read Lesson II","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less2"}],"questions":["In which direction does the sun seem to rise?","In which direction does it seem to set?","If your right hand points east and your left hand points west, which way are you facing?"],"answers":["East","West","North"],"notes":"Right and left change when you turn around; north, south, east, and west don''t. That is the big idea of these first lessons."},{"id":"home-geography-1-2","title":"Lessons III–IV: How the Stars Show Direction; How the Compass Shows Direction","steps":["Read Lessons III and IV together","On a clear night, go outside and find the Big Dipper; follow its two pointer stars to the North Star","Look at a real compass (or a phone compass) and watch the needle settle; mark N, S, E, W on paper around it","Draw the eight points of the compass: N, NE, E, SE, S, SW, W, NW"],"links":[{"label":"Read Lesson III","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less3"},{"label":"Read Lesson IV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less4"}],"questions":["Which star always shows the north?","What is the name of the group of stars that contains the Dipper?","Which direction is halfway between north and east?"],"answers":["The North Star","The Great Bear","Northeast"]},{"id":"home-geography-1-3","title":"Lessons V–VI: Questions on Direction; What the Winds Bring (poem)","steps":["Read Lesson V and talk through the questions together","Mark where your shadow falls at three times of day (morning, noon, and late afternoon); notice when it is shortest","Look for a flag, smoke, or weather vane and decide which way the wind is blowing","Read the poem \"What the Winds Bring\" (Lesson VI) aloud and talk about what each wind brings"],"links":[{"label":"Read Lesson V","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less5"},{"label":"Read Lesson VI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less6"}],"questions":["When during the day is your shadow shortest?","In what direction will birds fly when winter comes?","In the poem, what does the north wind bring?"],"answers":["At noon, when the sun is highest","South","Snowflakes (and frost pictures on the windows)"]},{"id":"home-geography-1-4","title":"Lesson VII: How to Tell Distance","steps":["Read Lesson VII together","Measure with a ruler: a book, a table, and a doorway; then use a yardstick or tape measure on a room","Guess a distance by eye (like across the yard), then measure it to check","Talk about a place about a mile from home and how long it would take to walk there"],"links":[{"label":"Read Lesson VII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less7"}],"questions":["How many inches are in a foot?","How many feet are in a yard?","Which measure is used for long distances, like between towns?"],"answers":["12","3","The mile"],"notes":"The book suggests guessing first, then measuring, and repeating until the guesses get close."},{"id":"home-geography-1-5","title":"Lesson VIII: Pictures and Plans","steps":["Read Lesson VIII together and compare the picture and the plan of the schoolroom","Trace around blocks on paper to make a plan of a block ''house'', like the boy in the lesson","Begin a plan of one room at home: measure two walls and choose a scale, such as 1 inch for 1 foot"],"links":[{"label":"Read Lesson VIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less8"}],"questions":["What is the difference between a picture and a plan?","In the lesson''s plan, what does one inch stand for?"],"answers":["A picture shows things as we see them; a plan shows where things are and their direction from each other","One foot in the room"]},{"id":"home-geography-1-6","title":"Lessons IX–X: Written Exercise; God Made Them All (poem)","steps":["Read Lesson IX and answer the questions about your own home or school in full sentences","Draw a plan of your room at home with the bed, table, chairs, and door; mark N, S, E, and W","Draw a plan of your house and yard","Read the poem \"God Made Them All\" (Lesson X) aloud"],"links":[{"label":"Read Lesson IX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less9"},{"label":"Read Lesson X","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less10"}],"questions":["What do we call a drawing that shows where things are in a room?","Is the top of a plan always north?"],"answers":["A plan","No; you have to mark which way is north"]}]},{"id":"home-geography-u2","title":"Unit 2: Land Forms and Weather (Lessons XI–XVII)","lessons":[{"id":"home-geography-2-1","title":"Lesson XI: Plains","steps":["Read Lesson XI together","Find the flattest piece of land near you and imagine it stretching for miles; that is a plain","Find a picture of a palm tree and draw it","Talk about why travelers cross the desert on camels instead of horses"],"links":[{"label":"Read Lesson XI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less11"}],"questions":["What is a broad, nearly level stretch of land called?","What is a grassy, flowery plain called?","What is an oasis?"],"answers":["A plain","A prairie","A fertile spot with water in the middle of a desert"]},{"id":"home-geography-2-2","title":"Lesson XII: Hills, Mountains, Valleys","steps":["Read Lesson XII together","Walk up a hill (or the biggest slope nearby) and name its base, slope, and summit; look at the view from the top","Model hills, mountains, and a valley in sand, clay, or play dough","Draw a hill you have seen, with a little of the land around it"],"links":[{"label":"Read Lesson XII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less12"}],"questions":["What do we call the bottom, the sides, and the top of a hill?","What is the land between hills or mountains called?","Is it warmer or colder at the top of a high mountain?"],"answers":["The base (foot), the slopes (sides), and the summit (top)","A valley","Colder"]},{"id":"home-geography-2-3","title":"Lessons XIII–XIV: Rain, Wind, and Snow; How Water Is Changed to Vapor","steps":["Read Lessons XIII and XIV together","Wipe a damp sponge across a slate or chalkboard and watch the water disappear","Set a plate of water in the sun and check it later; talk about where the water went","With a grown-up, watch a kettle boil and see the water turn to vapor"],"links":[{"label":"Read Lesson XIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less13"},{"label":"Read Lesson XIV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less14"}],"questions":["What does heat change water into?","Can warm air or cold air hold more vapor?","Why does vapor rise into the air?"],"answers":["Vapor","Warm air","It is lighter than air"],"notes":"The book says to give the weather lessons when that weather happens; save a rainy or snowy day for these if you can."},{"id":"home-geography-2-4","title":"Lesson XV: How Vapor Is Changed to Water","steps":["Read Lesson XV together","With a grown-up, hold a cold plate over steaming water and watch drops form and roll down","Fill a glass or pitcher with ice water and watch mist and drops gather on the outside","Breathe on a cold window and see your breath turn to water"],"links":[{"label":"Read Lesson XV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less15"}],"questions":["What turns vapor back into water?","Where does the water on the outside of an ice-water pitcher come from?","Does the water come through the pitcher from inside?"],"answers":["Cold","From vapor in the air that is cooled by the cold pitcher","No"]},{"id":"home-geography-2-5","title":"Lessons XVI–XVII: Dew, Clouds, and Rain; The Fairy Artist (poem)","steps":["Read Lesson XVI together","Go outside early in the morning to look for dew on the grass (or frost in cold weather)","Watch the clouds for a few minutes and notice how they change shape","Read the poem \"The Fairy Artist\" (Lesson XVII) and draw a frosty window picture"],"links":[{"label":"Read Lesson XVI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less16"},{"label":"Read Lesson XVII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less17"}],"questions":["What is dew?","What is frozen dew called?","What are clouds made of?"],"answers":["Water from the air that cools on cold grass and leaves and turns into drops","Frost","Tiny drops of water or crystals of ice"]}]},{"id":"home-geography-u3","title":"Unit 3: Rivers, Maps, and Water Forms (Lessons XVIII–XXVIII)","lessons":[{"id":"home-geography-3-1","title":"Lesson XVIII: How Rivers Are Made","steps":["Read Lesson XVIII together","Visit a brook, creek, or river if you can; notice which way the water flows and what grows on its banks","Draw a spring with a little brook flowing from it, and the grasses around it","Copywork: copy two of the river words (spring, source, mouth, tributary) with their meanings"],"links":[{"label":"Read Lesson XVIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less18"}],"questions":["What is the beginning of a river called?","Where a river flows into another body of water is called its what?","What is a small stream flowing into a larger one called?"],"answers":["Its source","Its mouth","A tributary"]},{"id":"home-geography-3-2","title":"Lessons XIX–XX: More About Rivers; The Brook (poem)","steps":["Read Lesson XIX together","Pour water slowly onto the ridge of a tent-shaped piece of paper or a sand ridge and watch it run down both sides (a water-parting)","Read the poem \"The Brook\" (Lesson XX) aloud and trace the brook''s journey with your finger in the air","Talk about why a river runs fast in some places and slow in others"],"links":[{"label":"Read Lesson XIX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less19"},{"label":"Read Lesson XX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less20"}],"questions":["What do we call hills that divide the water to flow down two sides?","What is it called when a river falls over a high ledge of rock?","Why does a river wind about on level land?"],"answers":["A water-parting or watershed","A waterfall or cataract","The water moves slowly there and is easily turned from its course"]},{"id":"home-geography-3-3","title":"Lesson XXI: Work of Flowing Rivers","steps":["Read Lesson XXI together","Put mud and water in a jar, shake it, and let it stand; notice which settles first, the coarse or the fine","After a rain, look for little streams carrying soil down a slope","Collect a few smooth stones from a stream or beach and talk about how they got round"],"links":[{"label":"Read Lesson XXI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less21"}],"questions":["What happens to muddy water when it stands still?","What makes stream stones smooth and round?","Where do rich river meadows come from?"],"answers":["The mud settles to the bottom and the water clears","Rubbing against each other as the water rolls them along","Soil that rivers wash down from the hills and leave when they flood"]},{"id":"home-geography-3-4","title":"Lessons XXII–XXIII: Waterdrop''s Story; The River (poem)","steps":["Read \"Waterdrop''s Story\" (Lesson XXII) aloud","Narration: your child tells the waterdrop''s whole journey back, from sea to cloud to rain to river to sea","Draw the water cycle as a circle of pictures","Read the poem \"The River\" (Lesson XXIII) and talk about its questions"],"links":[{"label":"Read Lesson XXII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less22"},{"label":"Read Lesson XXIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less23"}],"questions":["Where did the waterdrop''s journey begin and end?","What made the drops come together and fall as rain?","What machine did the water turn on its way?"],"answers":["In the sea","The cold wind by the mountain chilled them and made them heavy","A mill-wheel"]},{"id":"home-geography-3-5","title":"Lesson XXIV: A Map","steps":["Read Lesson XXIV together","Draw a simple map with mountains (short facing lines) and a river (a line that gets thicker toward its mouth)","Look at a real map of your area and find a river, hills, and your town"],"links":[{"label":"Read Lesson XXIV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less24"}],"questions":["What is the difference between a plan and a map?","Why is the river line drawn thicker toward its mouth?"],"answers":["A plan shows a room, house, or yard; a map shows land and water","Because the river gets wider as it flows toward the sea"],"notes":"The book''s warning is worth repeating: the lines on a map stand for real mountains and rivers, so picture the real thing."},{"id":"home-geography-3-6","title":"Lesson XXV: Forms of Land and Water","steps":["Read Lesson XXV together","Make a lake with an inlet, an outlet, and an island in sand, a sandbox, or a baking pan","If there is a pond or lake nearby, walk along part of its shore","Draw a map of a river and lake on paper"],"links":[{"label":"Read Lesson XXV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less25"}],"questions":["What is a lake?","What is the river that lets water into a lake called?","What is an island?"],"answers":["Water surrounded by land (a hollow in the land filled with water)","The inlet","A piece of land with water all around it"]},{"id":"home-geography-3-7","title":"Lesson XXVI: More About Forms of Land and Water","steps":["Read Lesson XXVI together","In sand or after a rain, make a peninsula, an isthmus, a bay, and a strait","Look for pictures of bays and peninsulas in books or magazines","Copywork: copy the meaning of peninsula and strait"],"links":[{"label":"Read Lesson XXVI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less26"}],"questions":["What does the word peninsula mean?","What connects a peninsula to the mainland?","What is a strait?"],"answers":["Almost an island","An isthmus","A narrow passage of water joining two larger bodies of water"]},{"id":"home-geography-3-8","title":"Lessons XXVII–XXVIII: A Trip to the Highlands; Spring (poem)","steps":["Read \"A Trip to the Highlands\" (Lesson XXVII) aloud","Take a walk to the highest place you can reach nearby and look for land and water forms from the top","Narration: your child retells the trip and names every land or water form the children saw","Read the poem \"Spring\" (Lesson XXVIII) aloud"],"links":[{"label":"Read Lesson XXVII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less27"},{"label":"Read Lesson XXVIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less28"}],"questions":["Did it get warmer or cooler as the children climbed?","What did the father say the land reaching out into the lake was?","How did the city look from the top of the hill?"],"answers":["Cooler","A peninsula","Small, with little straight streets and tiny house-tops"]}]},{"id":"home-geography-u4","title":"Unit 4: Plants (Lessons XXIX–XXXVI)","lessons":[{"id":"home-geography-4-1","title":"Lessons XXIX–XXX: Useful Vegetables; Useful Grains","steps":["Read Lessons XXIX and XXX together","Sort vegetables from your kitchen: which do we eat the roots, leaves, stems, or seeds of?","Plant a few seeds (beans or corn) in a cup of soil and start watching them grow","Draw one of the grains, such as wheat or an ear of corn"],"links":[{"label":"Read Lesson XXIX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less29"},{"label":"Read Lesson XXX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less30"}],"questions":["Name a vegetable whose root we eat.","Which grain makes the choicest flour?","Why is it called Indian corn?"],"answers":["Any of: beet, turnip, radish, carrot","Wheat","Because American Indians first raised it"],"notes":"The book suggests planting seeds and watching them sprout; keep the cup going for the plant lessons that follow."},{"id":"home-geography-4-2","title":"Lesson XXXI: Fruits","steps":["Read Lesson XXXI together","Name fruits that grow near you and sort them: trees, bushes, or vines","Visit an orchard, garden, or market and look at where fruits come from","Talk about why people in hot and cold countries eat different foods"],"links":[{"label":"Read Lesson XXXI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less31"}],"questions":["What is a place where many fruit trees grow called?","Where does the orange grow in our country?","Name a fruit that grows on a vine."],"answers":["An orchard","Only in the warmer parts","Grapes (or melons)"]},{"id":"home-geography-4-3","title":"Lesson XXXII: Useful Plants","steps":["Read Lesson XXXII together","Look at the labels on your clothes and find which are cotton or linen","Find out where your sugar comes from; taste a little maple syrup if you have some","Write or tell what you learned about cotton and linen"],"links":[{"label":"Read Lesson XXXII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less32"}],"questions":["What plant does linen come from?","What machine separates cotton from its seeds?","Name two plants that sugar is made from."],"answers":["Flax","The cotton gin","Sugar cane and the sugar maple"]},{"id":"home-geography-4-4","title":"Lesson XXXIII: Forest Trees","steps":["Read Lesson XXXIII together","Take a walk and learn the names of three trees near you; collect a leaf from each","Look at the wooden furniture in your home and guess what kinds of wood it is made of","Draw and color one of the trees you found"],"links":[{"label":"Read Lesson XXXIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less33"}],"questions":["What do we call trees planted along streets to keep off the sun?","How tall are some of the great trees of California?","What is lumber used for?"],"answers":["Shade trees","Nearly 400 feet high","Building houses, ships, and furniture"]},{"id":"home-geography-4-5","title":"Lesson XXXIV: Flowers","steps":["Read Lesson XXXIV together","Go on a flower walk and name as many flowers as you can; notice where each one grows","Find the parts of a plant: root, stem, leaves, bud, and flower","Begin learning the poem \"Spring and the Flowers\" by heart"],"links":[{"label":"Read Lesson XXXIV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less34"}],"questions":["Name the parts of a plant.","Do all flowers grow in the same kind of place?"],"answers":["Root, stem, leaves, bud, and flower","No; some need wet places and some need dry ones"]},{"id":"home-geography-4-6","title":"Lessons XXXV–XXXVI: What Is Necessary to Make Plants Grow; Summer Rain (poem)","steps":["Read Lesson XXXV together","Check on your seed cup: talk about what it needs to keep growing","Try an experiment: keep one seedling in the dark or without water and compare it with one that has light and water","Read the poem \"Summer Rain\" (Lesson XXXVI) aloud"],"links":[{"label":"Read Lesson XXXV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less35"},{"label":"Read Lesson XXXVI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less36"}],"questions":["What two things does the lesson say plants need to grow?","Why don''t plants grow in deserts?","Why don''t plants grow in winter?"],"answers":["Heat (warmth) and rain (moisture)","There is not enough rain","It is too cold"]}]},{"id":"home-geography-u5","title":"Unit 5: Animals, Minerals, and People (Lessons XXXVII–XLV)","lessons":[{"id":"home-geography-5-1","title":"Lessons XXXVII–XXXVIII: The Parts of Animals; The Covering of Animals","steps":["Read Lessons XXXVII and XXXVIII together","Watch a cat, dog, chicken, or duck and notice its feet, claws, beak, or bill and what it uses them for","Draw a duck''s webbed foot next to a hen''s foot","Sort animals by their covering: fur, hair, feathers, wool, scales, or shell"],"links":[{"label":"Read Lesson XXXVII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less37"},{"label":"Read Lesson XXXVIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less38"}],"questions":["What do we call animals that live near people and are tame?","What keeps a duck''s feathers from getting wet?","Why does a duck have webbed feet?"],"answers":["Domestic animals","An oily coating","For swimming"],"notes":"The big idea of both lessons: each animal has the parts and the covering that suit the life it leads."},{"id":"home-geography-5-2","title":"Lessons XXXIX–XL: Uses of Animals; The Signs of the Seasons (poem)","steps":["Read Lesson XXXIX together","Find things at home that come from animals: wool, leather, milk, eggs, silk","Make a list of animals that are useful for food, for work, and for clothing","Read the poem \"The Signs of the Seasons\" (Lesson XL) and look outside for signs of the season you are in now"],"links":[{"label":"Read Lesson XXXIX","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less39"},{"label":"Read Lesson XL","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less40"}],"questions":["Where does wool come from?","How is silk made?","In the poem, what are two signs that spring is here?"],"answers":["Sheep","Silkworms spin cocoons of silk thread","The bluebird comes and builds its nest, and violets peep up"]},{"id":"home-geography-5-3","title":"Lesson XLI: Things Found in the Earth","steps":["Read Lesson XLI together","Hunt around the house for things made of iron or steel, copper, tin, brass, and gold or silver","Look at a pencil and talk about what the ''lead'' is really made of","Start a collection of rocks and minerals from your area, as the book suggests"],"links":[{"label":"Read Lesson XLI","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less41"}],"questions":["What is the most useful of all metals, according to the lesson?","What is the hole dug in the earth to get minerals called?","What is a ''lead'' pencil really made of?"],"answers":["Iron","A mine","Graphite"]},{"id":"home-geography-5-4","title":"Lesson XLII: More About Things Found in the Earth","steps":["Read Lesson XLII together","Walk around your neighborhood and look for granite, marble, slate, brick, and sandstone in buildings, steps, and curbs","Rub a piece of sandstone or chalk to see how it crumbles; compare it with a hard stone","Add any building stones you find to your rock collection and label them"],"links":[{"label":"Read Lesson XLII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less42"}],"questions":["What is the place where building stone is dug called?","What are bricks made from?","What is glass made from?"],"answers":["A quarry","Clay","Sand"]},{"id":"home-geography-5-5","title":"Lesson XLIII: How People Live, and What They Are Doing","steps":["Read Lesson XLIII together","Talk about the kinds of homes people live in: tents, wigwams, huts, snow houses, bamboo houses","Trace one thing you ate today back to the plant or animal it came from","Name the work of farmers, stock-raisers, miners, lumbermen, and fishermen"],"links":[{"label":"Read Lesson XLIII","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less43"}],"questions":["What do we call the work of raising crops?","What is the business of raising cows and sheep called?","When do lumbermen cut trees, and how do the logs get to the mill?"],"answers":["Agriculture or farming","Stock-raising","In winter; they float down the streams in spring when the snow melts"]},{"id":"home-geography-5-6","title":"Lessons XLIV–XLV: More About What People Are Doing; A Review Lesson","steps":["Read Lessons XLIV and XLV together","Make a list of all the jobs (occupations) you can think of, and the jobs people do near you","Pick one thing in your home and talk about where it was made and how it got to you","Review: walk through your town or neighborhood and name the stores, workshops, roads, or waterways you see"],"links":[{"label":"Read Lesson XLIV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less44"},{"label":"Read Lesson XLV","url":"https://www.gutenberg.org/cache/epub/12228/pg12228-images.html#less45"}],"questions":["What do we call the buying, selling, and exchanging of goods?","Where are most things made in a city?","Why do people in different places do different kinds of work?"],"answers":["Trade or commerce","In mills and factories","It depends on the place they live: the land, mountains, sea, or city around them"]}]}],"version":1,"license":{"kind":"public_domain"},"attribution":"Lesson plan by Freerange Library for “Home Geography for Primary Grades” by C. C. Long (1894), in the public domain. Free full text: https://www.gutenberg.org/ebooks/12228"}'::jsonb)
  on conflict (listing_id, version) do update set content = excluded.content;
insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-im-grade-6-math', 'Freerange Library', 'publisher', true, 'Grade 6 Math: Open Problem-Based Course', array['math']::text[], 6, 6, array['traditional']::text[], 'online', 0, 'A full, problem-based sixth-grade math course from an open textbook: area and surface area, ratios, rates and percentages, fraction division, decimals, equations and exponents, negative numbers and the coordinate plane, and statistics. Each day opens with a short warm-up, works through the lesson''s activities on the free student page, then finishes with practice problems and the lesson summary.', array['145 lessons in 9 units', 'Link to the free student page and practice problems for every lesson', 'Warm-up, activities, practice, and summary steps each day', 'Extra questions with answers for every lesson']::text[], 145, 4, 45, 'medium', false, '{}'::text[], '📐', '#4C7FD9', false, '2026-11-11T12:00:00.000Z', 'pk-lib-im-grade-6-math', 1, '{"kind":"cc_by","version":"4.0"}'::jsonb, 'Adapted from “Open Up Resources 6–8 Math, Grade 6” by Illustrative Mathematics, published by Open Up Resources and licensed under CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Download for free at openupresources.org. Organized into lessons, with added practice questions, by Freerange Library; not endorsed by Open Up Resources or Illustrative Mathematics.', '[{"title":"Unit 1: Area and Surface Area","lessons":["Lesson 1: Tiling the Plane","Lesson 2: Finding Area by Decomposing and Rearranging","Lesson 3: Reasoning to Find Area","Lesson 4: Parallelograms","Lesson 5: Bases and Heights of Parallelograms","Lesson 6: Area of Parallelograms","Lesson 7: From Parallelograms to Triangles","Lesson 8: Area of Triangles","Lesson 9: Formula for the Area of a Triangle","Lesson 10: Bases and Heights of Triangles","Lesson 11: Polygons","Lesson 12: What is Surface Area?","Lesson 13: Polyhedra","Lesson 14: Nets and Surface Area","Lesson 15: More Nets, More Surface Area","Lesson 16: Distinguishing Between Surface Area and Volume","Lesson 17: Squares and Cubes","Lesson 18: Surface Area of a Cube","Lesson 19: Designing a Tent"]},{"title":"Unit 2: Introducing Ratios","lessons":["Lesson 1: Introducing Ratios and Ratio Language","Lesson 2: Representing Ratios with Diagrams","Lesson 3: Recipes","Lesson 4: Color Mixtures","Lesson 5: Defining Equivalent Ratios","Lesson 6: Introducing Double Number Line Diagrams","Lesson 7: Creating Double Number Line Diagrams","Lesson 8: How Much for One?","Lesson 9: Constant Speed","Lesson 10: Comparing Situations by Examining Ratios","Lesson 11: Representing Ratios with Tables","Lesson 12: Navigating a Table of Equivalent Ratios","Lesson 13: Tables and Double Number Line Diagrams","Lesson 14: Solving Equivalent Ratio Problems","Lesson 15: Part-Part-Whole Ratios","Lesson 16: Solving More Ratio Problems","Lesson 17: A Fermi Problem"]},{"title":"Unit 3: Unit Rates and Percentages","lessons":["Lesson 1: The Burj Khalifa","Lesson 2: Anchoring Units of Measurement","Lesson 3: Measuring with Different-Sized Units","Lesson 4: Converting Units","Lesson 5: Comparing Speeds and Prices","Lesson 6: Interpreting Rates","Lesson 7: Equivalent Ratios Have the Same Unit Rates","Lesson 8: More about Constant Speed","Lesson 9: Solving Rate Problems","Lesson 10: What Are Percentages?","Lesson 11: Percentages and Double Number Lines","Lesson 12: Percentages and Tape Diagrams","Lesson 13: Benchmark Percentages","Lesson 14: Solving Percentage Problems","Lesson 15: Finding This Percent of That","Lesson 16: Finding the Percentage","Lesson 17: Painting a Room"]},{"title":"Unit 4: Dividing Fractions","lessons":["Lesson 1: Size of Divisor and Size of Quotient","Lesson 2: Meanings of Division","Lesson 3: Interpreting Division Situations","Lesson 4: How Many Groups? (Part 1)","Lesson 5: How Many Groups? (Part 2)","Lesson 6: Using Diagrams to Find the Number of Groups","Lesson 7: What Fraction of a Group?","Lesson 8: How Much in Each Group? (Part 1)","Lesson 9: How Much in Each Group? (Part 2)","Lesson 10: Dividing by Unit and Non-Unit Fractions","Lesson 11: Using an Algorithm to Divide Fractions","Lesson 12: Fractional Lengths","Lesson 13: Rectangles with Fractional Side Lengths","Lesson 14: Fractional Lengths in Triangles and Prisms","Lesson 15: Volume of Prisms","Lesson 16: Solving Problems Involving Fractions","Lesson 17: Fitting Boxes into Boxes"]},{"title":"Unit 5: Arithmetic in Base Ten","lessons":["Lesson 1: Using Decimals in a Shopping Context","Lesson 2: Using Diagrams to Represent Addition and Subtraction","Lesson 3: Adding and Subtracting Decimals with Few Non-Zero Digits","Lesson 4: Adding and Subtracting Decimals with Many Non-Zero Digits","Lesson 5: Decimal Points in Products","Lesson 6: Methods for Multiplying Decimals","Lesson 7: Using Diagrams to Represent Multiplication","Lesson 8: Calculating Products of Decimals","Lesson 9: Using the Partial Quotients Method","Lesson 10: Using Long Division","Lesson 11: Dividing Numbers that Result in Decimals","Lesson 12: Dividing Decimals by Whole Numbers","Lesson 13: Dividing Decimals by Decimals","Lesson 14: Using Operations on Decimals to Solve Problems","Lesson 15: Making and Measuring Boxes"]},{"title":"Unit 6: Expressions and Equations","lessons":["Lesson 1: Tape Diagrams and Equations","Lesson 2: Truth and Equations","Lesson 3: Staying in Balance","Lesson 4: Practice Solving Equations and Representing Situations with Equations","Lesson 5: A New Way to Interpret a over b","Lesson 6: Write Expressions Where Letters Stand for Numbers","Lesson 7: Revisit Percentages","Lesson 8: Equal and Equivalent","Lesson 9: The Distributive Property, Part 1","Lesson 10: The Distributive Property, Part 2","Lesson 11: The Distributive Property, Part 3","Lesson 12: Meaning of Exponents","Lesson 13: Expressions with Exponents","Lesson 14: Evaluating Expressions with Exponents","Lesson 15: Equivalent Exponential Expressions","Lesson 16: Two Related Quantities, Part 1","Lesson 17: Two Related Quantities, Part 2","Lesson 18: More Relationships"]},{"title":"Unit 7: Rational Numbers","lessons":["Lesson 1: Positive and Negative Numbers","Lesson 2: Points on the Number Line","Lesson 3: Comparing Positive and Negative Numbers","Lesson 4: Ordering Rational Numbers","Lesson 5: Using Negative Numbers to Make Sense of Contexts","Lesson 6: Absolute Value of Numbers","Lesson 7: Comparing Numbers and Distance from Zero","Lesson 8: Writing and Graphing Inequalities","Lesson 9: Solutions of Inequalities","Lesson 10: Interpreting Inequalities","Lesson 11: Points on the Coordinate Plane","Lesson 12: Constructing the Coordinate Plane","Lesson 13: Interpreting Points on a Coordinate Plane","Lesson 14: Distances on a Coordinate Plane","Lesson 15: Shapes on the Coordinate Plane","Lesson 16: Common Factors","Lesson 17: Common Multiples","Lesson 18: Using Common Multiples and Common Factors"]},{"title":"Unit 8: Data Sets and Distributions","lessons":["Lesson 1: Got Data?","Lesson 2: Statistical Questions","Lesson 3: Representing Data Graphically","Lesson 4: Dot Plots","Lesson 5: Using Dot Plots to Answer Statistical Questions","Lesson 6: Histograms","Lesson 7: Using Histograms to Answer Statistical Questions","Lesson 8: Describing Distributions on Histograms","Lesson 9: Interpreting the Mean as Fair Share","Lesson 10: Finding and Interpreting the Mean as the Balance Point","Lesson 11: Deviation from the Mean","Lesson 12: Using Mean and MAD to Make Comparisons","Lesson 13: The Median of a Data Set","Lesson 14: Comparing Mean and Median","Lesson 15: Quartiles and Interquartile Range","Lesson 16: Box Plots","Lesson 17: Using Box Plots","Lesson 18: Using Data to Solve Problems"]},{"title":"Unit 9: Putting it All Together","lessons":["Lesson 1: Fermi Problems","Lesson 2: If Our Class Were the World","Lesson 3: Rectangle Madness","Lesson 4: How Do We Choose?","Lesson 5: More than Two Choices","Lesson 6: Picking Representatives"]}]'::jsonb)
  on conflict (id) do update set seller_name = excluded.seller_name, seller_kind = excluded.seller_kind, seller_verified = excluded.seller_verified, title = excluded.title, subjects = excluded.subjects, grade_min = excluded.grade_min, grade_max = excluded.grade_max, philosophies = excluded.philosophies, format = excluded.format, price = excluded.price, description = excluded.description, includes = excluded.includes, lessons = excluded.lessons, lessons_per_week = excluded.lessons_per_week, minutes_per_lesson = excluded.minutes_per_lesson, parent_involvement = excluded.parent_involvement, family_style = excluded.family_style, lesson_steps = excluded.lesson_steps, cover = excluded.cover, color = excluded.color, esa_eligible = excluded.esa_eligible, package_id = excluded.package_id, package_version = excluded.package_version, license = excluded.license, attribution = excluded.attribution, outline = excluded.outline;
insert into public.package_releases (listing_id, version, content) values ('l-lib-im-grade-6-math', 1, '{"units":[{"id":"im-grade-6-math-u1","title":"Unit 1: Area and Surface Area","lessons":[{"id":"im-grade-6-math-1-1","title":"Lesson 1: Tiling the Plane","steps":["Warm-up: Which One Doesn’t Belong: Tilings","Activities: More Red, Green, or Blue?","Practice problems for Lesson 1","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.1 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/1.html"},{"label":"Lesson 1 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-1"}],"questions":["A floor is covered by square tiles with no gaps or overlaps. What is this kind of covering called?","If 6 small triangles exactly cover 1 hexagon, how many triangles cover 3 hexagons?"],"answers":["Tiling (the plane)","18"]},{"id":"im-grade-6-math-1-2","title":"Lesson 2: Finding Area by Decomposing and Rearranging","steps":["Warm-up: What is Area?","Activities: Composing Shapes; Tangram Triangles","Practice problems for Lesson 2","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.2 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/2.html"},{"label":"Lesson 2 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-2"}],"questions":["A rectangle is cut into 2 pieces and rearranged into a new shape. Did the area change?","Two identical triangles each have area 5 square units. What area do they cover together?"],"answers":["No, the area stays the same","10 square units"]},{"id":"im-grade-6-math-1-3","title":"Lesson 3: Reasoning to Find Area","steps":["Warm-up: Comparing Regions","Activities: On the Grid; Off the Grid","Practice problems for Lesson 3","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.3 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/3.html"},{"label":"Lesson 3 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-3"}],"questions":["An L-shape is made of a 4-by-3 rectangle and a 2-by-2 square. What is its area?","A 6-by-5 rectangle has a 2-by-2 square cut out of it. What area is left?"],"answers":["16 square units","26 square units"]},{"id":"im-grade-6-math-1-4","title":"Lesson 4: Parallelograms","steps":["Warm-up: Features of a Parallelogram","Activities: Area of a Parallelogram; Lots of Parallelograms","Practice problems for Lesson 4","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.4 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/4.html"},{"label":"Lesson 4 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-4"}],"questions":["How many pairs of parallel sides does a parallelogram have?","A parallelogram is cut and rearranged into a rectangle 7 units by 3 units. What is its area?"],"answers":["2","21 square units"]},{"id":"im-grade-6-math-1-5","title":"Lesson 5: Bases and Heights of Parallelograms","steps":["Warm-up: A Parallelogram and Its Rectangles","Activities: The Right Height?; Finding the Formula for Area of Parallelograms","Practice problems for Lesson 5","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.5 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/5.html"},{"label":"Lesson 5 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-5"}],"questions":["A parallelogram has base 9 cm and height 4 cm. What is its area?","Is the height of a parallelogram always one of its sides?"],"answers":["36 square cm","No; it is perpendicular to the base and may be inside or outside the shape"]},{"id":"im-grade-6-math-1-6","title":"Lesson 6: Area of Parallelograms","steps":["Warm-up: Missing Dots","Activities: More Areas of Parallelograms","Practice problems for Lesson 6","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.6 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/6.html"},{"label":"Lesson 6 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-6"}],"questions":["A parallelogram has area 40 square inches and base 8 inches. What is its height?","Find the area of a parallelogram with base 12 m and height 2.5 m."],"answers":["5 inches","30 square m"]},{"id":"im-grade-6-math-1-7","title":"Lesson 7: From Parallelograms to Triangles","steps":["Warm-up: Same Parallelograms, Different Bases","Activities: A Tale of Two Triangles (Part 1); A Tale of Two Triangles (Part 2)","Practice problems for Lesson 7","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.7 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/7.html"},{"label":"Lesson 7 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-7"}],"questions":["A parallelogram with area 24 square units is cut along a diagonal. What is the area of each triangle?","Can any two identical triangles always be joined to make a parallelogram?"],"answers":["12 square units","Yes"]},{"id":"im-grade-6-math-1-8","title":"Lesson 8: Area of Triangles","steps":["Warm-up: Composing Parallelograms","Activities: More Triangles; Decomposing a Parallelogram","Practice problems for Lesson 8","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.8 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/8.html"},{"label":"Lesson 8 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-8"}],"questions":["A triangle is half of a parallelogram with base 10 and height 6. What is the triangle''s area?","Two copies of a triangle make a rectangle 8 by 5. What is one triangle''s area?"],"answers":["30 square units","20 square units"]},{"id":"im-grade-6-math-1-9","title":"Lesson 9: Formula for the Area of a Triangle","steps":["Warm-up: Bases and Heights of a Triangle","Activities: Finding the Formula for Area of a Triangle; Applying the Formula for Area of Triangles","Practice problems for Lesson 9","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.9 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/9.html"},{"label":"Lesson 9 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-9"}],"questions":["Find the area of a triangle with base 14 cm and height 5 cm.","Write the formula for the area of a triangle."],"answers":["35 square cm","A = 1/2 x b x h"]},{"id":"im-grade-6-math-1-10","title":"Lesson 10: Bases and Heights of Triangles","steps":["Warm-up: An Area of 12","Activities: Hunting for Heights; Some Bases Are Better Than Others","Practice problems for Lesson 10","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.10 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/10.html"},{"label":"Lesson 10 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-10"}],"questions":["A triangle has area 12 square units and base 6. What is its height?","For a triangle, can the height fall outside the triangle?"],"answers":["4 units","Yes, for an obtuse triangle"]},{"id":"im-grade-6-math-1-11","title":"Lesson 11: Polygons","steps":["Warm-up: Which One Doesn’t Belong: Bases and Heights","Activities: What Are Polygons?; Quadrilateral Strategies; Pinwheel","Practice problems for Lesson 11","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.11 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/11.html"},{"label":"Lesson 11 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-11"}],"questions":["Is a circle a polygon? Why or why not?","A pentagon is split into a rectangle of area 20 and a triangle of area 6. What is the pentagon''s area?"],"answers":["No, it is not made of straight line segments","26 square units"]},{"id":"im-grade-6-math-1-12","title":"Lesson 12: What is Surface Area?","steps":["Warm-up: Covering the Cabinet (Part 1)","Activities: Covering the Cabinet (Part 2); Building with Snap Cubes","Practice problems for Lesson 12","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.12 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/12.html"},{"label":"Lesson 12 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-12"}],"questions":["How many unit squares cover all faces of a 1-by-1-by-1 cube?","A box is built from 4 cubes in a row. What is its surface area in square units?"],"answers":["6","18"]},{"id":"im-grade-6-math-1-13","title":"Lesson 13: Polyhedra","steps":["Warm-up: What are Polyhedra?","Activities: Prisms and Pyramids; Assembling Polyhedra","Practice problems for Lesson 13","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.13 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/13.html"},{"label":"Lesson 13 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-13"}],"questions":["How many faces does a triangular prism have?","How many faces does a square pyramid have?"],"answers":["5","5"]},{"id":"im-grade-6-math-1-14","title":"Lesson 14: Nets and Surface Area","steps":["Warm-up: Matching Nets","Activities: Using Nets to Find Surface Area","Practice problems for Lesson 14","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.14 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/14.html"},{"label":"Lesson 14 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-14"}],"questions":["A net has 2 identical rectangles 3 by 4, 2 that are 3 by 5, and 2 that are 4 by 5. What is the surface area?","A net of a prism has how many copies of the base polygon?"],"answers":["94 square units","2"]},{"id":"im-grade-6-math-1-15","title":"Lesson 15: More Nets, More Surface Area","steps":["Warm-up: Notice and Wonder: Wrapping Paper","Activities: Building Prisms and Pyramids; Comparing Boxes","Practice problems for Lesson 15","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.15 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/15.html"},{"label":"Lesson 15 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-15"}],"questions":["A square pyramid has a base 6 by 6 and four triangles each with base 6 and height 4. What is its surface area?","What does a net help you see all at once?"],"answers":["84 square units","All the faces of a polyhedron"]},{"id":"im-grade-6-math-1-16","title":"Lesson 16: Distinguishing Between Surface Area and Volume","steps":["Warm-up: Attributes and Their Measures","Activities: Building with 8 Cubes; Comparing Prisms Without Building Them","Practice problems for Lesson 16","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.16 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/16.html"},{"label":"Lesson 16 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-16"}],"questions":["Which unit fits volume: square cm or cubic cm?","Two shapes are each built from 8 cubes. Must they have the same surface area?"],"answers":["Cubic cm","No, only the same volume"]},{"id":"im-grade-6-math-1-17","title":"Lesson 17: Squares and Cubes","steps":["Warm-up: Perfect Squares","Activities: Building with 32 Cubes; Perfect Cubes; Introducing Exponents","Practice problems for Lesson 17","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.17 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/17.html"},{"label":"Lesson 17 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-17"}],"questions":["What is 7 squared?","What is 4 cubed?","Is 27 a perfect cube?"],"answers":["49","64","Yes, 3 x 3 x 3"]},{"id":"im-grade-6-math-1-18","title":"Lesson 18: Surface Area of a Cube","steps":["Warm-up: Exponent Review","Activities: The Net of a Cube; Every Cube in the Whole World","Practice problems for Lesson 18","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 1.18 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/18.html"},{"label":"Lesson 18 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/practice_problems.html#practice-problems-lesson-plan-18"}],"questions":["What is the surface area of a cube with edge 5 cm?","What is the volume of a cube with edge 3 inches?"],"answers":["150 square cm","27 cubic inches"]},{"id":"im-grade-6-math-1-19","title":"Lesson 19: Designing a Tent","steps":["Activities: Tent Design - Part 1; Tent Design - Part 2","Work through the project, showing your reasoning and assumptions","Share your findings with a parent or sibling"],"links":[{"label":"Lesson 1.19 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/1/19.html"}],"questions":["A tent uses 2 triangles (base 6 ft, height 4 ft) and 2 rectangles 5 ft by 7 ft. How much fabric is that?"],"answers":["94 square feet"],"notes":"Culminating or exploration lesson: no summary or practice set; let it run long if the project takes off."}]},{"id":"im-grade-6-math-u2","title":"Unit 2: Introducing Ratios","lessons":[{"id":"im-grade-6-math-2-1","title":"Lesson 1: Introducing Ratios and Ratio Language","steps":["Warm-up: What Kind and How Many?","Activities: The Teacher’s Collection; The Student’s Collection","Practice problems for Lesson 1","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.1 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/1.html"},{"label":"Lesson 1 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-1"}],"questions":["A bowl has 3 apples and 5 pears. What is the ratio of pears to apples?","In a class there are 2 teachers for every 25 students. Write this ratio another way."],"answers":["5 : 3","2 to 25 (or 25 students for every 2 teachers)"]},{"id":"im-grade-6-math-2-2","title":"Lesson 2: Representing Ratios with Diagrams","steps":["Warm-up: Number Talk: Dividing by 4 and Multiplying by 1/4","Activities: A Collection of Snap Cubes; Blue Paint and Art Paste; Card Sort: Spaghetti Sauce","Practice problems for Lesson 2","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.2 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/2.html"},{"label":"Lesson 2 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-2"}],"questions":["A recipe uses 2 cups of rice for every 3 cups of water. Draw it, then: how many cups in all for one batch?","A diagram shows 4 blue cubes and 12 red cubes. For every blue cube, how many red cubes are there?"],"answers":["5 cups","3"]},{"id":"im-grade-6-math-2-3","title":"Lesson 3: Recipes","steps":["Warm-up: Flower Pattern","Activities: Powdered Drink Mix; Batches of Cookies","Practice problems for Lesson 3","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.3 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/3.html"},{"label":"Lesson 3 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-3"}],"questions":["A drink uses 3 scoops of mix for 2 cups of water. How much mix for a triple batch?","A cookie recipe uses 2 eggs per batch. How many batches use 10 eggs?"],"answers":["9 scoops","5"]},{"id":"im-grade-6-math-2-4","title":"Lesson 4: Color Mixtures","steps":["Warm-up: Number Talk: Adjusting a Factor","Activities: Turning Green; Perfect Purple Water","Practice problems for Lesson 4","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.4 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/4.html"},{"label":"Lesson 4 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-4"}],"questions":["A shade of green uses 2 cups of blue and 5 cups of yellow. What does a double batch need?","Will 3 cups blue and 6 cups yellow make the same shade? "],"answers":["4 cups blue, 10 cups yellow","No, the ratio 3:6 is not equivalent to 2:5"]},{"id":"im-grade-6-math-2-5","title":"Lesson 5: Defining Equivalent Ratios","steps":["Warm-up: Dots and Half Dots","Activities: Tuna Casserole; What Are Equivalent Ratios?","Practice problems for Lesson 5","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.5 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/5.html"},{"label":"Lesson 5 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-5"}],"questions":["Is 12 : 8 equivalent to 3 : 2?","Write a ratio equivalent to 5 : 7."],"answers":["Yes","Example: 10 : 14"]},{"id":"im-grade-6-math-2-6","title":"Lesson 6: Introducing Double Number Line Diagrams","steps":["Warm-up: Number Talk: Adjusting Another Factor","Activities: Drink Mix on a Double Number Line; Blue Paint on a Double Number Line","Practice problems for Lesson 6","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.6 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/6.html"},{"label":"Lesson 6 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-6"}],"questions":["A double number line shows 4 cups flour for 1 cup sugar. How much flour for 3 cups of sugar?","On a double number line, are the tick marks equally spaced?"],"answers":["12 cups","Yes"]},{"id":"im-grade-6-math-2-7","title":"Lesson 7: Creating Double Number Line Diagrams","steps":["Warm-up: Ordering on a Number Line","Activities: Just a Little Green; Art Paste on a Double Number Line; Revisiting Tuna Casserole","Practice problems for Lesson 7","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.7 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/7.html"},{"label":"Lesson 7 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-7"}],"questions":["2 cups paste for 5 cups water. Fill in a double number line: how much water for 8 cups paste?","What should each line of a double number line have in front of it?"],"answers":["20 cups","A label telling what the numbers represent"]},{"id":"im-grade-6-math-2-8","title":"Lesson 8: How Much for One?","steps":["Warm-up: Number Talk: Remainders in Division","Activities: Grocery Shopping; More Shopping","Practice problems for Lesson 8","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.8 student page","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/8.html"},{"label":"Lesson 8 practice problems","url":"https://access.openupresources.org/curricula/our6-8math-v1/6/students/2/practice_problems.html#practice-problems-lesson-plan-8"}],"questions":["5 notebooks cost $15. What is the unit price?","At that price, what do 8 notebooks cost?"],"answers":["$3 per notebook","$24"]},{"id":"im-grade-6-math-2-9","title":"Lesson 9: Constant Speed","steps":["Warm-up: Number Talk: Dividing by Powers of 10","Activities: Moving 10 Meters; Moving for 10 Seconds","Practice problems for Lesson 9","Read the lesson summary and explain it back in your own words"],"links":[{"label":"Lesson 2.9 student page","url":"htt