insert into public.listings (id, seller_name, seller_kind, seller_verified, title, subjects, grade_min, grade_max, philosophies, format, price, description, includes, lessons, lessons_per_week, minutes_per_lesson, parent_involvement, family_style, lesson_steps, cover, color, esa_eligible, created_at, package_id, package_version, license, attribution, outline) values ('l-lib-mcguffey-primer', 'Freerange Library', 'publisher', true, 'McGuffey''s Eclectic Primer', array['phonics', 'reading']::text[], -1, 0, array['charlotte_mason', 'classical', 'traditional', 'faith_based']::text[], 'online', 0, 'The classic first reading book: 52 tiny lessons that add about six new words at a time, from “A cat and a rat” to simple stories and poems. Each day you sound out the new words, read the lesson together, copy a line on a slate or paper, and talk about it. The full text is free online.', array['53 short lessons in 10 units (every Primer lesson, plus the closing slate page)', 'Link to the free full text for every lesson', 'New words and a sound focus for each lesson', 'Slate or copywork line and a narration or picture-talk activity', 'Simple comprehension questions with answers', 'Review lessons every fifth lesson, with script (cursive) reading practice']::text[], 53, 4, 15, 'high', false, '{}'::text[], '🐈', '#E3A33B', false, '2026-11-11T12:00:00.000Z', 'pk-lib-mcguffey-primer', 1, '{"kind":"public_domain"}'::jsonb, 'Lesson plan by Freerange Library for “McGuffey''s Eclectic Primer, Revised Edition” by William Holmes McGuffey (1881), in the public domain. Free full text: https://www.gutenberg.org/ebooks/14642', '[{"title":"Unit 1: Lessons I–V","lessons":["Lesson I: A Cat and a Rat","Lesson II: Ann Has a Cat","Lesson III: Ann and Nat","Lesson IV: The Man and the Lad","Lesson V: Review"]},{"title":"Unit 2: Lessons VI–X","lessons":["Lesson VI: Rab the Dog","Lesson VII: The Frog on a Log","Lesson VIII: The Lamp","Lesson IX: Tom''s Nag","Lesson X: Review"]},{"title":"Unit 3: Lessons XI–XV","lessons":["Lesson XI: The Hen''s Nest","Lesson XII: The Old Fox","Lesson XIII: Nell and the Ducks","Lesson XIV: The Blind Man","Lesson XV: Review"]},{"title":"Unit 4: Lessons XVI–XX","lessons":["Lesson XVI: Sue''s Doll","Lesson XVII: The Bird''s Nest","Lesson XVIII: The Pet Bird","Lesson XIX: Boys at Play","Lesson XX: Review"]},{"title":"Unit 5: Lessons XXI–XXV","lessons":["Lesson XXI: The Owl","Lesson XXII: Cows in the Shade","Lesson XXIII: The Cow with a Bell","Lesson XXIV: The Brave Men","Lesson XXV: Review"]},{"title":"Unit 6: Lessons XXVI–XXX","lessons":["Lesson XXVI: On the Ice","Lesson XXVII: By the Mill","Lesson XXVIII: Skates on the Floor","Lesson XXIX: Look Out for the Cars","Lesson XXX: Review"]},{"title":"Unit 7: Lessons XXXI–XXXV","lessons":["Lesson XXXI: Hard at Work","Lesson XXXII: A Walk in May","Lesson XXXIII: Bess and Her Goats","Lesson XXXIV: The House on Fire","Lesson XXXV: Review: Tom and Bess"]},{"title":"Unit 8: Lessons XXXVI–XL","lessons":["Lesson XXXVI: Miss May''s Rule","Lesson XXXVII: The Schoolhouse","Lesson XXXVIII: The Quail","Lesson XXXIX: Baby Kate","Lesson XL: Review: Henry and Ned"]},{"title":"Unit 9: Lessons XLI–XLV","lessons":["Lesson XLI: The Lighthouse","Lesson XLII: The Sheep and Lambs","Lesson XLIII: The Snow Man","Lesson XLIV: The Bee and Mary","Lesson XLV: Review: By the Sea"]},{"title":"Unit 10: Lessons XLVI–LII and Slate Exercises","lessons":["Lesson XLVI: Work While You Work","Lesson XLVII: John and Watch","Lesson XLVIII: James Drives On","Lesson XLIX: My Dear Puss","Lesson L: Queen of the May","Lesson LI: The Tall Tree","Lesson LII: The Lord Is Near","Slate Exercises and Script Alphabet"]}]'::jsonb)
